TOPIC_SUMMARY_DB: dict[str, str] = {
  "mingGong|贪狼|male": "你活力足、想要的东西多。你会的东西也多，社交能力强，靠个人魅力就能影响一群人。外表好相处，心里其实很硬，认准的事敢下手，也容易上头。最大的麻烦是想试的太多，很难在一件事上待够久，兴头上还容易在感情和钱上冒险。朋友遍天下但交情不深，热得快也凉得快。心里那股不满足是你的动力，也是你最难安静下来的原因。\n\n建议你把力气收到一两件事上。定个年限，比如一个方向先做满五年再谈换。重要决定别在情绪高的时候拍板，睡一晚第二天再定。花钱和感情上给自己设上限，超了就停。朋友里挑三五个真能说上话的深交，其余保持往来就好。你的爆发期在中年，攒下的人脉和手艺往后才真正值钱。",
  "personality|贪狼|male": "你在哪儿哪儿就是焦点。你嘴上功夫好，跟谁都能说上两句，人脉天然就宽，做生意有别人比不了的起手优势。但别人只看到你热络的那一面，你心里其实挺硬：认定的事九头牛拉不回，真要下手也不手软，还容易一时上头不顾后果。你最大的对手是自己想要的太多，年轻时酒和牌桌都容易沾；脑子够用，可劲儿散在太多地方，能到的高度反而到不了。\n\n建议你把选择权用在挑赛道上，而不是每样都试一遍。销售、娱乐、任何需要看人识人的活儿你都拿手，朝九晚五的岗位别硬撑，你坐不住。给自己立两条规矩：不在酒桌上拍板，不在情绪高的时候签字。中年是你的分水岭，收得住心，把年轻攒的人脉换成一两件真做成的事，后半程就稳。",
  "fuQi|廉贞|male": "你在感情上有吸引力，容易被人注意到。感情会不会多波折，不能一见廉贞就断，要看夫妻宫有没有擎羊、陀罗、火星、铃星来加。晚一点结、看准了再定，对你更有利。你投入时很热，要走时也干脆，不会在没指望的关系里耗着，但冲动做的决定事后常后悔。你的妻子多半有自己的特色：才艺好、外表有吸引力，可能做艺术、媒体、法律、军警或跟美感有关的工作，在人群里很扎眼。她在人脉和形象上能间接帮到你，你们两个主意都大，吵起来火气也大。\n\n建议你把结婚这件事往后放一放。先看人品和过日子的底子，别只被感觉带着走。吵架当天不解决问题，等火气下去再谈，这一条对你们特别管用。你的吸引力来自才艺和气场，但关系能不能长久，靠的是愿不愿意把心里话讲出来：定期跟她认真聊一次，比送什么都有用。",
  "guanLu|七杀|male": "你适合在竞争激烈、压力大的地方做事。越是硬仗越有精神。纯文书、纯行政的位子会把你磨钝，带实权、要冲劲的路子才合适，比如军警执法。你是团队里的冲锋队长，推得快、不怕难，但管得硬，又不肯妥协，容易把几个对手逼到一块来对付你。\n\n建议你别在文职上耗着。往有实权、有硬指标的位置走。对手也别一律当敌人，能合作就合作。",
  "caiBo|破军|male": "你的钱是大起大落型的。好的时候来得猛，淡的时候也真淡，别拿一时手头的松紧判断一辈子。固定收入跟着事业变动走，意外之财常在变动里冒出来，抓时机比埋头苦干管用。你赚钱的本事是在变化里找商机，外贸、开拓型销售、新科技、靠一门手艺提供专业服务，都是你的路。守钱的本事偏弱，心情好就大手大脚，一到低谷手头就紧。\n\n建议你在事业顺的时候就把钱分账。一个账户只进不出，工资到手先扣一笔存起来，别等有闲钱再存。大额消费给自己设 24 小时冷静期。投资往自己熟悉的行业里放，别盲目分散，高点时尤其别加码。",
  "jiE|（疾厄空宫|male": "你属于神经敏感的体质。脑子转得太久，身体先扛不住。最容易出状况的是睡眠：心里一堆事放不下的时候，往往先是睡不踏实，人容易累、容易头疼。担心和反复琢磨停不下来，是你最该留意的地方，情绪一紧，身体跟着紧。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天机的五行去配。\n\n建议你把作息固定下来。每天尽量同一个点睡、同一个点起，这一条比什么补品都管用。吃得清淡些，辣的和咖啡因少碰，下午之后别再喝咖啡。运动挑有节奏的——快走、慢跑、游泳、骑车，一周三次、每次半小时，让身体带着脑子降温。每年做一次常规体检，查哪几项听医生安排；身上有不舒服别自己上网查症状吓自己，去看医生，按医生说的做。",
  "xiongDi|太阴|male": "你的兄弟姐妹里，跟女性更亲。姐姐妹妹跟你聊得来，心里话愿意跟她们讲；有兄弟的话，相处偏含蓄温和，很少起正面冲突。合伙这件事，搭档多半心思细、敏感，擅长处理人情，不靠硬碰硬。\n\n要合伙，就找务实能落地的搭档。你出判断、他出执行，事先把出资、分工、分钱写成白纸黑字，别靠交情撑。跟气场硬的人别硬顶，把话放到私下谈，用你看人的长处。家里女性亲人闹别扭的时候，分开住、各过各的，反而比天天凑一块儿舒服。",
  "ziNv|（子女空宫|male": "你的孩子多半性格刚、主意正。孩子从小就像个小大人，不黏人也很少撒娇，心里有情也是用做事表达，不挂在嘴上。这类命里孩子数目偏少，缘分来得也晚一些。你当父亲最容易踩两个坑：一是管得太严，把对孩子好等同于把他练成材，让他童年里没多少暖的记忆；二是拿钱代替陪伴，觉得我挣钱让他过好日子就够了。\n\n建议你把「我说了算」换成「我听你说」。孩子越大越吃这一套，管得紧不如说得开。每周留一段只属于你和孩子的时间，不谈成绩、不谈规划，就是一起玩。嘴上那句「我爱你」在你家里尤其少，值得你硬着头皮多说几次。",
  "qianYi|紫微|male": "你出门在外，会逢到贵人。离开本地，一直守着家门口那个小圈子，你会越待越闷、越焦虑。大城市、沿海或者国外，都比本地更适合你施展。\n\n建议你 35 岁之前争取一段离开本地的经历。外派、留学、跨城调动都行，这段经历往往决定你后面能走多宽。已经成家的话，可以把事业重心放在大城市，家安在离得近的二三线。到了新地方别只顾埋头做事，主动认识人、请人吃饭，把在外面的关系网铺起来——一个人在外终归孤单，你缺的不是本事，是有人接得住你。",
  "jiaoYou|天机|male": "你朋友多、路子杂。什么人都能聊上几句，是那种谁都认识你的类型；但真正能交心、能托付事情的，掰着手指也数得过来。你最容易被那种话讲得漂亮、场面做得足的人吸引，也最容易在这种人身上吃亏——他答应得快，做起来就没影了。\n\n建议你把朋友分三层来处。一般的朋友尽量多交，用来听消息；能交心的挑两三个，长期用心处；重要的事没定下来之前，在别人面前一个字都别提。判断一个人别听他怎么说，看他上一件答应你的事有没有做到。合作前把分工和分账讲在明面上，关系再好也照做。",
  "tianZhai|太阳|male": "你的家业跟祖上连得紧。祖上留下的荫泽，你承得到。\n\n接到手的祖产，先守住再说。家里别长期冷冷清清，多开窗，也多请朋友来坐坐。",
  "fuDe|武曲|male": "你的快乐很实在。事情做成了、账上有具体数字，心里才踏实；没有的时候就发慌。你是个闲不下来的人，没事也要给自己找事，忙是常态，好在忙得多半有回报，年纪大一些反而能松下来。那种谈心灵、谈境界的东西在你这儿不太起作用，你要的就是把事办成、把钱攒下的踏实感。\n\n建议你给自己找一两样跟钱完全无关的爱好。爬山、钓鱼、写字、收藏都行，算不出回报的事，恰恰最解你的心慌。每天留半小时不看手机、不想工作的时间，身体动起来的那种放松对你更管用。",
  "fuMu|天同|male": "你父母多半脾气温和、疼你多过骂你。家里气氛不紧张，这是你很实在的一份底气。但这份疼爱也是个坑：什么都有人替你安排，你自己的动力就被磨掉了。职场上你跟和气的上司配合最顺，碰到强势的容易被压住。\n\n建议你主动断奶。三十岁前自己养活自己，三十五岁前自己安排住处，四十岁前把家里该扛的事接过来。长辈给的帮助可以收，但别让他们替你做决定。四十五岁以后，主动给二老安排每年一次体检，有问题按医生说的办。跟强势的上司相处，把事做完后当面讲清楚进度，别等着被问。",
  "mingGong|贪狼|female": "你是那种走进屋里会被多看一眼的女性。你才艺多、会玩会聊，身边从来不缺人围着。追你的人多，可真正值得托付的没那么多，热闹里最需要的是你自己那份清醒。你天生什么都想试一试，日子过得比别人精彩，也比别人碎。前半辈子多半在体验和折腾中度过，真正的沉淀和成绩，往往要到后半程才显出来。\n\n建议你尽早挑一两件事往深里做。把外形和人缘带来的机会，换成一门能吃一辈子的手艺或者一个自己的牌子。艺术、娱乐、美容、跟人打交道的行当都适合你，但别只靠魅力这一条腿走路。感情上给自己定个筛选标准，比如认识满半年再谈定下来。钱上留一笔不动的，热闹归热闹，账上得有底。",
  "personality|贪狼|female": "你身上有种让人多看一眼的劲儿。这不一定是长得多好看，是那种活泼、灵动、路子又宽的气质，身边从来不缺人。这份魅力是天赋也是考验：你容易吸引人，但只将亥、子两宫的贪狼算正科桃花，感情线不能一见贪狼就往缠绕上断。你不是不专情，只是天生对新鲜敏感，老路走久了会觉得闷。也别被你柔和的外表骗了，你心里有把很硬的尺，认定了谁劝都没用。\n\n建议你别为「感情复杂」给自己扣帽子。与其憋着，不如把这份劲儿放进能一直给你新鲜感的行当：娱乐、时尚、媒体、销售，这些地方容不下无聊，正合你。感情上给自己设个观察期，心跳归心跳，先看这个人能不能陪你过第二天的早饭。真遇到让你心服口服的那一个，你其实比谁都忠诚。",
  "fuQi|廉贞|female": "你在感情上不是随便动心的人。你标准高、看人看得细，跟谁都不轻易走太近，别人对你多是敬重。一旦认定了就很坚定，守得住。适合你的丈夫要有气质、有内涵，看得懂你的才华，也容得下你的独立，光被外表吸引的那种走不长。你晚一点结婚，质量反而更好。这是生年带来的底子，哪个十年、哪一年被引动，要再看运限。\n\n建议你别急着把终身大事定下来。先看这个人怎么对待家里人、怎么对待钱，这两处最看得出底细。相处上可以主动一点：你习惯端着，对方常常读不懂你在想什么，把自己想要什么直接说出来，比等他猜有用得多。真碰上让你为难的关系，把界线讲明白、把距离拉开，别怕被说不近人情。",
  "guanLu|七杀|female": "你适合在竞争激烈、压力大的地方做事。越是硬仗越有精神。掌事、拍板、带人本来就是你的强项，在这种位置上你的能量才用得出来。纯文书、纯行政的岗位会把你磨钝，带实权、要冲劲的路子才合适，比如军警执法。你推得快、不怕难，但管得偏硬，容易让下属有压力。\n\n建议你把重心放在事业上。这对你不是遗憾，是最顺的那条路。往有实权、有硬指标的位置走，别在文职上耗着；真要创业，找一个心细、能收尾的合伙人补上你这块。管人的时候多说一句为什么，让人服而不是让人怕。",
  "caiBo|破军|female": "你的钱是大起大落型的。跟着事业的起落走，好的时候来得猛，淡的时候也真淡。你赚钱的本事在走出去三个字上：跨境电商、翻译、国际贸易、海外咨询、跨城市发展，都是你的天然财路，最怕守在一地做一份一成不变的工作。花钱这块你比多数人都随性，看到想要的就下单，事后又后悔。你对独立账户的安全感看得很重，不太甘心只做家里的管账人。\n\n建议你给自己设 24 小时冷静期。想买的先放购物车，隔一天再决定。工资到手先扣一笔转进只进不出的账户，别等有闲钱再存。家庭财务上与其硬凑一个共同账户，不如把各自赚各自管、大项一起出谈明白，写下来。投资只碰自己熟的行业，高点别加码。",
  "jiE|（疾厄空宫|female": "你属于神经敏感的体质。脑子转得太久，身体先扛不住。最容易出状况的是睡眠：心里放不下事的时候，先是睡不踏实，人容易累、容易头疼。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天机的五行去配。情绪和身体是连着的——压力大、心里憋着火的那阵子，月经容易不太规律，来之前脾气也变大。怀孕那段日子和更年期那几年，情绪起伏会更明显，心里先有准备就不慌。\n\n建议你先把作息固定下来。每天尽量同一个点睡、同一个点起。吃得清淡些，多吃蔬菜，辣的少碰，下午之后别喝咖啡。运动挑有节奏的：快走、慢跑、游泳、骑车，一周三次、每次半小时，最能把火气排掉。每年做一次常规体检，把睡眠、情绪、月经的变化记在手机里，看诊时给医生看；心慌、出汗多、体重忽上忽下，就按医生的建议去做检查，别自己上网查了吓自己。",
  "xiongDi|太阴|female": "你跟姐妹之间的情分特别重。姐姐妹妹往往是你一辈子最深的女性盟友，心里话跟她们说得最透。婚后跟嫂子弟媳相处，你的温柔很讨人喜欢，容易成为大家的情绪出口，但也容易被消耗。\n\n跟人合伙最怕感情账和利益账混着算。真要一起做事就按项目来，一件事一本账，出资、分工、分钱事先写明白，谈钱的时候把姐妹情放一边，事情反而长久。别人来倒苦水，你给自己设个时限，听半小时可以，别把人家的事扛成自己的心病。跟家里女性亲人闹别扭的时候，各过各的，比天天凑一块儿舒服。",
  "ziNv|（子女空宫|female": "你的孩子多半性格刚、主意正。孩子从小就像个小大人，不黏人也很少撒娇。这类命里孩子数目偏少，缘分来得也晚一些。你当母亲最大的难处不在能不能给：物质条件、升学规划你都安排得又稳又细；难的是说出口的那部分，一句「我爱你」、一个拥抱，对你来说像是另一门语言。可孩子最想要的，恰恰是这个。\n\n建议你把感情当动作来练。每天一个拥抱，每周留一段只陪孩子、不谈成绩的时间，生日认真过一次。把「我安排」换成「我们商量」，孩子越大越吃这一套，冲突会小很多。",
  "qianYi|紫微|female": "出门在外，你会逢到贵人。离开本地，家里人情压力越大，你在外地越松快。到外地、国外生活或者跨地区的婚姻，对你都比守在原地合适——让你安分待在家里相夫教子的剧本，你多半演不下去。\n\n结婚之前，有外派、留学、跨城工作的机会就果断去。这段一个人闯的经历是你往后底气的来源。已经结婚了，别把自己整个挂在丈夫的路线上，留一份属于自己的工作空间，哪怕是远程也行；两地跑不丢人，全盘依附才容易出问题。到了新地方主动认识人、请人吃饭，把在外面的支持圈子铺起来。",
  "jiaoYou|天机|female": "你的朋友圈是两层的。外面一圈很宽，谁都能聊上几句；里面真正交心的，就那么两三个。这是你的本性，不用勉强自己把每个人都处成挚友。要留神的是那种很会包装自己、张口就是“咱俩谁跟谁”的人，感情牌打得响，办起事来未必靠谱。男性朋友里你容易遇到聊得特别投的知己，但聊得太深容易越线，在外人眼里也容易被误会。\n\n建议你把别人嘴上答应的话先在心里打个折。看他上回答应的事有没有做到，再决定信几分。交心的朋友有两三个就够，长期用心处。跟异性朋友相处，把边界摆在明处：单独见面少些，不碰对方的家务事，也别把自己的私事全倒出来。重要的事没定之前，在一般朋友面前别提。",
  "tianZhai|太阳|female": "你的家业跟祖上连得紧。祖上留下的荫泽，你承得到。\n\n接到手的祖产，先守住再说。家里别长期冷冷清清，多开窗、多添灯，也多请兄弟朋友来坐坐，人气足了，住着的感觉就不一样。",
  "fuDe|武曲|female": "你的踏实感是钱给的。账上有具体数字才睡得着，数字见底就发慌。你是个闲不下来的人，没事也要给自己找事，好在忙得多半有回报，年纪大一些反而能安下来。这种务实不是肤浅，反而是最稳的一种活法：你不会因为想不通人生意义而消沉，但会因为账户清零而睡不着。\n\n建议你每天留一段不算回报的时间。哪怕只有半小时：散步、瑜伽、太极这种身体动起来的放松，对你这种闲不住的性子最管用。跟自己赚钱的本能和解，不用逼自己看淡，只是别让它二十四小时开着。",
  "fuMu|天同|female": "你父母多半脾气温和、疼你多过骂你。家里气氛松快，这是你一辈子的底气——被好好对待过的人，才会对这个世界有基本的信任。婚后跟公婆也容易处得来，你的温柔在长辈那儿吃香。坑在于你太想让所有人都满意，一路讨好下来，自己的想法就没地方放了。\n\n建议你在长辈面前守住一条线。尊重不等于讨好，关心不等于牺牲。不想做的事温和地说清楚，比忍着做完再委屈强。跟公婆之间的事，让你先生出面去讲，别自己硬扛。四十五岁以后主动给二老安排每年一次体检，有问题按医生说的办。父母之间要是爱拌嘴，多半也是吵归吵、情分还在，不用太担心。",
  "mingGong|武曲|male": "你是典型的实干家。你做事直接，不爱绕弯子，看重的就是效率和结果。你对数字、资产、实际利益天生敏锐，别人还在开会讨论，你已经动手做了。缺点是不太会表达感情，跟人相处容易显得冷或硬，有时话太直伤到人，自己还不知道。你脾气来得急，但一发就过去，不记隔夜的气，旁人被吓一跳，你早翻篇了。你不擅长应酬客套，朋友不多但都靠得住。压力越大你反而越冷静，关键时刻身边也常有人出手拉你一把。\n\n建议你刻意把语气放软。提意见前先讲一句认可，同样的话对方就不觉得是被你压着走。做重要决定时别只凭一口气，先放一晚上再拍板，你的失手多半来自太自信、推敲不够。家里人那边别只顾埋头做事，每周专门问一句他们过得怎么样。",
  "personality|武曲|male": "你不是话多的人，别人聊一小时的事，你三句话讲完。不是冷淡，是你脑子里动手永远排在开口前面：能解决的事就不在嘴上磨。你爱一个人的方式是给安全感，稳定的收入、说到做到，而不是甜言蜜语，所以在感情里常被说成木、说成硬，其实你心里在意得很，只是讲不出来。脾气上你来得急也去得快，不记隔夜的气。你最受不了的是含糊不清，事情非黑即白你才舒服。\n\n你有个自己常忽略的本钱。学东西上手快、会的门类杂，想转行、想多学一门手艺都不难。真正要补的那一课很简单：把心里在意的话说出来，一句「我担心你」，比你默默多做十件事更容易被家里人接到。跟人有分歧时，先问清楚对方的意思再下判断，别急着下对错，很多误会就是这么省掉的。",
  "fuQi|（夫妻空宫|male": "你在感情里温柔体贴。你愿意为了不起争执先退一步，跟你在一起的人会觉得舒服、没压力。你不太看重对方的家底，更在意两个人合不合得来、日子过得暖不暖。你太太多半性格温和、会过日子，可能做服务、设计、餐饮这类跟生活美感有关的工作，能把家布置得让人待着不想走。她不一定帮你在外面打天下，但你累了回家能缓过来。你们都不爱吵，问题反而出在太安逸，久了容易没热度。\n\n婚事不用赶，你晚一点成家反而更稳。古书说天同在夫妻宫夫宜年长、妻宜年少，你比她大一些相处更自在；这是参考，不是硬条件。日常别把「不吵架」当成感情好，主动安排点两个人一起做的新事——出去旅行、学一门手艺、换个地方住一阵都行。她提要求时别一味答应了事，把自己的想法也讲出来，感情才不会变成你一个人在迁就。",
  "guanLu|紫微|male": "你走的是靠位置吃饭的路子。你坐在有头衔、说了算的岗位上，比在底下做执行更能发挥。政府机关、司法、大公司管理层、金融机构高层这类地方最适合你。你擅长定方向，不喜欢也不擅长琐碎细节，需要能干的人替你落地。比起自己创业，你更适合在大平台上借势，靠职位和固定薪水稳稳往上走。你的收入跟位置挂钩，位置越高钱越厚，升职比跳槽更能改善收入。\n\n职场上你容易端着。你跟同级暗暗较劲，对下属又压得太紧。建议你把姿态放低半格：管事严一点，待人温一点，留住人比赢过人重要。定期找个敢跟你唱反调的下属聊聊，问他哪儿不对。公司有调动机会要争取，这类节点往往就是你往上走的台阶；年纪比你长、位置比你高的人容易成为助力，值得主动走近。",
  "caiBo|廉贞|male": "你的钱是一阵一阵来的。不是细水长流：好的时候进得很快，淡的时候也能淡很久。钱多半从人多热闹的场子里来，你的才艺和名气能换成钱，演出、设计、顾问、自己开店都算。你管钱的本事偏弱，看到好看的、享受的东西就容易松手，真正的大漏点是感情上的花销、冲动买单，还有打官司和摆平麻烦的开销。化禄（进财）的年份进账顺。\n\n建议你在赚得多的时候就先把钱分走。固定一笔转进不轻易动的账户，剩下的再花。大额支出给自己定个规矩，超过多少就隔三天再决定。别碰你看不懂的高风险东西，把钱放回自己擅长的行当更实在。跟钱有关的事，白纸黑字写清楚，能省掉后面很多麻烦。",
  "jiE|天梁|male": "你的底子不错，生病也恢复得快。问题恰恰出在太能扛——身体早就发过信号，你觉得还撑得住，就这么过去了。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天梁的五行去配；长期绷着，最先出状况的是睡不好。你习惯自己扛、不开口求助，攒下来的孤单和压力，往往到中年前后一起冒出来，表现成容易累、睡不踏实。\n\n建议你每年做一次全面体检。体检时顺带认真答一次情绪方面的问卷；身体有不对劲的地方及时看医生、按医生说的做，别自己扛着上网查。吃饭按点吃，少碰太凉的。运动挑缓和的，瑜伽、太极、爬山都行，最好拉上人一起，一边活动一边把闷着的话说出去。还有一条最难也最管用：难受的时候找个人讲讲，允许别人帮你。",
  "xiongDi|天同|male": "你跟兄弟姐妹处得不错。你们都是不爱吵的性子，过节聚一聚气氛融洽，真要一起做点事，你这边是加分的。麻烦出在界线上：兄弟姐妹彼此都随和，借钱、帮忙、做担保这类事常常顺口就应下来，事后才后悔。\n\n建议你把亲情和钱分开算。感情可以亲，借钱写个凭据，合伙签份合同，谁出多少、怎么分，开头就讲清楚。做担保这种事直接说不做，不用解释。真要一起干，挑餐饮、休闲娱乐、服务、艺术这类路子，比拼硬功夫的行业更合你们的性子。",
  "qianYi|天相|male": "你出门在外运气不差。总有人愿意拉你一把、给你指条路。但你不是那种背个包去陌生地方白手起家的类型，你的路子是到外地之后，进一个稳定的地方慢慢往上走——大公司、机关单位、专业机构，按部就班升迁，才是你的正路。一个人在外久了，你容易生出一种什么都做不了主的孤单感。\n\n建议你换城市之前先把去处定下来。先有单位、有岗位再动身，不要先辞职再去碰运气。最不适合你的是去外地从零开始创业，你擅长的是接手别人已经打下的摊子，把它做稳做大。已经成家的，尽量别长期两地分居；真要分开一段时间，固定每周通话、定期回去，家这个后盾对你很重要。",
  "jiaoYou|巨门|male": "你的朋友圈不大但深。古书说巨门在这一宫「多怨逆」，身边的人怨气多、爱唱反调，几句话就疏远的事常有。\n\n建议你对真正在乎的朋友学会让一步。不是输，是给这段关系留条活路。朋友诉苦的时候先听完、先接住情绪，别急着分析对错。酒桌上少喝两杯，你酒后一句话最容易闯祸。合伙的事跟交情分开算，该签的字一样要签。你自己是讲规矩的人，要防的是交错人，不是你自己会出问题。",
  "tianZhai|天机|male": "家里的老房子、老底子你多半守不住。你也不用惦记——属于你的家业是自己重新挣、重新买的。房子对你更像一件随时能换的资产，不是非得在一个地方扎一辈子根。\n\n建议你别把钱全压在一套超出需要的大房上。留一部分在能随时动用的地方。选房优先挑好脱手的——地段熟、户型常见、转手快，比一步到位重要。装修上选能改的：家具能挪、隔断能拆，别做满做死。要是最近两年搬家太频繁，先稳稳住上三年再谈换房，人先安定，事才理得顺。",
  "fuDe|天府|male": "你的安心是拿看得见的东西垫出来的。账户上的余额、房本、保险单，这些东西在，你心里才踏实。跟那种嫌自己赚得不够多的焦虑不一样，你怕的不是没赚到，是已经有的会丢。日子安静，你的福气就在；一乱起来，你就得操着心过。\n\n你一辈子最重的担子是想把所有事都攥在手里。可人生本来就攥不住。建议中年以后找一件重复而有节奏的事：打太极、静坐、慢瑜伽都行，一周三次，把脑子从算计里拔出来。风险想到能接受就停，别一遍遍推演最坏的情形。钱上定一条底线，只要这条线不破，剩下的就不再算了。",
  "fuMu|太阳|male": "你父亲多半是个体面、要强的人。他从事公职、教书、行医，或者自己干出一番事业，对你也有期待，希望你在外头给家里长脸。你们父子相处偏正式，话说得客气，真正交心的时候不多。你跟上司的相处基本是父子那套的翻版，碰上同样强势的领导，最容易为了谁露脸而别扭。太阳落陷（力量弱）时，古书说「陷地克父」，父母两人里先克父亲。\n\n建议你把台面上的功劳让给领导。你自己拿口碑：对外让他体面，对内让人知道事是你办成的。跟父亲也一样，少争对错，多问他近况，尤其留意他的心脏、眼睛和血压，五十岁以后劝他定期体检。化忌（阻碍）时，父亲或上司那边容易出公开的是非，那阵子话少说、字少签。",
  "mingGong|武曲|female": "你是事业上的铁娘子。你做事果决干脆，不绕弯子，效率和结果就是你的标准。你对数字和钱天生敏锐，赚钱能力在十四颗主星里排得很靠前，在实业和金融这类地方最能发挥。你这股刚气用在事业上是本钱，用在感情里就容易把人挡在外面：你不装柔弱，也不肯将就，不少男人因此不敢靠近。你朋友不多，但都靠得住，关键时刻身边也常有人出手帮一把。\n\n建议你把事业当主线，放开了做，这是你最稳的底气。感情上别把标准端得太死，合不合拍比条件漂不漂亮更要紧，遇到能跟你一起往前跑的人，给自己一点时间慢慢试。跟人说话时多加一句认可，你的强硬就没那么扎人。也给亲近的人留一道口子，让他们知道你其实也需要人疼。",
  "personality|武曲|female": "你做事比多数人狠，决定来得快。撒娇这件事对你来说几乎是另一门语言，不是不想学，是练不出来。你从年轻时就明白，自己有本事比依赖谁都靠得住，这让你在事业和钱上格外稳。代价是在亲密关系里容易把人推开：你不需要被照顾，对方就不知道该从哪儿靠近你。脾气上你来得急也去得快，不记隔夜的气，旁人还没缓过来，你早翻篇了。\n\n你这股刚气是本钱。它用在事业上极占便宜，不用为了讨好谁把它磨掉。要补的只有一道口子：在亲近的人面前，允许自己说一句「我有点累」。示弱不等于输，它只是给对方一个进来的门。跟人相处时，先听完再判断，别急着给结论。硬了二三十年，还能让一个温和的人靠近你而不被吓退，这本身比赢更难，也更值。",
  "fuQi|（夫妻空宫|female": "你在感情里温柔体贴。你凡事以和为贵，为了不起争执愿意先退一步，跟你在一起的人会觉得放松、没压力。你不太看重对方的条件，更在意两个人过日子合不合拍。你先生多半性格温和、懂得享受生活，可能做服务、艺术、设计、餐饮这类跟美感有关的事，把家过得舒服是他的长处。他不一定在外面替你冲锋，但你累的时候他能给你缓过来的力气。你们都不爱吵，问题反而是太平静，久了容易没劲。\n\n婚事不用赶，晚一点成家对你反而更稳。古书说天同在夫妻宫夫宜年长、妻宜年少，对方比你年长一些相处更自在；这是参考，不是硬条件。日常别用一味迁就去换和气——你不说，他是真的不知道。有想法就当场讲，讲完照样可以温柔。两个人要有一起做的新事，出去旅行、学点什么、换个环境住一阵都行，感情才不会停在原地。",
  "guanLu|紫微|female": "你适合坐在有头衔、说了算的位置上。政府机关、司法、大公司管理层、金融机构高层都合适；你擅长定方向，不耐烦琐碎细节，需要能干的人帮你落地。事业这条线通常比感情顺，你也很难只满足于家里的角色。难处是女人特有的：生孩子的时间常和事业最冲的那几年撞上，往上走还有一层看不见的天花板。你的气场在职场是优势也是隐患——下属敬你却不敢真跟你走，男性同级要么躲开，要么暗地里较劲。\n\n建议你主动找几位信得过的女性伙伴结成同盟。别照搬男高管那一套。对下属把姿态放低半格：管事严一点，待人温一点，敬畏留不住人，认同才行。生孩子的节奏，等事业站稳一点（30 岁以后）再规划更从容。公司有调动机会就争取，多半是往上走的台阶。",
  "caiBo|廉贞|female": "你的钱是一阵一阵来的。好的时候进得快，淡的时候要熬一阵。钱多半从你的才华和人气里来，设计、演出、顾问、自己的牌子，都算你的路子。你管钱偏弱，花在好看的东西上最容易松手，衣服、艺术品、家里的陈设常常是大头。最要留意的是感情上的花销：你认真投入起来，容易为对方大笔往外掏。化禄（进财）的年份进账顺。\n\n建议你不管跟谁在一起，都给自己留一个独立账户。再留一笔随时动得了的钱，这是你这一生最实在的底气。进账多的时候先转走一笔固定的再花。给对方的大额支出，超过一个数就先放三天再决定；涉及借钱、担保、一起买房，白纸黑字写清楚。别碰你看不懂的投资，把钱放回自己熟的行当更稳。",
  "jiE|天梁|female": "你的底子不错，恢复力也好。问题出在太能扛——身体早就发过信号，你觉得还撑得住就过去了。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天梁的五行去配；长期绷着，最先出状况的是睡不好。你习惯自己扛、不开口求助，压着的情绪会反映到身上：月经不规律、量偏少，常常就是这么来的。你偏向晚一点结婚生孩子，备孕可能需要更长时间，生完之后的情绪低谷也要当心。\n\n建议你每年做一次全面体检。体检时顺带认真答一次情绪问卷。要准备怀孕，尤其过了三十五岁，早点找专业医生做评估，按医生说的来，别自己在网上翻答案。吃饭按点吃，少碰太凉的。运动挑缓和的，瑜伽、太极、爬山都行，最好拉上人一起。最要紧的是给自己养一个能说心里话的小圈子，难受时有人接得住。",
  "xiongDi|天同|female": "你跟兄弟姐妹处得和睦。你们都是不爱吵的性子，有事互相搭把手。但家里一有难处，第一个被想到的往往是你——借钱、临时帮忙带孩子、托你介绍工作，你几乎不会拒绝。婚后跟妯娌之间也是这样：你的温柔在家里讨喜，可越是会哭会闹的人，越容易从你这儿拿到好处。\n\n建议你学着说不。这不是冷漠，是给自己留点力气——你先站稳了，才帮得了别人。钱上的事丑话说在前面：借多少、什么时候还，写清楚；真要一起做生意，合同签好，账目交给一个更实际的人来管。答应帮忙前先问自己一句：这事我做了，接下来一个月会不会更累？会，就直接说这次不行。",
  "qianYi|天相|female": "你出门在外运气不差，总有人愿意拉你一把、指条路。但你不是背着包去陌生城市白手起家的类型，你适合的是到了外地之后，进一个稳定的地方慢慢站住脚。远嫁对你是把双刃剑：你得体、稳重，融进婆家的圈子不难；可一旦娘家不在身边，你的好脾气容易被当成软弱，事事被人拿捏。\n\n建议你远嫁或长期外派之前，先老实问自己三个问题。没有娘家帮忙，我能不能独自应付婆家的人和事？能不能自己拿主意管钱？能不能一个人把孩子带起来？有一个答案是不能，就再想想，或者先把这一项补上。换城市之前把工作定下来再动身。",
  "jiaoYou|巨门|female": "你的朋友圈重质不重量。你不爱泛泛之交，宁可少也要深。早年的朋友和下属多半帮不上什么忙，是非倒不少，也留不长久。古书说巨门在这一宫「多怨逆」，身边的人怨气多、爱唱反调。\n\n建议你对真正在乎的朋友先共情、后分析。她诉苦的时候要的是被听懂，不是被解决，先说一句「换我也难受」，再谈怎么办。别把朋友当案例研究，关系需要一点不讲道理的温度。真在乎的人学会让一步，不是输，是给关系留条活路。你的男性朋友数量不多，但往往是有事真会到场的那种，值得好好维持。",
  "tianZhai|天机|female": "家里长辈留下的房子、老底子，你多半守不住。你也不用惦记，属于你的那份家业是自己买下来的。你对家的感觉偏向暂时落脚，不是一辈子扎根：今天觉得这套房完美，过几年就嫌它不合用。\n\n建议你别把钱全压在一套大房上。婚前买房优先挑小一点、好脱手的。跟丈夫一起买房，出资比例和名字怎么写，提前讲清楚，白纸黑字比嘴上说说踏实。装修的事分工来：谁在意谁定，别两个人在每个细节上较劲。最要紧的一条是给自己留一块独属的空间，书房、阳台、一个角落都行，没有这块地方，你的心思会被家务和家人的说话声淹没。",
  "fuDe|天府|female": "你的安心是靠看得见的东西垫出来的。已有的积蓄、稳固的家、靠得住的几段关系。日子安静，你的福气就在；一乱起来，你就得操着心过。你的焦虑比表面看着深得多，外人往往只看到你一脸平静。\n\n建议中年以后安排一件重复而有节奏的事。静坐、太极、慢瑜伽，或者园艺、烘焙都行，一周三次，把脑子从算计里拔出来。更要紧的是交两三个能说心里话的女性朋友，定期见面把心事讲出来，比一个人硬扛管用得多。风险想到能接受就停，别一遍遍推演最坏的情形。",
  "fuMu|太阳|female": "父亲在你这一生里分量特别重。他多半是个要强、有名声、扛得住事的人，是你最早见到的男人样板，你后来挑对象的标准，很大程度上是照着他来的。太阳落陷（力量弱）时，古书说「陷地克父」，父母两人里父亲先克。化忌（阻碍）时，父亲那边容易出名声上的波折，他晚年也容易多些波折。\n\n建议你从父亲五十岁起就主动关注他的身体。尤其留意心脏、血压和眼睛，定期劝他体检，有不舒服就陪他去看医生，别等出了事才后悔。还有一件事：结婚以后你多半会不自觉地拿公公跟亲爹比，比来比去总觉得差点意思——这层滤镜要自己有意识地摘掉，把公公当普通长辈相处就好，不用指望他像你爸那样。",
  "mingGong|天同|male": "你脾气温和、不爱跟人争。你走到哪儿都能很快找到让自己舒服的节奏。你最大的本钱是人缘：跟你相处的人都放松，所以凡是要一群人合力才做得成的事，你往往是最关键的那块黏合剂，跟人搭伙做比一个人硬扛容易成。你心里其实有主意、也有志气，只是懒得摆到台面上去争。弱点是太容易满足，该争的时候习惯让一步，久了会被当成没主见；做决定也慢热，被人催着当场拍板时最容易失手。\n\n建议你给自己定几个具体的目标和完成时间。别只等着机会送上门。合作的事多接，尽量跟有冲劲的人搭伙，让他带着你往前跑。碰上该争的场合，先想清楚自己要什么，再把话说出口，哪怕一次只说一句。需要当场定的事，提前把选项和底线列好，别让别人催着你做决定。",
  "personality|天同|male": "你大概是最不容易跟人结仇的那种人。你脾气好、不争不抢，跟谁都聊得来。这份人缘是实打实的本钱：很多事你自己办不成，拉着你一起办的人却办成了。你不是没想法，只是不肯拿出来跟人抢。麻烦也在这儿：你没有非把什么事做成不可的那股劲。年轻时「不太拼也过得去」很舒服，等身边的人一个个走到前面，你心里也会打鼓。长辈疼你、朋友帮你、家里人替你操心，这份好也容易把你困住。\n\n建议你每年主动挑一件让自己不舒服的事做。换个岗位、接一个没把握的项目、学一门要下笨功夫的手艺都行。给目标写上完成日期，再告诉一个会追问你的人。你的底子偏安稳，后半程多半不缺日子过，真正缺的是四十岁之前这些年，有没有替自己挣下点东西。",
  "guanLu|天机|male": "你靠脑子和应变吃饭。最能发光的不是埋头执行，而是出主意、定方向、给人当参谋。公职、内勤、咨询顾问、教育培训、科技研发、媒体策划、数据分析这些地方最适合你；领一份固定薪水、把本事用在方案和判断上，比自己扛风险稳得多。你在团队里常是提出新视角的那个，但把事情从头推到尾不是强项。帮你的人多半是比你有阅历的前辈、老师或行内高手。\n\n建议你别急着自己开公司。先在一个好平台上把专业名声做起来，收入涨得更快；真要自立门户，一定要找一个做事落地的合伙人补上执行这块。兴趣广是好事，但要挑一个方向扎下去，别什么都会一点、什么都不精。重要的事情上，想法定了就别改来改去，别人才敢把活交给你。",
  "caiBo|天梁|male": "你的钱不是靠量大，是靠口碑好。收入稳、有保障，但整体量级不会特别高，属于慢慢往上走的类型，中年以后随着名声攒起来，会上一个明显的台阶。你赚钱最顺的方式是把肚子里的学问变成钱，比如做顾问、带培训、做法律医疗这类专业服务，或者写东西出书。你花钱不讲排场，管得住手。漏财在两处：对人太讲情义，钱和精力往外送；太守自己那套规矩，错过本来能挣的机会。\n\n建议你先把价码抬上来。对着同行的行情算一遍，该涨就涨，很多人跟你一样本事不差却一直报低价。投资走稳的路子，长期拿得住的东西适合你，高风险的短线别碰。帮朋友先给自己定个上限，超出就直说。每年抽一天把收支算清楚，别凭感觉过日子。",
  "jiE|天相|male": "你的底子偏温和。整体还不错，但起伏比较明显，累久了容易一下子垮。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天相的五行去配；长期久坐加上工作压力，颈椎和腰椎也容易出问题。情绪对你影响特别大：委屈往心里咽，表面看着平和，其实一直扛着，长期不疏解，身体是最先撑不住的那个。\n\n建议你每年定期体检。《全书》卷二疾厄天相条说「天相灾少面皮黄肿血气之疾」，大病少，面色、皮肤和气血要看着，加上久坐伤的颈椎腰椎，体检时一并跟医生提；身体不舒服及时看医生、遵医嘱，别自己扛着拖。日常多喝水，吃得清淡一点，少油少盐少辛辣。坐一小时就起来活动五分钟，做做颈肩和腰背的拉伸，再配一点快走、游泳这类不激烈的有氧。心里憋着的事就找人说出来，需要的时候找专业的人聊一聊，这对你比吃什么都管用。",
  "xiongDi|（兄弟空宫|male": "你跟兄弟姐妹处得不错。你们都是不爱吵的性子，过节聚一聚气氛融洽，真要一起做点事，你这边是加分的。麻烦出在界线上：兄弟姐妹彼此都随和，借钱、帮忙、做担保这类事常常顺口就应下来，事后才后悔。\n\n建议你把亲情和钱分开算。感情可以亲，借钱写个凭据，合伙签份合同，谁出多少、怎么分，开头就讲清楚。做担保这种事直接说不做，不用解释。真要一起干，挑餐饮、休闲娱乐、服务、艺术这类路子，比拼硬功夫的行业更合你们的性子。",
  "ziNv|廉贞|male": "你的孩子不会太多，但一个顶一个聪明。从小就有点看不透，心思细、感受力强，多半在艺术、文学这类地方先冒出天分。要留心的是孩子感情上开窍早，青春期的心事和跟人相处的摩擦会比同龄人多一些。化禄（进财）的时候，孩子的才华容易被人看见；你自己脾气硬，当了爸爸容易先摆要求，父子之间话不多，容易各自较劲。\n\n建议你早一点跟孩子聊感情、聊身体。也聊跟人相处的分寸，别避讳，讲得越早越自然。孩子的艺术天分尽量支持，硬压下去往往换来情绪上的问题。跟孩子尤其是儿子相处，少用命令，多问一句他怎么想；每周留一段只属于你们俩的时间，哪怕只是一起吃个饭、打场球，都比讲道理管用。",
  "qianYi|巨门|male": "你到了外地心不太容易定下来。跟人相处总差一口气，是非也跟着来。好处是你的口才能让你在陌生地方很快立起专业形象，跑客户、做异地拓展是你的强项；坏处是人生地不熟，你的话特别容易被人会错意。\n\n建议你在外地说话比在家里更收着点。同样一句直话，本地人知道你什么脾气，外地人可能当成挑衅。出差、远行期间不急着签合同、不轻易替人做担保，拿不准的文件带回来找人看过再签。到一个新地方先认识一两个本地人，把这里的规矩问清楚，比你自己慢慢摸索省事得多。",
  "jiaoYou|紫微|male": "你身边有分量的人多。朋友和下属里有身份、有地位的不少，来往偏正式。古书说这一宫紫微「成行得力，旺主生财」，手底下能聚起一批用得上的人，还能替你把钱挣出来。同一部书又把奴仆宫列为紫微的陷宫，说「虽得助亦不为福」，两种说法并存，用人别全押在别人身上。这些人分量重，端着架子反而容易失人心。\n\n管事严、待人温，这两样得同时来。批评只对事，事后补一句私下的关心。每年认真带一两个人，比到处加微信有用得多。跟同辈朋友别只在工作场合见面，主动约饭、约球、约爬山。有人替你办成了事，记得当众把功劳分出去，你少不了什么，人心却能留住。",
  "tianZhai|天府|male": "房子是你最重要的一笔家当。祖上留下的你守得住，自己攒钱买的也守得旺，你尤其擅长接手一份现成的产业并守好它。\n\n建议大额的买房决定，先请专业法务把合同看一遍。产权、抵押、交房时间逐条核清楚。二手房多跑两趟，白天晚上各看一次，问问邻居。装修上你偏爱经典耐久的路子，实木家具、中式或欧式古典都行，选材按十年不过时的标准挑，别追当下最潮的款式。",
  "fuDe|太阳|male": "你的精神头是从人堆里来的。被人看见、被人需要，你才有劲；一个人闲着反而心里空落落的。这不是虚荣，是你这种人的充电方式：忙起来、来往多起来，运气和心气都跟着旺，真闲下来心里那根弦反倒更紧。最难受的是被动退场——名声上出了事不得不躲起来，那段时间你的状态会掉得很厉害。化忌（阻碍）时，为名声悬着的那份不安会跟很久。\n\n建议你自己掌握节奏。该出场的时候尽情出场，累了就主动退一阵，是你决定退，而不是被人赶下来。低谷期别硬撑着社交，把手机关掉，找件不用被人看见的事做——钓鱼、走山路、种点东西都行，中年以后这个出口尤其要紧。再给自己找一件跟名气无关、长期能做下去的事，哪怕没人鼓掌你也做得住，这份底气比掌声耐用。",
  "fuMu|武曲|male": "你的父母多半是刚硬实干的人。其中做工程、做管理、当兵从警或者技术出身的居多，家教偏严，情感上的话不多，物质上不会亏着你。你跟长辈早年的缘分偏薄，要么很早就离家，要么聚少离多。跟父亲尤其容易两个硬汉对着来，谁也不肯先软一句，年纪大了就变成敬着但不亲近。\n\n建议你别指望靠继承来立足。你自己在外面立起门户，反而两代人都轻松。孝心用你擅长的方式表达：给父母安排体检、买保险、找好医疗资源，这比说漂亮话更落地，有空多打个电话，哪怕只讲三句。职场上你跟实干型的上司最合得来，遇上情绪化的领导，多汇报进度、少争对错。",
  "mingGong|天同|female": "你脾气温和、爱笑。人往哪儿一站气氛就轻松下来，别人跟你相处不设防。你聪明、学东西快，不爱跟人争，在家里和朋友圈里常当那个和事佬。感情上这份温柔是你最大的本钱，对方多半是被你的和气吸引来的，路比多数人顺。弱点是太容易满足：日子过得去就不想再动，事业上往往要有人推一把才肯往前。还有一点要当心——你太在意和气，容易在关系里把自己的想法一点点让没了。\n\n建议你给自己留一条不为别人让步的底线。哪些事可以商量、哪些事不行，事先想清楚，说的时候不用解释太多。事业上别等人来推，每年定一个具体目标，写下来，再告诉一个会追问你的人。挑一门能长期练的手艺往深里做，安稳日子里留一点往上走的劲，路才不会越走越窄。",
  "personality|天同|female": "你温柔、心软、重感情。你是那种让人一见就愿意亲近的人。你不爱硬碰硬，遇上大事第一反应是找人商量，这不是软弱，是你稳得住的方式。你也聪明、学东西快，这份本事能替你把路走宽，日子过成什么样不全看别人。你最容易吃亏的地方是心软：明知道这段关系不对劲，还是舍不得断；明知道这个人在占你便宜，下次她开口你还是答应。你不缺善良，缺的是一条清楚的界线。\n\n建议你把界线提前写下来。哪些忙不帮、哪些话不许对你说、每个月留多少时间和钱只归自己。事前定好，到时候照着做，别等人开口了才临时拿主意——到那时候你多半又心软了。一段关系让你越处越累，就给自己定个日子认真想一次：是这阵子特殊，还是一直都这样。真下不了决心，找一个不掺和其中的朋友，把事情原原本本讲一遍，你自己就听明白了。",
  "guanLu|天机|female": "你靠脑子和应变吃饭。最能发光的不是埋头执行，而是出主意、定方向、当参谋。公职、咨询顾问、教育培训、心理、人力、市场研究、数据分析这些地方最适合你，你看人看事细，方案想得周全。麻烦有两处：一是兴趣太广，什么都会一点、什么都不精；二是该开口的场合你想得太多，犹豫两下就错过加薪、升职的机会。帮你的人多半是比你有阅历的前辈或行内高手。\n\n建议你平时就练着快点做决定。小事限自己一分钟拍板，练熟了大事才敢开口。重要的汇报和谈薪，提前把话写下来过两遍，别临场现想。别急着自己开公司，先在好平台上挑准一个方向做深，把名声做起来；真要自立，找一个把事做落地的合伙人。要是打算生孩子，产前就跟团队说好回来的节奏和联系方式，别让自己在家里彻底断了消息。",
  "caiBo|天梁|female": "你的钱靠口碑挣，稳、有保障。上限比你以为的高，别一上来就给自己封顶。你最大的特点是有自己的钱袋子：自己赚、自己花、自己规划养老，结不结婚对你的安全感影响都不大。漏财在两处：对人太讲情义，钱和精力往外送；拉不下脸为钱开口，长期把价码定低了。\n\n建议你先做一件具体的事。查一遍同行的行情，把报价调到该有的位置，别再用人情价接活。投资走稳的路子，长期拿得住的东西适合你，高风险的短线别碰。帮人先给自己定个上限，超了就直说。婚前财产讲清楚、婚内各自记账，这在你身上本来就是天性，说开了反而少矛盾。",
  "jiE|天相|female": "你的底子偏温和。整体不错，但起伏比较明显，累久了容易一下子垮。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天相的五行去配；久坐加上压力，颈椎腰椎也容易出问题。你的情绪最伤身：委屈往心里咽，表面平和，其实一直扛着；怀孕生产前后和更年期这几段，憋久了最容易集中爆发。\n\n建议你每年定期体检。《全书》卷二疾厄天相条说「天相灾少面皮黄肿血气之疾」，大病少，面色、皮肤和气血要看着，女性相关的检查也别落下；身体不舒服及时看医生、遵医嘱。日常多喝水、吃清淡些、少盐少辣；坐一小时起来动五分钟，做颈肩腰背拉伸，配点快走、游泳这类温和的有氧。最要紧的是别一个人扛：怀孕和坐月子期间，家务和工作怎么分，提前跟家人谈好；情绪一直低落，主动找家人和专业的人帮忙。",
  "xiongDi|（兄弟空宫|female": "你跟兄弟姐妹处得和睦。你们都是不爱吵的性子，有事互相搭把手。但家里一有难处，第一个被想到的往往是你——借钱、临时帮忙带孩子、托你介绍工作，你几乎不会拒绝。婚后跟妯娌之间也是这样：你的温柔在家里讨喜，可越是会哭会闹的人，越容易从你这儿拿到好处。\n\n建议你学着说不。这不是冷漠，是给自己留点力气——你先站稳了，才帮得了别人。钱上的事丑话说在前面：借多少、什么时候还，写清楚；真要一起做生意，合同签好，账目交给一个更实际的人来管。答应帮忙前先问自己一句：这事我做了，接下来一个月会不会更累？会，就直接说这次不行。",
  "ziNv|廉贞|female": "你的孩子不会太多，但一个顶一个聪明。从小就有点看不透，心思细、感受力强，在艺术、文学这些地方先冒出天分。要留心的是孩子感情上开窍早，青春期的心事、网上认识的人、情绪的大起大落，都会比同龄人多一些。化禄（进财）的时候，孩子的才华容易被人看见；你自己经历过感情里的复杂，比谁都懂孩子在纠结什么。\n\n建议你主动跟孩子聊感情、聊身体。也聊跟人相处的分寸，用自己的经历讲，比一句「不许」管用得多。孩子的艺术天分尽量支持，硬压下去容易变成情绪上的问题。备孕和怀孕期间按时产检、听医生的，别照着命盘吓自己。跟孩子、尤其是女儿，要一直留着一条能聊天的路，别让她什么都自己憋着。",
  "qianYi|巨门|female": "你到了外地心不太容易定。跟人相处总差一口气，是非也跟着来。好处是你的表达能力让你在陌生地方立得快，教育、咨询、媒体、跨境生意这些方向尤其吃香；坏处是人生地不熟，你的话特别容易被人会错意。\n\n建议你在外地说话比在家里更收着点。同样一句直话，外地人可能当成挑衅。远嫁之后别做两边的中间人，你看得清家里的矛盾，可一插手调解，两边都会怀疑你。拿不准的合同、担保先放一放，找人看过再签。到一个新地方先认识一两个本地朋友，把这里的规矩问清楚，比自己慢慢摸索省事得多。",
  "jiaoYou|紫微|female": "你身边有分量的人多。朋友和下属里有身份、有自己舞台的不少，来往偏正式。古书说这一宫紫微「成行得力，旺主生财」，手底下能聚起一批真用得上的人，还能替你把钱挣出来。同一部书又把奴仆宫列为紫微的陷宫，说「虽得助亦不为福」，两种说法并存，用人别全押在别人身上。这些人分量重，端着架子反而容易失人心。\n\n每年认真维护三到五个能说心里话的朋友。这比泛泛地认识一百个强。你不用装可爱，但可以偶尔露一点软的一面，说一句「这事我也搞不定」，别人才敢靠近你。",
  "tianZhai|天府|female": "房子对你格外重要。家是你的归宿，也是你这一生最稳的那块地基。祖上留下的产业你守得住，自己买下的也经营得旺。你的家通常整洁、有序，住着让人安心，持家这件事上你的功底很深。\n\n建议你在结婚前先给自己置一套小房子当底牌。你婚后再和丈夫一起买要长住的那套，那套小的产权保留在自己名下。大额的买房决定先请专业法务看合同，产权、抵押、交房时间逐条核清楚。装修按十年不过时的标准挑，实木家具、中式或欧式古典都合你。家里留一点年节的仪式感，摆一面家人的照片墙、留几件老物件，这些是你的定心丸。",
  "fuDe|太阳|female": "你的精气神是从外面来的。被认可、被需要，你就满血；一个人闲着的时候反而容易空落落，开始怀疑自己是不是不被需要了。忙起来、来往多的时候，你的运气和心气都旺；真闲下来，心里那根弦反倒更紧。太阳落陷（力量弱）时，付出多、回报慢，人会累。化忌（阻碍）时，为名声悬着的那份不安会跟很久。\n\n建议你给自己找一个不靠别人点头的支点。固定读点书、写点东西、画画、练一门手艺，或者每周留一段安静的独处时间，一个人也待得住。中年以后，打坐、瑜伽这类静下来的活动，或者找专业的人聊聊心里的事，都值得试。掌声可以享受，但别把它当成活着的唯一理由——更年期前后，这份依赖会变得特别沉。",
  "fuMu|武曲|female": "你的父母多半刚硬务实。父亲常是技术出身、做企业或者当兵从警的那种硬汉，家教偏严，暖话不多，物质上不会亏着你。你跟长辈早年的缘分偏薄，要么很早离家，要么聚少离多。跟母亲这条线最复杂：母亲要是也强势，你们从青春期就开始较劲，一直能较到中年；母亲要是温和，你又容易嫌她太软而失望。\n\n建议你别指望靠继承来立足。你自己在外头立起门户，两代人反而都轻松。孝心用你擅长的方式表达：帮父母安排体检、保险和养老，这比说漂亮话更落地。跟母亲较劲的时候，先不争对错，隔一天再聊往往就过去了。婚后跟公婆礼数到位就够，保持一点距离对你才舒服。",
  "mingGong|天机|male": "你脑子转得快，看人看事很透。你常能想到别人没想到的角度。你最大的本事是灵活：环境一变，你比谁都快找到新路子。最适合你的位置是出主意、做规划、当参谋，公务、内勤这类靠脑子吃饭的活最顺手；钱也走这条路——帮人做事、领一份稳定薪水最稳，靠运气博来的钱留不住。短板是想得多、动手少，一件事翻来覆去想，等想明白时机过了；主意换得快，别人容易觉得你不够稳。你性子急、心却软，跟谁都聊得来，别人却常常摸不准你。\n\n建议你给自己定个规矩。想到七成就动手，剩下三成边做边改。重要的决定找一个做事踏实的人帮你拍板，别一个人在脑子里绕。工作上挑一个方向扎进去三五年，先把一样东西做到别人绕不开你，再去碰新的。跟人打交道，把已经定下的想法讲清楚，少让人猜。",
  "personality|天机|male": "你的脑子像一台不熄火的机器。别人看你在发呆，里面其实同时跑着十几条线。别人常说你“想得多、脑子快”，这话一半是夸一半是叹气。你上手快，什么都摸得到门道，代价是每样都没挖到底。你最舒服的位置是在旁边出主意——参谋、顾问、技术把关人，而不是自己扛大旗；真坐到第一把交椅，今天看好这条路、明天觉得那条更好，会先把自己拖垮。感情上也一样反复，不是不专一，是脑子总在重新算账。中年是你的分水岭：要么收一收，挑一两件事做深；要么继续散着，最后什么都只沾了个边。\n\n建议你现在就选一件已经做了三年以上的事。再往里扎三年，别一看到新方向就掉头。给自己设个冷却期，想换方向先记下来，放一个月再看还想不想换。位置上不用勉强自己当头，做那个被反复请教的人更自在。",
  "fuQi|太阳|male": "你在感情里热情大方。你愿意主动付出，肯把最好的条件和人脉给另一半。问题多半不是爱得不够，是陪得不够——太阳在夫妻宫先说的是另一半，她事业心重、外面的事多，两人容易顾不上彼此的情绪。你不太会变心，但外头的事太多，容易让她觉得被晾在一边。你在外面高调、要面子，回到家却需要把这身盔甲脱下来，跟她做回真实的自己。太阳庙旺（力量强）时，妻子多半能在事业上给你加分，还会带来人脉。\n\n建议你晚一点成家，太早定下来容易磕碰。把陪伴排进日程，每周固定一段只属于她的时间，手机放下；出差回来先跟她讲讲这趟遇到的人和事，别只报个平安。她提意见的时候别当成挑刺，那多半是想被你放在心上。刚在一起那股烈劲总会淡，能一起过日子的默契要慢慢攒。",
  "guanLu|（官禄空宫|male": "你事业上最大的助力是人缘。同事愿意配合，贵人多半是和气的长辈，或者圈子里有人替你引荐，工作整体挺顺，不用太拼也能维持得不错。服务、医疗健康、教育、艺术设计、餐饮酒店这类跟人打交道、要耐心的行业最合你。你在团队里是润滑剂，协调关系是强项，但催进度、拍板做决定不是。你不是只能干轻省活，问题在于有没有人把你推出去。\n\n建议你待在稳定的单位里做。别轻易一个人出去创业；真要合伙，找个有冲劲的搭档推着你跑。每做完一件事，主动跟上级讲清楚哪部分是你做的，别指望别人替你记功。每年定一个够一够才拿得到的目标；一个位置待得太舒服超过三年，就该动一动。",
  "caiBo|天同|male": "你的钱是慢慢攒出来的。家里给的本钱不多，早年不容易见到大数目，中年以后才慢慢有模样，指望一笔横财翻身不现实。主要收入来自工作和薪水，稳定但不快。你真正的赚钱方式是口碑：在某一件事上做到让人信得过，客人会自己带客人来。漏钱的地方很固定——吃喝、旅行、休闲这类让自己舒服的开销，钱常常就是这么一点点没的。\n\n建议你把存钱交给制度，别靠自制力。工资一到账先自动转走一笔，剩下的随便花。投资走稳的路子，定期定额买一点，看不懂的高风险东西别碰。想清楚自己哪一样本事能做到让人主动介绍客人，把时间压在那上面。还有一点，你感情一乱，花钱就跟着乱，关系不稳的时候先别做大额决定。",
  "jiE|破军|male": "你的身体跟着生活节奏走。日子一乱，状态就跟着晃，作息稳定是你最大的保障。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗破军的五行去配；熬夜之后抵抗力也会跟着往下掉。老在变动、老对现状不满，也会一直耗你的精力，磕碰意外要格外当心。\n\n建议你先把作息固定下来。睡觉和吃饭的点比吃什么更重要。饮食按点吃，少吃辛辣。运动挑有新鲜感的，攀岩、格斗、武术都行，关键是能坚持下去，护具戴好、别带伤硬上。每年定期体检；身体有问题及时看医生、遵医嘱，别自己扛。",
  "xiongDi|贪狼|male": "你的兄弟姐妹多半也是能说会道、路子宽的人。他们在销售、娱乐、餐饮、艺术这些行当里常见。人数一般不多，各自过各自的，反而比挤在一起更省心。你们热闹归热闹，逢年过节场面很大，日常真正说心里话的时候少。\n\n最该防的是酒桌上定生意。几杯下去一拍即合，第二天清醒才发现条件没谈清。立个硬规矩，酒后不签字、不转账，隔天再把条款过一遍。真要合伙，销售、餐饮、娱乐、做平台这类最合适，账目和分成一开始就写进合同。平时多打几个电话问近况，比过节摆一大桌管用。",
  "ziNv|武曲|male": "你的孩子多半性格刚、主意正。孩子从小就像个小大人，不黏人也很少撒娇，心里有情也是用做事表达，不挂在嘴上。这类命里孩子数目偏少，缘分来得也晚一些。你当父亲最容易踩两个坑：一是管得太严，把对孩子好等同于把他练成材，让他童年里没多少暖的记忆；二是拿钱代替陪伴，觉得我挣钱让他过好日子就够了。\n\n建议你把「我说了算」换成「我听你说」。孩子越大越吃这一套，管得紧不如说得开。每周留一段只属于你和孩子的时间，不谈成绩、不谈规划，就是一起玩。嘴上那句「我爱你」在你家里尤其少，值得你硬着头皮多说几次。",
  "qianYi|（迁移空宫|male": "你是往外走才发光的人，守在老家反而施展不开。家里的老本行、老产业通常帮不上你，多半得自己挪窝、换个地方重新扎根，在外地闯名声比在本地快得多。往东边、南边这类热闹、舞台大的地方去，一般更顺手。\n\n建议你这辈子至少去一次大城市、大平台或者国外。认真把摊子铺在更大的地方，这一步对你几乎是少不了的。人到了外地，酒局应酬要格外当心，感情和钱上的乱账在陌生地方最难收拾，能不喝就不喝，能带上同事就别单独去。化忌（阻碍）时，出门容易惹是非、伤名声，那阵子少露面、少接不熟的合作，手续和合同都办清楚。",
  "jiaoYou|廉贞|male": "你身边总少不了几个有故事的人。有才艺的、感情经历复杂的，都爱往你这儿凑。你这条路上朋友多不多不要紧，圈子干不干净才要紧。廉贞在这一宫的亮度，决定肯替你出力的人来得早晚。朋友一有感情上的烦心事就来找你评理，弄到最后你自己也搅了进去。化禄（进财）的时候，人脉能给你带来门路和资源。\n\n建议你给自己定三条线。别人的感情纠纷只听不评，不当中间人；朋友之间的钱，要么给得起就给，要么不借；灰色地带的事一概不沾。听到关于谁的传话，先核实再决定要不要管。宁可圈子小一点，也别为了热闹留一堆会给你惹事的人。",
  "tianZhai|七杀|male": "你这个人闲不住。身上一直带着一股躁劲；住的地方要是吵、乱、人来人往，脾气会越住越大。家对你是充电站，不是社交场：客人多、客厅热闹、家里总有人走动的模式，会让你身心俱疲。家里的产业，七杀会刑囚就难留。\n\n建议你挑安静、独立、私密性好的住处。独栋小院或者郊区优先，闹市里的公寓尽量少考虑。装修走简洁实用的路子：少装饰、多收纳，留一个只属于你的房间或角落，进去就不用应付任何人。家里少办聚会，想热闹就约在外面。",
  "fuDe|天梁|male": "你心里像棵老树，自己扎得稳，还能给别人一片阴凉。平时看着没什么大起大落，真出事的时候你反而定得住，这份安稳是你最大的福气。你的软肋是照顾了一圈人，唯独漏了自己。\n\n建议你每周留一块完全属于自己的时间。不接活、不听人诉苦，去走路、发呆、打坐都行。中年以后试试一个人出门旅行，哪怕三天，你会发现少了你，天也塌不下来。心里压着事别硬扛，找个能听你说话的人，写下来也行。别把操心当成爱——很多事你不管，它自己也会好。",
  "fuMu|紫微|male": "父亲这条线是你命里的大题目。你爸多半说一不二、在外头有点地位，对你的期望也高。缘分本身不薄，难在两个人性子太像：你年轻时不服他管，中年以后又因为一样的硬脾气，慢慢没了话说。跟妈妈相处会柔软一些，但要是妈妈也强势，一样紧张。碰到强势的上司也一样，你硬顶多半吃亏。\n\n35 岁以后主动去修跟父亲的关系。别等他身体出状况才后悔：定期回去吃饭，聊他懂的事，少评判他的选择。给妈妈多一点嘴上的温度，一句「你辛苦了」比你买的东西管用。遇到强势的上级，别比谁更硬，学着借他的力办成你想办的事；真起了冲突，先把自尊放一放。",
  "mingGong|天机|female": "你脑子快、心也细。别人一句话背后是什么意思，你一听就明白。你最擅长的是在旁边出主意、把事情安排顺，是那种让整件事转起来的军师。吃饭的路子偏稳：公职、内勤、学校、咨询、教育、技术研究这类领固定薪水、靠脑子做事的位置最合你。难处在感情上——你太敏感，一个语气、一条没回的消息，都能在心里演成好几出戏，小事越想越大，自己先累了。你要的不是天天给惊喜的人，而是让你踏实、不用猜的人。\n\n建议你别在心里自己演。起了疑心就当面问一句，比自己琢磨三天强。挑伴侣别看会不会哄人，能按时回消息、答应的事做到，比浪漫重要得多。工作上不用急着抢台前，先把出方案、定方向的本事做扎实。每天留一段不想事的时间，做点动手的事，把注意力从脑子拉回手上。",
  "personality|天机|female": "你的心思细到自己都嫌累。别人一句话的语气、一个停顿的眼神，你能在心里拆出三层意思。这份敏感在小事上让你比谁都体贴，到了大事上却拖住你——一个决定在脑子里演十几遍，等真动手，最好的时机已经过了。你对玄学、命理、心理这些看不见的规律天生感兴趣，越钻越上瘾。你最累的地方在亲密关系里：太容易把对方的情绪接到自己身上，他不高兴，你先难受半天。\n\n你缺的不是会想，是停得下来。建议你给决定设个期限：小事当场定，大事最多想三天，到点就选一个，选错了再改。练一句话对自己说——别人的难受是他的事，你可以心疼，但不用替他扛。跟人相处时，先问对方需不需要你帮忙，再决定要不要出手。事情上挑一两件做久，三五年做下去，比同时铺开五件浅的更踏实。",
  "fuQi|太阳|female": "你的另一半多半是太阳型的男人。他外向、有魅力、事业心重，在圈子里有点名气或者位置。太阳庙旺（力量强）时，他形象好、肯顾家；落陷（力量弱）时，你们要多花心思守住相处的时间。你欣赏有本事的男人，可这种人最容易把你晾在一边——他忙他的，你一个人守着。还有个老说法得纠正：把家里张罗妥当，不等于婚姻就长久，感情得两个人一起花心思。\n\n建议你别急着定下来。多相处一段，看清楚他扛不扛事。太阳落陷（力量弱）时更适合晚一点结婚；一个女命巨门、太阳组合、太阳落陷的例子，择偶可找比你大七岁以上、或者离过婚的人。相处上给彼此留空间，别拿他在不在家衡量他爱不爱你，但该提的要求要说明白：每周留一段只属于你俩的时间。太阳化忌（阻碍）在夫妻宫，牵动的首先是丈夫那边，感情上要多留心外面的是非；这是生年带来的底子，哪个十年、哪一年被引动，要再看运限。",
  "guanLu|（官禄空宫|female": "你工作上最大的助力是人缘。同事愿意配合，机会常是熟人引荐来的，整体挺顺，不用太拼也能维持得不错。服务、医疗健康、教育、艺术设计、餐饮酒店这类跟人打交道、要耐心的行业最合你。你在团队里是协调关系的那个人，但催进度、拍板做决定不是强项。你对职位高低、排名前后没那么在乎，工作和家庭之间弹性很大，风险也在这儿：日子一舒服就容易停在原地，功劳也常因为不会讲而被别人领走。\n\n建议你不管重心放在哪一边，都别把这条事业线断掉。兼职、手艺、副业都算，一是手里有自己的钱，二是别让生活只剩家里这一圈。每做完一件事，主动跟上级讲清楚哪部分是你做的。打算生孩子的话，提前跟伴侣把谁来带、什么时候回去上班讲明白，写下来最好。",
  "caiBo|天同|female": "你的钱是一点点攒出来的。家里给的本钱不多，中年以后才慢慢看得出成色，指望一笔横财翻身不现实。你日常其实很会算账，比价、优惠、会员这些门儿清，但钱还是留不住——漏的地方集中在吃、做保养、带孩子玩和给家里添东西这四样，都是让自己和家人舒服的开销，花起来不心疼。家里的钱你多半不争着管：你管日常和气氛，大额投资交给另一半。\n\n建议你单独开个自己的账户。工资一到先自动转一笔进去：一半留着买让自己开心的东西，一半锁死不动，比咬牙省钱管用得多。投资走稳的路子，定期定额买一点，看不懂的不碰。家里的钱就算不归你管，账你也要看得懂，每年至少弄清一次家底。真正能让收入涨上去的是口碑：在一件事上做到让人主动介绍你。",
  "jiE|破军|female": "你的身体跟着生活节奏走，日子一乱，状态就跟着晃。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗破军的五行去配；熬夜之后抵抗力也会往下掉。生活一动荡，经期也容易跟着乱：忽早忽晚、量不稳定，甚至停一阵又突然来。你还有个习惯是忙起来就硬扛，身体给的信号常被你忽略过去，磕碰意外要格外当心。\n\n建议你把作息固定下来。睡觉和吃饭的点比吃什么更重要。每年定期体检，自己把经期情况记一记，连着几个月不正常就去看医生、遵医嘱，别拖。打算要孩子，先把生活节奏稳定半年到一年再说；怀孕期间让家人帮你盯产检时间，别因为出差就跳过。快到更年期时可以提早找医生聊调理，你这类体质的不适感往往比别人明显。",
  "xiongDi|贪狼|female": "你的兄弟姐妹多半也是会玩、路子宽。他们是身边不缺人的类型，娱乐、艺术、时尚、销售这些行当里常见。人数一般不多，各自过各自的日子，反倒比挤在一起处得好。你们聊得多的是近况和热闹，真正说心里话的时候少。\n\n结婚以后跟妯娌、嫂子弟媳相处要多留一分心。你天生的气场容易让人觉得被比下去。家族聚会上收着点，多问她们的事、少讲自己的风光，姿态放低，麻烦少一半。合伙上最该躲的是跟异性单独搭伙做生意，感情和利益搅在一起，最后两头都输；真要合伙就找第三个人在场，账目分开记。",
  "ziNv|武曲|female": "你的孩子多半性格刚、主意正。孩子从小就像个小大人，不黏人也很少撒娇。这类命里孩子数目偏少，缘分来得也晚一些。你当母亲最大的难处不在能不能给：物质条件、升学规划你都安排得又稳又细；难的是说出口的那部分，一句「我爱你」、一个拥抱，对你来说像是另一门语言。可孩子最想要的，恰恰是这个。\n\n建议你把感情当动作来练。每天一个拥抱，每周留一段只陪孩子、不谈成绩的时间，生日认真过一次。把「我安排」换成「我们商量」，孩子越大越吃这一套，冲突会小很多。",
  "qianYi|（迁移空宫|female": "你是往外走才顺的人。老家的旧资源通常帮不上忙，换个城市重新扎根，反而更容易闯出名堂。在外地、外企或跨地区的平台上，很多在本地压着你的东西会松开，施展空间大得多。成家以后走动受家里牵制是常事，但你要是完全待在家里，人很快就蔫了——你得跟外面保持来往才有精神。\n\n建议你趁早争取外派、留学或者跨城调动的机会。这段经历是你独立起来最关键的一步。成家以后可以试试远程办公或者两地跑的安排，别把自己彻底困在家里。一个人出远门，行程告诉家人、住处选正规的，异地的酒局应酬尽量别单独去，界线讲在前面。化忌（阻碍）时，在外容易被人说闲话或者被搭讪骚扰，那阵子少接陌生邀约，安全上多留个心眼。",
  "jiaoYou|廉贞|female": "你身边总有几个有故事的人。感情经历复杂的、做艺术的、职业特别的，都爱往你这儿靠。朋友有心事就来找你拿主意，久了你成了别人的情感军师，结果卷进人家的恩怨里，自己耗得很厉害。廉贞在这一宫的亮度，决定肯替你出力的人来得早晚。圈子干不干净比人多人少重要。化禄（进财）的时候，人脉能带来专业上的门路。\n\n建议你给自己定几条线。别人的感情纠纷只听不评，不当中间人；跟异性朋友和同事的往来放在明处，不深夜单独见面；朋友之间的钱，要么给得起就给，要么不借。听到关于谁的传话，先核实再决定管不管。宁可圈子小一点，也别留会给你惹事的人。",
  "tianZhai|七杀|female": "你这个人闲不住。身上一直带着一股躁劲；住的地方要是吵、乱、人来人往，脾气会越住越大。家是你少有的能卸下盔甲的地方：白天在外面冲锋陷阵，晚上需要一个安静到底的空间把自己修回来。家里的产业，七杀会刑囚就难留。\n\n建议你挑安静、独立、私密性好的住处。独栋小院或者郊区优先，闹市公寓少考虑。条件允许的话，早点给自己买一套小房子当底牌，不是不信任另一半，是你这样的人心里需要一处只属于自己的退路。装修走简洁实用：少装饰、多收纳，留一个谁都不打扰你的角落。",
  "fuDe|天梁|female": "你心里像棵老树，自己扎得稳，还能给别人一片阴凉。平时看着没什么大起大落，真出事反而是你定得住，这份安稳是你最大的福气。你最大的软肋是操心过头：家里每个人、身边每个朋友的事都往心上放，久了就成了长期的紧绷。\n\n建议你每周留一块完全属于自己的时间。不接活、不听人诉苦，走路、发呆、做瑜伽都行。中年以后试试一个人出门旅行，哪怕三天，你会发现少了你，天也塌不下来。心里压着事别硬扛，找个听得懂你的人说说。别把操心当成爱——很多事你不管，它自己也会好。",
  "fuMu|紫微|female": "父亲这条线是你心里最大的题目。你一直想要他的认可，又因为性子跟他太像，动不动就顶起来。缘分本身不薄，难的是性格。你爸如果是事业型、说一不二的人，对你期望很高，甚至盼着你像个儿子一样争气——这份压力后来成了你一辈子往前冲的动力。跟妈妈要是处得紧张，多半是她习惯把话憋着，你却直来直去。\n\n主动给妈妈一点嘴上的温度。一句「你辛苦了」比买什么都管用。跟父亲别再比谁更硬，定期回去吃饭，聊他懂的事，少评判他的选择。结婚以后跟公婆相处，面子上恭敬着，有意见私下跟丈夫说，别当着他的面数落他父母，这一条能省掉后面很多麻烦。",
  "fuQi|武曲|male": "你在感情上直接又务实。你不太会说浪漫话，但会用做事来表达爱：帮对方解决麻烦，把日子的底子顶稳。你认定一个人就不轻易放手，只是太讲道理，容易让对方感觉不到温度。你的另一半个性刚、有主见、做事有担当，不是依附别人过日子的类型，可能做金融、工业、军警、外科或者管理。两个人都是行动派，家里分工往往很清楚，对方在钱和人脉上往往也能实实在在帮到你。\n\n结婚你适合晚一点。早婚时两个人锋芒都没收住，磨合起来很累。挑对象这一步对你格外要紧，对方的钱怎么花、账怎么管，谈恋爱时就该摊开讲。两个人都硬，吵起来谁也不肯让，你可以先退半步，把不高兴讲出来，比冷着脸管用。情调和仪式感得你主动安排，纪念日和小礼物记在日历上。",
  "xiongDi|太阳|male": "你的兄弟姐妹里往往有一个外向、体面的人。这人在社会上站得住，可能在公家单位、学校或媒体这类岗位上。你们之间来往比较敞亮，少有背地里的算计，多是在朋友圈和公开场合一起出现。太阳庙旺（力量强），兄弟是能借上力的。\n\n跟兄弟或朋友合伙，建议你把账目分工摊到明面上。要白纸黑字写清楚谁出钱、谁出力、怎么分。你这种人最忌讳背地里搞小动作、台面下做交易，藏不住，早晚会翻出来。最顺的合作方式是你出面、他执行，对外一起露脸，对内各管一摊。化忌（阻碍）时，兄弟那边的公开纠纷容易连累你的名声，先把利益关系切干净，再谈感情修补。",
  "ziNv|天同|male": "你的孩子好带，温和体贴。从小不太让人操心，长大了也多半挑一条稳当的路走，父子之间少有对着干的时候。要留心的是孩子缺那股往前冲的劲，容易觉得现在这样就挺好。你自己就偏爱舒服，看不得孩子吃苦，一疼就容易疼过头，结果养出一个比你还没动力的下一代。\n\n建议你有意给孩子安排一点「不那么舒服」的事。运动队、要长期练才见效的东西、既要配合别人又要跟人比的项目，让他早点尝到用力和结果之间的关系。他自己做得成的事你少代劳，做不成也别急着兜底。孩子身体不舒服，带去看医生、按医生说的办，别自己拿主意。",
  "qianYi|廉贞|male": "你是出门比在家顺的人。守在原地容易憋着，一出去反而遇得到肯提携你的人，机会也多。在外面的应酬、酒局、临时起意的来往特别多，关系比在家复杂，是非常常就从这些场合里来。化禄（进财）的时候，你在外地容易做出名声。\n\n建议你放心往外走。读书、工作、长住外地都比守在家里强。但出门有几条要守住：少去夜场，酒喝到七分就停，别跟不熟的异性单独相处到深夜。开车和户外活动量力而行，别赶夜路。在外地谈签约、担保、有灰色地带的合作，一律先放一放，回头找懂行的人看过再说。",
  "jiaoYou|（仆役空宫|male": "你的朋友圈偏务实。朋友多是因为共事、因为利益走到一起，很少有那种掏心掏肺的交情。你带人也一样，能干、执行力强、不用多说就把事办了的下属，跟你最合拍。\n\n建议你只跟讲合约、认规矩的人合伙。别跟那种「够意思就行」的人绑股权。合作前先把散场的规矩谈好：怎么分账、谁说了算、谁想退出怎么办，怎么散比怎么开始更重要。替人做担保这件事尽量不沾，吃亏的多半是你。",
  "tianZhai|天梁|male": "你的家有股护着人的温度。长辈爱来坐，朋友有难处也往你这儿跑。老家留下的家业，天梁庙旺的有一份。你不适合完全独立的小家庭，跟父母同住或者住得近，你反而踏实。\n\n建议你买房别只看涨不涨。要看能不能容得下人——多一间房，父母来住、朋友借宿都方便。装修往暖里做，木头、暖色、自然的料子，太冷的极简风你住着别扭。老家的房产早点跟家里讲清楚谁住谁管，别拖到有分歧才谈。长辈那边提醒他们定期体检，不舒服及时看医生。",
  "fuDe|紫微|male": "你心里的事比外人看到的复杂得多。白天你在人前利落、说一不二，夜里安静下来，却容易冒出一句「我得到了什么」。你的开心很依赖别人的认可：被肯定时整个人是亮的，一个人待着就容易自我怀疑。\n\n给自己找一件跟身份完全无关的爱好。写字、养花、骑车、钓鱼、拍照都行，在那件事上你不是谁的领导，就是个普通爱好者，这个出口对你比任何头衔都珍贵。每天留半小时，不处理任何人的事。中年以后如果长期高兴不起来，去试试打坐、冥想，或者找专业的人聊一聊，把安心的来源慢慢从别人的评价挪回自己身上。",
  "fuMu|天机|male": "你父亲多半是爱读书、爱琢磨的人。你们聊得来，可日常的亲热劲儿不多，感情都藏在道理和话题里。母亲对你的影响往往比父亲更深，你早年的阅读习惯、看事情的方式，多半是她带出来的。有的人早年会跟父母分开住一阵，或者由长辈带大、认过干爹干妈，这只是缘分的形式不同，不用往坏处想。\n\n建议你对长辈勤联系、少争论。一周一个电话，哪怕只说五分钟，也比半年一次的长谈管用。别老想着说服他们，他们要的是被放在心上，不是被讲赢。父母的事先问一句他们想怎么办，再给建议。对上司也一样，把你的判断讲清楚就够了，别在心里跟人较劲。",
  "fuQi|武曲|female": "你这个人气质偏刚。你做事果决，不习惯靠谁过日子；武曲在夫妻宫宜晚一点成家，遇到让你认定的人，多给自己一些时间。这不是什么命不好，是你要求高、不肯将就。对方得在某一方面真让你服气，你才愿意露出软的那一面。最合适你的，是比你更沉稳、更会理财的人，两个人能一起往前奔，而不是谁依附谁。\n\n建议你结婚晚一点。不用给自己定死岁数；定下来之前，先把对方的钱怎么花、日子怎么过摸清楚，这比甜言蜜语有用。你表达爱靠做事，记得也让对方知道你在做什么，不然他只看到你能干，看不到你在乎。",
  "xiongDi|太阳|female": "兄弟在你这儿分量很重。他们多半外向、体面，在公家单位、学校或者媒体这类要见人的岗位上。太阳庙旺（力量强），兄弟能给你当后盾。他们过得顺，你跟着借势；他们遇到坎，你也容易被带着受影响。\n\n建议你主动维系跟兄弟的往来。别等有事才联系，过节、生日、有好消息都搭个话，关系热着才借得上力。化忌（阻碍）时，兄弟那边闹出的公开纠纷容易连累你的名声，先把钱和责任撇清，再谈情分。",
  "ziNv|天同|female": "你的孩子好带，脾气温和。跟你少有对着干的时候，长大了也能像朋友一样跟你说心里话，当妈这件事你比多数人省心。要留心的是孩子缺那股往前争的劲，容易觉得眼下这样就够了——你的温柔是好事，可他一直待在软软的环境里，就不知道使劲是什么感觉。\n\n建议你主动把孩子放到性格不一样的人堆里去。运动队、辩论社、既要跟人配合又要跟人比的项目都行，让他早点尝到用力和结果之间的关系。他自己做得成的事你别抢着做，摔一跤也别急着扶。孩子饭菜清淡些，按时体检，不舒服就带去看医生、听医生的。",
  "qianYi|廉贞|female": "你是出门比在家顺的人。守在原地容易憋着，往外走反而遇得到肯提携你的人。在外面认识的人也杂，出差、旅行、异地的来往里，常会碰上让你心动却带着隐患的人。异地恋是你要特别当心的一块，隔着距离容易把神秘感当成真心。化禄（进财）的时候，外地有机会也有愿意帮你的人。\n\n建议你放心往外走。读书、工作、长住外地都比守着强。出门在外把社交的线摆明：少去夜场，酒别喝多，不跟异性单独聊到深夜。动心之前先把对方的实际情况弄清楚，家里什么状况、做什么的、身边人怎么说，这几样问明白再投入。自驾远行和户外活动量力而行，别赶夜路。",
  "jiaoYou|（仆役空宫|female": "你的朋友多是因为共事、因为合作走到一起的。关系能长期维持，但掏心掏肺的交情不多。你带人倒是顺手，能干、话不多、把事办成的下属跟你最合拍。\n\n建议你别勉强自己挤进不喜欢的圈子。把力气花在两三个同样独立、同样实在的朋友身上，创业型、专业型的女性通常跟你最搭。合伙这件事，合约和退出机制一定要写在前头，替人做担保尽量不沾，吃亏的多半是你。",
  "tianZhai|天梁|female": "你的家有股护着人的温度。亲戚爱来坐，朋友有难处也往你这儿跑。老家留下的家业，天梁庙旺的有一份。你跟父母的连接深，就算结了婚，住得离他们近一点你才踏实。\n\n建议你买房别只盯着涨不涨。要看能不能容得下人：多一间房，父母来住、朋友借宿都方便。装修往暖里做，木头、暖色、自然的料子，太冷的极简风你住着别扭。家里留一张能坐下几个人的桌子，朋友家人随时能来坐坐。老家的房产早点跟家里讲清楚谁住谁管；长辈那边提醒定期体检，不舒服及时看医生。",
  "fuDe|紫微|female": "你心里比看上去敏感，也比看上去孤单。白天你能把所有场子都撑住——会议、客户、孩子的事，一样不落；夜里安静下来，却容易反复琢磨「我是不是太强了」「他讨厌我这样吗」。被人肯定的时候你才觉得日子有滋味，被否定哪怕话说得很客气，也能让你失眠好几天。好在你本来就是能享福的人，真正卡住你的，是你对自己那套太高的要求。\n\n给自己留一段「不当大人」的时间。允许自己脆弱，允许别人照顾你，允许有几个小时什么都不用决定。找一件跟身份无关的事做，写字、养花、拍照都行。",
  "fuMu|天机|female": "你父母多半是老师、医生、工程师。这类爱读书、讲道理的人，你跟他们聊得来，偏偏因为太像，日常小事上摩擦不断。母亲对你的影响往往比父亲更深，你们能互相理解，也最容易互相戳到痛处。有的人早年跟父母分开住过一阵，或由长辈带大、认过干爹干妈，这只是缘分的形式不同，不用往坏处想。\n\n建议你跟父母把话说在事上。别翻旧账：他们的事先问一句他们想怎么办，再给建议，别上来就纠正。跟母亲相处，话到要冒火的时候先停住，换个时间再说。平时多聊小事、少讲道理，隔几天发张照片、问一句吃了什么，比长谈管用。婚后跟公婆，把期待放低些，礼节做到、面子上过得去就行，不用强求聊得来。",
  "mingGong|（命宫空宫|male": "你是个很有魅力又不太好看透的人。你会的东西多，往人群里一站有存在感，心里那股想要的劲一直没停过。你骨子里不服气，敢把旧的一套推倒重来，放在需要魄力的位置上最容易出头，到了陌生地方也能很快让人记住你。麻烦的是脾气硬、爱争，情绪起伏大，压力一来或者感情出事，反应容易走极端，不是爆发就是把自己整个关起来。吸引来的人多了，感情上的纠纷和背后的闲话也跟着多。\n\n建议你给情绪留个缓冲。气头上先别做决定，也别急着回话，隔一晚再谈，这一条能替你挡掉大半麻烦。把这股劲用在正事上，去做需要魄力和创意的工作，比跟人较劲划算得多。跟人来往，男女之间的是非主动少掺和；跟谁走得近、能走多近，自己心里先画条线。",
  "personality|（命宫空宫|male": "你的心里永远比脸上复杂。你不是好脾气的人，那团火一直烧着，只是有时候压着不发。你爱憎分明：喜欢一个人喜欢得很深，不喜欢的能记很久。你聪明，但这份聪明常用错地方，为了一句话反复琢磨对方什么意思，一个细节能在心里过好几个月。你适合走从政、司法、军警、艺术，或任何需要敏锐判断的复杂行业，带点锋芒的路你走着反而顺。要当心的是另一面：赌钱、男女关系、打官司这三件事，一旦沾上就不容易抽身。\n\n建议你给那些反复琢磨的事设个期限。过了就落地：要么把话直接问清楚，要么彻底放下，别在心里养着。这辈子最要紧的功课是分清哪些事值得计较、哪些不值得：动气之前先问自己，这件事一年后还重要吗。灰色地带的关系、能不打的官司、来路不明的钱，能躲就躲。",
  "fuQi|紫微|male": "感情里，你想当拿主意的那个。你希望另一半以你为中心，同时也愿意给她实打实的保护和物质支持，属于要面子、但也真扛责任的那种丈夫。你感情起步偏晚，晚一点结婚更容易走得长久，你需要够长的时间才敢认定一个人。你的妻子多半气质不俗、有自己的位置和主见，不是依附你过日子的类型，有时存在感比你还强。她在事业上帮得上你，可能替你带来人脉，也可能是你心里的支撑。\n\n两个都强的人吵架难免。但也因为谁也不弱于谁，反倒互相敬着；别争谁说了算，先把事情说清楚。你们相处偏庄重，激情不是主线，更像是在一起彼此都体面，所以亲密这件事要靠你主动安排：每周固定留一段只有你们俩的时间，不谈工作也不谈孩子。",
  "guanLu|天府|male": "你最擅长的是把已经有的摊子维持好、做扎实。不是从零开荒。待在成熟的大机构里，先把事做稳再做出彩，是最适合你的路。政府机关、银行、保险、会计审计、大企业的行政管理和法务合规都合适；当老师、做教育培训同样是你的路子，不少人一边上班一边教书，两头都不耽误。你可靠、负责、规矩守得严，能让一个团队转得有条不紊，但不太擅长在剧烈变动里抓机会。\n\n你最大的风险不是踩坑，是原地踏步。待得太安全，人就不往前走了。建议你每两三年主动换个岗位或接个新项目。拉你一把的多半是单位里的长辈和上级，所以别只顾埋头做事：每半年找直属上级聊一次，把做成的事讲清楚，能用数字就用数字。真要创业，选每月有稳定收入进账、风险看得见的方向；副业挑跟本职沾边的，别跨行。",
  "caiBo|天相|male": "你的钱来得很稳。你吃穿不愁，主要靠本职工作的收入，一点一点攒起来。你很少有天上掉钱那种一下子进一大笔，钱多半是跟着职位往上走、跟着贵人带出来的。你花钱有节制，不会冲动亏一大笔，但有时太保守，好机会也放过了。漏财的地方有两个：人情往来上花太多，还有拉不下脸拒绝别人，白白搭进去时间和资源。你的家底是稳步往上走的，中年之后明显宽裕。\n\n建议你主动跟公司谈加薪。你不习惯开口，很容易长期拿着低于自己价值的工资。理财就走稳路子，定存、稳健型基金、保险这类保本优先，别碰高风险的投机。把专业变成服务去接点活，比如做咨询、兼职，是最适合你多挣一份的方式。人情往来给自己定个年度上限，超了就直说预算没了。",
  "jiE|太阳|male": "你体力底子好、精力旺。但你也最容易透支——忙起来不知道停，情绪一上来火气也大。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗太阳的五行去配。你用眼多、又常待在强光和屏幕前，眼睛需要额外照顾；社交排得太满，抵抗力也会跟着掉。\n\n建议你每年做一次体检。眼睛的检查别落下，四十岁以后查得勤一点；身体有不舒服就去看医生，按医生交代的来，别自己硬扛。吃的方面少盐少油，酒能减就减。运动挑快走、游泳、骑车这种有氧的，户外最好，别去拼对抗性强的比赛。情绪上头时先离开现场走十分钟，比事后后悔管用。",
  "ziNv|天机|male": "你的孩子多半聪明、好奇心重。脑子转得快，问题一个接一个。这样的孩子压得越紧越容易反弹，给他空间才长得开。你容易掉进两个坑：一是自己懂得多，习惯替孩子把每个决定都指点一遍；二是拿“这个更有用”推着他走，而不是让他做想做的事。孩子缘上，孩子来得可能偏晚、数量也不多。\n\n建议你把自己当成给资源的人。别当画路线的人：学费、机会、见识尽力给，走哪条路让他自己选。管原则别管细节——诚信、安全、对人的态度管到底，穿什么、先写哪科作业放手。他做错了先别急着讲道理，让他把后果承担完，再问一句下次打算怎么办。",
  "qianYi|武曲|male": "你是要往外走的类型。越热闹、越有生意做的地方，你越吃得开；窝在家里守着反而施展不开。适合金融、工程、外贸、技术这类要跑、要跨地区的活儿，在外面靠的是你的真本事，不是靠人脉，做买卖、跑市场这条路对你是顺的。只是外面机会多，是非也多，口舌、纠纷、磕碰都比在家里概率高。\n\n建议你主动争取外派、调动或者常驻外地的机会。别舍不得挪窝。出远门给自己买份意外险，不亏。开车别赶夜路，户外别玩太极限的项目，工地、机器、刀具这些地方多看一眼再动手，最怕的就是「我没事」这种侥幸。",
  "jiaoYou|天同|male": "你的朋友圈气氛很好。多是脾气温和、爱吃爱玩的人，聚在一起像过节。你聚人、带人其实挺在行，真要张罗一件事，人是叫得来的。问题是身边全是捧你的人，没人愿意扫你的兴，难听但有用的话你基本听不到。脾气好不等于可以不看人。\n\n建议你身边留两三个敢当面说你不对的人。隔一阵就找他们聊聊自己最近在干嘛，他们说难听话时别急着解释。借钱给自己定一条线：超过某个数一律不借，借出去的就当送出去了。有人反复占你便宜，不用翻脸，把来往减少就行。",
  "tianZhai|（田宅空宫|male": "你的房子基本靠自己买。家里留下的有限，年轻时不容易，中年以后越置越顺，所以二十几岁跟人比房子没什么意义。你买房看的是住着舒不舒服，不是能涨多少，这本来也没错。\n\n建议你用制度替自己管钱。公积金交满、房贷按月扣、每月固定转一笔进买房的账户，比靠自己忍着管用。房贷别顶着上限借，留出让自己过得舒服的那部分钱，不然中途容易撑不住。装修别学那种冷硬的灰白风格，地毯、靠垫、暖光、香薰这些不起眼的小东西对你很要紧，该花的钱别省。",
  "fuDe|廉贞|male": "你是忙起来才踏实的人，一闲下来心里反而空得慌。你的内心戏比谁都多：能爱得很深，也能记恨很久；能做出很美的东西，也能掉进很暗的情绪里。最典型的毛病是把自己关起来，一件小事在心里反复回放，谁也不说，越想越沉。化禄（进财）的时候，你精神头足、做得出东西。\n\n建议你给心里的火找个固定的出口。写下来、画出来、跑出去，一周至少来一次，别等憋满了才发。难受的时候找一个能说实话的人讲出来，讲完就轻一半。也别让自己闲太久，手上留一件正在做的事。要是低落持续好几周、睡不好也提不起劲，去找专业的人聊聊，比自己硬扛管用。",
  "fuMu|（父母空宫|male": "你跟长辈的缘分偏淡。不是感情不好，多半是聚少离多、各过各的。你的父母通常是有故事的人：职业特别，或者人生经历不太寻常；家里的气氛也比一般人家复杂，可能有些说不清的老账、长辈之间的感情旧事，或者小时候跟着爷爷奶奶长大。化禄（进财）的时候，父母能给你别处拿不到的资源和见识。\n\n建议你把联系变成固定动作。每周一个电话，每年回去几次，不靠心情靠日程。长辈的身体按常规体检来，有问题听医生的，别照着命盘自己吓自己。这一条在单位里也一样：你跟上司容易互相猜，你看得穿他却不说，他也觉得被你审着，有想法就当面讲清楚，别把神秘感当护身符。",
  "mingGong|（命宫空宫|female": "你这个人做事有分寸、有自己的标准。你气质干净，不轻易跟人套近乎，别人对你多是敬重而不是随便。你才艺好、路子宽，艺术、法律、财务这几条路都走得通。感情上你态度认真，不轻易动心，一旦认定就很坚定，魅力是别人被你吸引过来，不是你主动去招惹。\n\n建议你别把标准端得太高。在守住自己原则的同时，对真正在乎你的人多露一点柔软。事业上可以放心多试几个方向，不必早早锁死一条路。感情上不用急，你这样的人晚一点遇到对的人反而更稳；真遇上了，把界线和分寸讲清楚，比什么都管用。",
  "personality|（命宫空宫|female": "你身上有种让人想多看一眼的气质。不是甜的那种，是有分寸又不太好看透的那种。你对自己有标准，不跟着别人起哄。你感性、敏感，对美的东西格外有判断力，可这份感性也是负担：情绪起伏大，今天能为一首歌哭，明天因为一句话就冷下来。爱起来你毫无保留，可一旦感情断了，那种痛要很久才消化得掉。关注你的人不少，人际关系也因此常常变复杂。\n\n建议你把心里反复重演的那些细节找个地方放出去。写下来、画出来，或者一个人出去走一趟，别堵在胸口变成内耗。跟人相处先把距离和分寸摆明，能少很多麻烦。走艺术、设计、法律、心理咨询这类既讲专业又容得下复杂情绪的路子，你的敏感是本事不是毛病。情绪上来的时候先别做决定，隔一天再说。",
  "fuQi|紫微|female": "你在感情里想拿主意，希望对方围着你转。你的丈夫多半不是普通人——有身份、有位置，在自己的圈子里说得上话，往哪儿一站都撑场面，你也因为他有面子。他对你的事业真帮得上，可能替你打开人脉，也可能是你心里最稳的那根柱子。你感情起步偏晚，晚一点结婚更容易走得长久。你们两个都强，吵架免不了，但正因为谁也不比谁弱，反倒互相敬着。\n\n你们相处偏郑重。激情不是主线，更像是彼此都体面地在一起，所以亲密这件事要你主动张罗：每周空出一个晚上单独吃饭、走一走，不聊工作，也不聊两边的家里人。吵架别急着分谁对谁错，先把各自能决定什么讲清楚——结婚前就把这条边界谈明白，比婚后再磨省事太多。别急着定下来，你晚一点反而稳。",
  "guanLu|天府|female": "你最擅长的是把已经有的摊子维持好、做扎实。不是从零开荒。待在成熟的大机构里，先把事做稳再做出彩，是最适合你的路。政府机关、银行、保险、会计审计、大企业的行政管理和法务合规都合适，当老师、做教育培训也是你的路子。你稳重可靠，在职场上很受信任，是大机构最看重的那种靠谱员工，也比较容易把事业和家庭两头都顾上。短板是太守规矩，升职机会来了反而不好意思去争。\n\n建议你专门练一件事。主动开口要资源、要薪水、要升职。开口前先把这两年做成的事写成三条战绩，用数字说话，别只说自己辛苦。每两三年主动换个岗位或接个新项目，位置动了视野才动。如果要休产假，休假期间每个月跟上司联系一次，聊聊团队进展，回来才不会被挪到边上。",
  "caiBo|天相|female": "你的钱来得很稳。你吃穿不愁，主要靠本职工作，跟着职位往上走、跟着贵人带出来，很少有天上掉钱那种一下子进一大笔。你花钱有节制，不会冲动亏大钱，但有时太保守，好机会也放过。最大的盲点在家里：给家人花钱毫不犹豫，给自己花钱反复掂量；你还觉得夫妻的钱本就该放一起，所以手里几乎不留自己的那一份。中年之后财务会明显宽裕起来。\n\n建议你开一个只属于自己的账户。每月工资一到账就自动转进去两成，只花在自己身上。不管感情多稳，都给自己存够至少一年生活费的独立存款，这不是防谁，是底气。理财走稳路子：定存、稳健型基金、保险，保本优先，不碰高风险投机。人情往来定个年度上限，超了就直说预算没了。工资低于你的价值，就主动去谈。",
  "jiE|太阳|female": "你体力不错、精力旺，但火气也旺，忙起来容易透支。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗太阳的五行去配。你用眼多，眼睛得额外照顾。怀孕生产那段，你多半不肯歇着，压力大，身体的负担要格外留意。\n\n建议你每年体检一次。眼睛的检查别落下；身体不舒服就去看医生，按医生交代的来。经期量多时注意补铁，吃的方面少盐少油，酒能减就减。孕期按产检的节奏走，别为了工作跳过任何一次。到了更年期前后，燥热、心慌、睡不好别硬扛，提早几年就找医生检查、把作息调过来。运动挑快走、游泳这类有氧的，别拼对抗性强的项目。",
  "ziNv|天机|female": "你的孩子多半聪明灵动，从小爱问、好奇、想法跳。你最大的本事是听得懂他那些天马行空的话，能陪他讨论大人都未必答得上来的问题。你最容易掉的坑是育儿焦虑：方法研究一堆，孩子每一步都跟别人家比，越看越慌，把自己耗干。孩子缘上，孩子来得可能偏晚、数量也不多。\n\n建议你先给自己减信息。育儿号少看，家长群设免打扰，别人家孩子的进度不用打听。相信自己的眼睛和孩子的节奏，他什么时候会走会说，不用跟别人比。管原则别管细节——安全、诚信、对人的态度管住，其余的让他自己试。心里发慌的时候，先放下手机陪他玩二十分钟，多半就好了。",
  "qianYi|武曲|female": "你是要往外走的类型。越热闹、越有生意做的地方你越吃得开，守在家里反而施展不开。到了外地，老家那些牵绊松了，你的本事才真正放得开，所以你在异地往往比在本地顺。金融、工程、外贸、技术这类专业性强的行业最合适。只是在外独当一面的同时，孤单感也比别人重，身边常常没几个说得上话的人。\n\n建议你早点争取外派、留学或者跨城调动的机会。别舍不得挪窝。到了新地方，主动经营两三段能说心里话的关系，别把自己活成一座孤岛。出远门买份意外险，开车别赶夜路，户外别玩太极限的项目，一个人走夜路多留一分心。",
  "jiaoYou|天同|female": "你的朋友圈气氛好。多是能一起吃饭、一起玩的姐妹，聚起来轻松。你张罗人的本事不弱，真要办事，人是叫得来的。问题是身边都是好人，久了就没了看人的警觉——明明感觉到对方在消耗你，她下次开口你还是答应。你在男同事、男性朋友里也特别讨喜，但好意容易被人读成别的意思。\n\n建议你学一个简单办法。拒绝不用解释，「我现在不方便」就够了，说完别补理由。借钱给自己定一条上限，超过就直接说没有。跟异性相处把分寸讲在明面上，该说清楚的场合别含糊，比事后收拾误会省力。谁是真朋友、谁只在有事的时候才想起你，看几个月就看得出来，认准了慢慢少来往就行，不用翻脸。",
  "tianZhai|（田宅空宫|female": "房子这件事你基本靠自己。家里留给你的有限，年轻时紧一点，中年以后才慢慢宽裕起来。你在过日子上天赋很高：挑东西的眼光、把日常过出仪式感的本事、让人一进门就想赖着不走的氛围，都是你的长处。婚后你很适合当家里的中心，张罗节日、招待亲友这些事会让你特别有成就感。\n\n建议买房优先看三样。采光、离不离公园近、邻居好不好相处，这几样对你的幸福感比升值空间实在得多。存钱靠制度别靠忍：每月固定转一笔进专门的账户，剩下的随便花。装修别用冷色调和冷白光，暖光、暖色、软一点的布艺才是你的地方，这部分钱别省。",
  "fuDe|廉贞|female": "你是忙起来才踏实的人，一闲下来心里反而空。你的内心比外表动荡得多：能爱得很深，也能为一件小事反复回想、不放过自己，容易把自己关起来，谁也不说，越想越沉。化禄（进财）的时候，你精神头足、创造力旺，能把难受的事变成作品。\n\n建议你给心里的东西找个固定的出口。写下来、画出来，或者一个人出去走一趟、读点厚书，一周至少一次，别等憋满了才发。难受的时候找一个能说实话的人讲出来，讲完就轻一半。手上留一件正在做的事，别让自己闲太久。要是低落持续好几周、睡不好也提不起劲，找专业的人聊聊是很正常的选择，比自己硬扛强。",
  "fuMu|（父母空宫|female": "你跟长辈的缘分偏淡，多半是聚少离多、各过各的。父母通常是有故事的人，家里的气氛也比一般人家复杂。最值得说的是你和母亲：你们之间的牵扯特别深，她可能既是你最亲的人，也是你最疼的那处伤。化禄（进财）的时候，母亲是你审美和眼界的启蒙人，父母也能给你别处拿不到的资源。\n\n建议你跟母亲的关系不用急着理清楚。先把相处的方式定下来：能聊的多聊，聊不来的话题绕开，别每次见面都翻旧账。长辈的身体按常规体检来，有问题听医生的，别照着命盘自己吓自己。婚后跟公婆保持基本的礼数就够了，不用强求亲密，你的性子本来就不容易被长辈读懂，客气而有距离，反而处得久。",
  "fuQi|天机|male": "你在感情里很会察觉对方的情绪。你体贴得细，但爱分析的脑子常让你想太多，反而挡住了自然的亲近。你对感情忠诚，可好奇心重，容易被别的新鲜事吸引，得刻意把心思放回眼前的人身上。你的妻子多半聪明、脑子活，可能做顾问、策划、教育、技术这类动脑的工作，跟你有说不完的话，也常在要紧的事上给你出主意。两个人都爱想，容易变成谁都在分析、没人动手。\n\n建议你晚一点成家。多给彼此确认的时间；古书说天机在夫妻宫宜配年纪小一点、性子刚强一点的妻子，这样反而合得来；这是参考，不是硬条件。相处上，心里想什么就直接说出口，别指望对方猜。两人商量事情时定个规矩：谁提的想法谁负责第一步，先做起来再说。日子里多安排一起动手的小事——做饭、散步、出趟远门，光靠聊天撑不住一段关系。",
  "caiBo|太阳|male": "你的收入不太稳定，很难事先算准下个月进多少。要不要自己当老板，单看这颗星定不了：权禄相逢的人才会去做事业当老板，得看财帛宫权、禄是否相逢（禄存也算禄）。机会多半是人脉和曝光带来的，邀约不少但好坏都有，得挑。你花钱大方，请客、送礼、维持形象的开销不小，这是你最大的漏财口。投资上你偏爱回报快的，风险却看得不够细。钱通常来得晚，中年以后才真正厚起来。\n\n建议你给面子上的开销定个月度上限，超了就打住。谈合作先打听对方口碑再谈钱，宁可少接几单。把一部分钱交给更稳的人或更保守的方式打理，别全押在自己看好的快项目上。早年起落是常事，别因为亏过一两次就把路子全换掉。",
  "jiE|武曲|male": "你底子偏硬朗，体力比多数人好。但身体也偏僵，柔韧性不够，小毛病容易一点点攒起来。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗武曲的五行去配；意外受伤、动手术这类风险也要放在心上。你很能憋住情绪，可长期不说出来，闷气最后多半落在身上，变成说不清的酸痛。\n\n建议你把定期体检固定下来。每年做一次全面体检，身体有问题第一时间看医生、遵医嘱，别自己扛。运动上有氧加力量训练都做，把肌肉和体能练结实，但一定要注意安全，别逞强上大重量。烟酒和太辣的东西少碰。",
  "xiongDi|紫微|male": "你的兄弟姐妹里多半有一个特别出挑的。他在外头混得开，通常是哥哥或姐姐；你真遇上难处，第一个想到的也是他，你敬重他，又忍不住跟他比。你们感情是真的，但隔着一层面子，很少有打打闹闹的亲近。合伙这事要格外当心：兄弟宫紫微，搭档多半气场强、各有主意，你若也想拿主意，容易变成两个人抢方向盘。\n\n跟兄弟姐妹相处，你可以主动低半格。家里的事别急着替所有人拿主意，先问一句「你们想怎么办」。要合伙就把规矩立死再开工：怎么分钱、谁说了算、想退出怎么退，白纸黑字写清楚，留口头默契等于埋雷。最省事的分工是你定方向、对方管落地，别两个人都盯着同一摊事。",
  "ziNv|天相|male": "你的孩子多半乖巧、懂配合、有教养。从小就是放在哪都让人放心的那一类，老师喜欢，家长会上常被点名表扬。你的子女缘分本来就厚，孩子长大后读书、找工作都走得稳，公职、专业岗位、传统的大公司最适合他们。你和女儿的关系往往特别融洽，脾气对得上，话也说得进去。\n\n最该留意的是，太乖的孩子容易缺主见、缺闯劲。长大后就凡事等人安排。建议你从小把选择权交出去一部分——报什么班、周末怎么过、房间怎么布置，让他自己拿主意，选错了也让他自己承担一次，别什么都替他决定。孩子说“随便”的时候，多问一句你到底想要哪个。",
  "qianYi|天同|male": "你出门在外是有人帮的那一类。到了新地方容易遇上愿意拉你一把的人，很多机会是别人介绍来的，不是你硬抢来的。在外地从零做起、慢慢站住脚，对你来说走得通，尤其餐饮连锁、酒店、文旅、艺术这类行业，跟人搭伙去外地做也合适。\n\n建议你要换城市就趁早。动身前先把工作定下来，别辞了职再去碰运气。到了地方多找人牵线——同行的群、老乡的局都值得跑一跑，你在外面的路多半是人给的，不是硬抢来的。真要在外地做点自己的事，找个搭档一起干，比一个人扛稳当得多。出差旅行按常规做好安全准备就够，不用紧张。",
  "jiaoYou|天府|male": "你的朋友圈稳重务实。圈子不大，但认识二十年的老友、老同事、老邻居都还在，关键时刻是真能指望上的一群人。带团队也一样，你说一句有人跟着办，最舒服的搭档是能干又稳当的下属。\n\n建议你跟朋友的钱来钱往一律明算账。借条写清楚金额和还款时间，感情归感情，账目归账目。真开不了口催，就一开始只借你愿意送出去的数，借出去就当送了，心里反而干净。选下属宁可能力差一点，也要选人品靠得住的：能力能教，人不可靠救不回来。",
  "tianZhai|廉贞|male": "家里的房子和产业，多半靠你自己挣。你对住的地方有自己的讲究，家里通常有品味、有故事，摆件、颜色、家具都带点不随大流的味道。化禄（进财）的时候，买房、置办产业走得顺，你收藏的东西也容易增值。\n\n建议你买房签合同逐字看完再签。尤其是面积、交房时间和违约怎么赔这几条，看不懂就花钱找人看。跟邻居的关系主动维护，动工前打声招呼，能省掉大半麻烦。家里用电用火别马虎。装修可以深、可以有个性，但采光和整洁要保住，长期住在又暗又压抑的屋子里，你的情绪先扛不住。",
  "fuDe|（福德空宫|male": "你心里其实挺热闹。好奇心一直在线，对哲学、宗教、命理这些想不明白的事有天然的兴趣，读得越深越上瘾。你的日子多半是先累后闲——年轻时精神头都耗进去了，中年往后才慢慢得空。你享受琢磨事情的乐趣，也被它困住：脑子像不关机的机器，出成果的时候是天赋，停不下来就成了负担。\n\n建议你每天固定留一段只用身体、不用脑子的时间。走路、拉伸、做饭、修点东西都行，让注意力落到手上。中年以后挑一件专注一处的事长期做：打坐、太极、瑜伽、长跑都行，光靠读书和聊天压不住你这份心思。再定条规矩：一件事想过三天就必须挑一个，挑错了边做边改，别在脑子里熬通宵。",
  "fuQi|天机|female": "你在感情里很会看对方的情绪。你体贴得细，但爱分析的脑子常让你想太多、担心太多，反而挡住了自然的亲近。你对感情忠诚，可好奇心重，容易被新的可能性吸引，得刻意把心思收回眼前这个人身上。你的丈夫多半聪明、脑子活，可能做顾问、策划、教育、技术这类动脑的工作，跟你有说不完的话，也常在要紧的事上给你出主意、带来机会。两个人都爱想，容易变成谁都在分析、没人动手。\n\n建议你晚一点结婚。古书说天机在夫妻宫，丈夫宜比你年长；找年长一些的人相处更顺，这是参考，不是硬条件。相处上，心里不确定就当面问，别自己在脑子里替对方编理由。两人定好分工：谁提的事谁负责第一步，先做起来。多安排一起动手的日常——做饭、走路、一起出趟远门，这些比反复聊感情更能把关系稳住。",
  "caiBo|太阳|female": "收入不太固定，很难事先算准下个月进多少。要不要自己做老板，得看财帛宫权、禄是否相逢（禄存也算禄）。你花钱大方，请客、送礼、维持形象的开销明显偏高，这是最大的漏财口。钱通常来得晚，中年以后才厚实。\n\n建议你不管结不结婚，都保住自己的收入和账户。别把生计整个挂在别人身上。给社交和形象开销定个月度预算，超了就打住。投资别只挑回报快的，拿一部分交给更稳的方式打理。早年起落是常事，别因为亏过一次就把路子全换掉。",
  "jiE|武曲|female": "你底子偏硬朗，体力比多数人好。但身体也偏僵，柔韧性不够，小毛病容易一点点攒起来。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗武曲的五行去配；意外受伤、动手术的风险也要放在心上。你很能憋住情绪，可长期不说出来，闷气多半落在身上，变成说不清的酸痛。你性子刚，一忙起来最容易把身体排到最后。\n\n建议你把每年的例行检查固定下来。全面体检和女性的常规项目都别落下，身体有问题第一时间看医生、遵医嘱。备孕那段日子，压着情绪连轴转，身体容易不配合，减压比使劲更管用。运动上有氧加力量都做，注意安全别逞强。",
  "xiongDi|紫微|female": "你和兄弟姐妹之间有种微妙的张力。你要是有哥哥，他多半事业做得不错、气场也不输你，真到难处他确实靠得住；你和这样的兄长相处，常要在敬重和较劲之间找分寸。\n\n跟家里人相处，你可以主动让一让面子。别急着替所有人拍板，先问一句「你们想怎么办」。合伙做事挑人尤其要当心：兄弟宫紫微，搭档多半气场强、各有主意，两边暗暗较劲，最后常常连朋友都做不成。优先找互补的人——你定战略，对方管执行；两个都想拿方向盘的组合，早晚出事。",
  "ziNv|天相|female": "你的孩子多半乖巧、懂事、好带。读书成绩中等偏上，做人有规矩，是最让当妈的省心的一类。你跟女儿尤其亲，像母女也像姐妹和朋友，很少起冲突。你的子女缘分本来就厚，生育上一般也顺利，坐月子的时候家里人照顾得周到。要留意的是另一面：太懂事的孩子往往把难受藏得最深，你看到的乖，不一定是他真的舒展。\n\n建议你别只看孩子表现得好不好。多问一句“你想要哪个”。他说随便、说都行的时候，恰恰是最该追问的时候。给他一些真正能自己拿主意的事——报什么班、周末怎么安排、房间怎么布置，选错了也让他自己收场一次。孩子到了青春期突然沉默，别急着说他不懂事，先坐下来听他把话讲完。",
  "qianYi|天同|female": "你在外面不会孤立无援。你脾气好、好相处，走到哪儿都容易碰上愿意帮你一把的人，到外地从零做起也做得成。但你天生不是一个人扛着行李闯天下的性子：完全陌生的环境待久了，心里没着落，情绪上比在熟悉的地方吃力得多。\n\n建议你去外地别空手去。工作先定下来，落脚的地方先看好，再认识两三个说得上话的人，这三样齐了，你走多远都稳。到了新地方主动进圈子，同行的群、兴趣的组织都行，你的机会都是从人身上来的。跟家里保持固定的联系频率，比如每周一次电话，比想家时才打有用得多。",
  "jiaoYou|天府|female": "你的朋友多是同样稳当的女性。圈子不大，但每个人都靠得住。这是你很大的一份福气：认识二十年的老闺蜜还在身边，你的关系不像有些人那样隔几年就洗一次牌。关键时刻真能指望上，是你人际上最值钱的地方。\n\n你心软，不好意思催债，这一条要专门防。借钱之前先把金额和还款时间写下来，讲在前面比事后开口容易得多。真开不了口，就只借你愿意送出去的数，借出去当送了，心里反而干净。感情可以亲，账目要清，这两件事不冲突。",
  "tianZhai|廉贞|female": "家里的房子和产业，多半要你自己挣。你对住的地方有讲究，家里通常有品味、有故事，摆件、颜色、家具都带点不随大流的味道。化禄（进财）的时候，买房、置办产业走得顺，你收藏的东西也容易增值。\n\n建议你尽早给自己买一套小房子。哪怕小，也是实实在在的底气。签合同逐字看完再签，面积、交房时间、违约怎么赔这几条尤其要看清，看不懂就花钱找人看。动工前跟邻居打声招呼，能省掉大半麻烦。选房尽量挑采光通风好的，装修可以深、可以有个性，但别弄得又暗又压抑，住久了你的情绪先扛不住。",
  "fuDe|（福德空宫|female": "你心里有一个别人看不见的世界。各种可能在脑子里翻来覆去地算，对哲学、命理、修行、艺术有真兴趣，一头扎进去能待很久。你的日子多半是先累后闲，年轻时心里的劲儿都耗在想事上，中年往后才慢慢松下来。你这辈子最难的功课就是按下暂停键——想得停不下来的时候，凌晨三点还醒着，第二天什么都干不动。\n\n建议你每天留出半小时不动脑子的时间。冥想、瑜伽、慢跑、养花、画画都行，让注意力落在手上和身体上。睡前把没想完的事写在纸上，写完合上本子，告诉自己明天再说。中年以后可以学打坐这类专注一处的功夫，也可以找专业的咨询师聊一聊，把心里的事说出来比自己闷着强。",
  "jiE|贪狼|male": "你天生精力足，能熬、能玩、能连轴转。问题也出在这儿：透支得比别人快，自己还不容易察觉。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗贪狼的五行去配；长期熬夜、喝酒、玩得太猛，耗的是整个人。想要的东西得不到时那股烦躁，也会直接变成睡不着、吃不香。\n\n建议你把酒和夜宵先减下来。饭吃七分饱，蔬菜多一点，油腻辛辣少一点。你有运动天赋，把多出来的劲儿用在跑步、球类、游泳上，比憋着或者拿去喝酒强得多。每年做一次体检，平时喝酒多就跟医生讲清楚，该查的一项别漏；有不舒服及时看医生、遵医嘱，别自己上网找答案。节制这两个字，是你一辈子的功课。",
  "xiongDi|七杀|male": "你的兄弟姐妹不多。关系也谈不上亲：话少，从小各闯各的天地，见面客客气气，真到心里话就说不出口。这不是谁冷漠，是手足各自刚强独立、习惯自己扛。合伙做事最怕深度绑定——对方多半也独断，两个强势的人凑在一起总要分高下，最后钱和情分一起伤。\n\n建议你合伙之前先把丑话讲在前面。谁出钱、谁说了算、赚了怎么分、要退怎么退，全写成字。不是不信任，是给彼此留条路。跟兄弟姐妹相处，彼此都刚强，谁也别替谁拿主意，有事先问一句你想怎么办。逢年过节主动发个消息、约顿饭，感情是走出来的，不走就淡了。",
  "qianYi|太阴|male": "往外走对你有好处。尤其是在外地买房这件事，你做起来顺手，是攒家底比较省力的一条路。在外面发展，安静些、动脑子的活儿更合你：文化、艺术、咨询、技术这类跨地区的工作都行；被派出去冲业绩、跑销售的活儿不合你。日月反背的人，「大部分都会离祖，离开家乡到外乡去发展」。\n\n真要去外地，先把落脚的地方安顿好。住得踏实你才做得出事。异地恋别只靠感觉撑，见面少的时候更要把见面频率、将来在哪定居谈清楚，能不能落地一试就知道。已婚的换城市工作之前，先跟太太把利弊摆开谈——你不爱直说，一沉默对方就觉得被晾着。",
  "tianZhai|破军|male": "你的住处状态往往不太稳。搬家频繁、装修反复，房子很难一次到位。这不是你不会挑，是你天生待不住。破军落在子宫或午宫的，家里的老房产反而兴旺，只是有进有出。房子对你的意义不是住一辈子的地方，更像一个阶段性的据点——你不太擅长在一处扎根二十年。\n\n建议你买房别追求一步到位。优先挑好脱手的地段和户型，把“将来能换”当成硬指标。装修别一次砸太多钱，先满足住得舒服，剩下的等下一套再说，租房合同也别签太长。",
  "jiE|贪狼|female": "你天生精力旺，能熬能玩。麻烦也在这儿：消耗得比别人快，自己还不当回事。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗贪狼的五行去配；熬夜、喝酒、情绪压着不发，耗的是整个人。不少人还会发现经期量偏多、那几天脾气特别冲，这跟情绪憋着有关系。\n\n建议你把作息先稳住。酒和夜宵减下来，饭吃七分饱，蔬菜多一点。运动你有天赋，跑步、游泳、球类都行，把多余的劲儿用出去比憋着强。每年做一次体检，该做的女性常规筛查按年龄做；有不舒服及时就医、遵医嘱，别拖着上网找答案。打算怀孕就提前把酒、咖啡、熬夜停掉；怀孕期间别为了身材节食或者猛练。",
  "xiongDi|七杀|female": "你和兄弟姐妹之间不算密。也不爱说那些客套的贴心话，从小就各闯各的天地。婚后跟妯娌、嫂子这类关系，你天生带一点距离感，那种热络客套、姐妹情深的戏码你演不来，宁可淡一点也不愿装。好处是你不容易被复杂的家族关系拖下水；难处是你容易跟家里的女性长辈争谁说了算。\n\n建议你不用参与所有的家族应酬。做好自己该做的那份就够了，缺席几次不会怎么样。别硬装乖顺，装久了自己会先撑不住。跟兄弟姐妹如果要一起做事、一起出钱，把分工、出资和退出的规矩先写下来。真心待你的那一两个，主动联系、主动走动。",
  "qianYi|太阴|female": "往外走对你有好处也有代价。外地能给你安静的发展空间，文化、艺术、教育、咨询这类工作在外地做得开，房子上也常有收成；代价是孤独感重，身边没有熟人接着，情绪容易往下掉。\n\n远嫁这件事要想清楚。离开从小的支持圈，你的精神支点会晃；真要远嫁，就给自己补一套新的：每月固定跟家里通话，落地半年内在当地交到两三个能说心里话的人。异地恋别只靠感觉撑，远距离的浪漫跟过日子是两回事，早点安排见面、谈定将来在哪落脚。情绪长期低落别自己扛，找专业的人聊聊。",
  "tianZhai|破军|female": "你的住处往往不太稳。搬家频繁、装修反复，水电小毛病也多。这不是你不会挑，是你天生待不住。破军落在子宫或午宫的，家里的老房产反而兴旺，只是有进有出。房子对你的意义不是一辈子的港湾，更像阶段性的据点——你不太擅长在一个地方扎根二十年。装修上你偏爱前卫、有个性的风格，跟风传统那一套你住不惯。\n\n建议你有条件，婚前先给自己买一套小户型当底牌。这不是不信任另一半，是你需要一条随时能走的退路。买房别追求一步到位，优先挑好脱手的地段和户型，把“将来能换”当硬指标。装修别一次砸太多钱，先住舒服，剩下的等下一套。",
  "mingGong|七杀|male": "你是天生的行动派。认准的事说干就干，别人还在犹豫，你已经动手了。越是急事、难事、硬仗，你越顶得住，是关键时刻最能靠得住的那个人。代价是性子急、情绪起落大，遇事又爱反复掂量，身边人常摸不准你在想什么。你不肯妥协，容易被人觉得不好相处；有时准备还不够就冲了出去，白白多花力气。你朋友不多但够铁，不爱应酬，心里常有一种没人真懂我的孤独，这是天生带着的，不是你哪里做错了。\n\n建议你做大决定前给自己留一两天冷静期。先把最坏的情况想一遍再动手。跟人打交道，话说慢一点、脸色放软一点，你的执行力就能变成带动别人的力量，而不是压着别人。再给自己找一个不用绷着的地方：累了就承认累，别一个人硬扛到底。",
  "personality|七杀|male": "你的存在感很强，不是靠嗓门，是那股不好惹的气场。你直接、果断、不爱绕弯子，定了的事不容易回头。你不爱说，但说了就做，执行力上很少有人比得过你；可你受不了拖泥带水的人，更受不了反复改方向的上司，团队配合上常有摩擦。你性子急又刚，还容易多疑，身边人得花点力气才摸得准你。感情上你直接但不细腻，给伴侣的是说到做到的踏实，不是懂你心思的温柔。\n\n建议你安排事情时多说一句为什么。别人跟得上，摩擦就少一半。对伴侣和家人，把关心做出来：接一次机、记一个日子，都比嘴上不说强。中年以后你的朋友会越来越少但越来越深，别嫌少，把那几个人守住。晚上给自己留一个可以卸下盔甲的角落，不是变软，是让自己缓过来。",
  "guanLu|破军|male": "你的事业靠“破”和“变”吃饭。你在需要变革、开新局的地方最能发挥，守着老一套天天重复你受不了。科技、外贸、国际商务、艺术、军警司法外交、改革型管理这些路子都合适，往外走比守在一地强。你敢提反对意见、推着大家改，需要突破时价值最大；一到要稳稳执行的阶段，兴趣掉得很快。贵人来自天南海北，常在旅途和跨行交往里碰上。\n\n建议你走创业或者靠一门本事打天下的路。但要找个心细、求稳的搭档补你的短板。给自己定个规矩：一件事没做满三年不换赛道，积累不够深是你最大的风险。执行期兴趣掉了，就把收尾交给别人，你去开下一个口子。",
  "caiBo|贪狼|male": "你的钱很少是按月稳稳发的那种。工资这条线随事业起伏；你真正的大钱多半是计划外的进账，靠人脉、机会、投资一笔一笔来。命盘上再碰上火星、铃星，这种进账更容易来，但来得猛也去得快。见火星的人，三十岁以前起起落落是常态，真正攒下钱多半在三十岁以后。你挣钱容易，存钱难，吃喝玩乐、衣服旅行，哪一项都能把钱花光。\n\n建议你每次赚到大钱先把本金抽出来。放进一个不好动的账户。给自己定好每月的消费上限，超了就停手；赌性大的投机和感情上的大额付出，是你最大的两个窟窿。投资挑周期短、自己人脉够得着的项目，别把钱压在要放十年的东西上。年轻时别一次把家底全押上，留着本钱，中年那波才接得住。",
  "jiE|太阴|male": "你的身体跟心情是连着的。心情顺，人就有劲；心情一压着，身体先替你喊累。你属于偏敏感的体质，长期把情绪憋在心里是最大的隐患，睡眠和精神状态往往最先出问题——翻来覆去睡不着、白天没精神，多半是情绪没处走。作息一乱，缓过来也比别人慢。\n\n吃的以温补为主。少碰太寒凉的东西，饭按点吃。运动挑舒缓有节奏的：瑜伽、太极、游泳都合适，出点汗，情绪也跟着走掉一些。每年的体检别省，多查哪几项，按你全盘杀星最集中那一宫的地支和医生的建议来。身上有不舒服早点看医生、按医生说的做，别自己上网对症状吓自己。最要紧的一条：把情绪理顺，别的都好办。",
  "mingGong|七杀|female": "你是独立、果断的那类女性。眼里不揉沙子，做事说了算。你的本事是被认可的：在竞争激烈的环境里，你是最能从逆境里杀出来的人，事业上往往比感情顺。难的是婚姻这一关——你性子刚，对伴侣要求高，宁可单身也不愿将就，对等的人本来就不好找。太早结婚，磨合的阻力会比较明显；三十岁以后再定，反而更容易遇到真正合适的人。\n\n建议你把事业当成人生主轴。这是清醒的选择，不是退而求其次。找伴侣别只看条件，要找一个在某方面让你打心底服气、又容得下你独立的人；容不下的，再优秀也不合适。同时学着接受自己软的那一面：累了可以说累，别人递过来的好意可以接住，别把孤独当成强大的代价。",
  "personality|七杀|female": "你一向被形容为刚强、有气势。这不是贬义，是说你的独立和果断超出一般人。你比同龄的女生更早学会一个人扛事，比身边不少男生更敢拍板。你不撒娇，也不太喜欢撒娇的人；感情观直接，要么很爱要么不爱，没有暧昧的中间地带。这让很多男人对你又欣赏又有点怕，欣赏你的独立，怕你的强势。朝九晚五的日子会让你憋得慌，你更适合能自己拍板的位置。\n\n建议你在工作上就往需要自己下决心的路走。创业、销售、专业技术都行，别硬把自己塞进按部就班的框子里。感情上不用赶时间，等你自己站稳了，遇到的人才接得住你。你不用学撒娇，但可以学着接住别人递过来的伞：有人关心你，说声谢谢收下就是，你已经为自己撑了太久了。",
  "guanLu|破军|female": "你的事业靠“破”和“变”吃饭。你在需要变革、开新局的地方最能发挥，守着老一套天天重复你受不了。科技、外贸、国际商务、艺术、军警司法外交、改革型管理都合适。你敢提不同意见、推着大家改，需要突破时价值最大；到了要稳稳执行的阶段，兴趣掉得快。你这种性子的女性，事业往往比感情顺；贵人来自天南海北，常在旅途和跨行交往里碰上。\n\n建议你把重心放在事业上。靠一门精细的手艺或专业立住名声，这是你最稳的路。走出去比守在一地强，跨城市、跨行业的机会都可以试。给自己定个规矩：一件事没做满三年不换赛道，积累不够深是你最大的风险。创业就找个心细求稳的搭档补短板。",
  "caiBo|贪狼|female": "你的钱来得杂。工资这条线随事业起伏，钱来得不规则。挣钱你不难，难的是留住。衣服、包、美容、旅行、好一点的餐厅，哪一样都花得心甘情愿，钱从热闹里来，也从热闹里走。最怕的是巅峰期光顾着精彩，账上没留底，到中年日子过得漂亮、存款却很单薄。\n\n建议你开一个取起来麻烦的账户。每月收入先划三成进去，剩下的才是能花的。几个大项定上限：衣服、美容、旅行各自一年花多少，写下来对着看。投资挑周期短、自己人脉能摸得着的；圈子里口头推荐的项目，合同和背景查清楚再掏钱。家里的账建议各管一摊、分开记。",
  "jiE|太阴|female": "你的身体跟情绪绑得很紧。心情顺，人就有劲；心情压着，身体先知道。经期、睡眠、精神状态往往最先给你反应——情绪一乱，周期跟着乱，人也容易累。备孕、刚生完孩子那阵和更年期前后，起伏会比平时更明显，这几个阶段对你格外要紧。\n\n从年轻起就养成记录经期的习惯。哪天不舒服、量多量少都记一笔，看医生时能说清楚。每年的体检别省，女性相关的项目按医生建议定期查。吃的以温补为主，少碰寒凉，经期前后注意保暖。运动挑舒缓的：瑜伽、太极、游泳都好。打算怀孕就提前半年把身体调一调；生完孩子情绪低落别硬扛，跟家人说，必要时找专业的人帮忙，有问题及时就医、遵医嘱。",
  "mingGong|紫微|male": "你天生有一股领头的气场。外表稳重大方，进任何场合都容易被先看到，第一印象是厚道正派。你最大的长处是看得见大局，也能靠气场让人服你。短处是性子刚、认死理，拿定主意就很难听进别人的话，有时会因此错过更好的选择。你很在意面子，被当众否定特别难受，心里比外表敏感得多。跟人相处你习惯坐在上位，别人敬你多过亲近你，压力来了也爱一个人扛。\n\n这辈子最大的分水岭，是身边有没有肯帮你的人。建议你把批评当成信息收着，别当成挑衅：每做一个大决定，先找两个敢说真话的人问一遍。做事上你管方向就好，细节和落地交给靠谱的人。身段放低一点，把人放进来一起做，你的大局观才能变成真正的成果。",
  "personality|紫微|male": "在人群里你不用刻意表现，坐在那儿就有人看过来。你最让人服气的是能在乱局里一眼看出主线，会议吵成一团，你一开口就安静。但这份天然坐上位的本能也是你最大的坎：你的固执不是没听见别人说什么，是听见了还要按自己的来；被否定时哪怕话说得客气，落到心里也会一直发酵。你和别人之间总隔着一层，朋友敬你、跟着你，却很难走近你。压力来了你不肯示弱，硬扛久了，睡眠和肠胃先出问题。\n\n你要练的不是嘴上谦虚。要做的是承认两件事：你的判断也会错；你的尊严不需要靠让别人闭嘴来撑着。有人当面反驳你，先别急着回嘴，把话听完，再问一句「你指哪件事」。每周挑一件小事，故意按别人的办法做一次。心里堵着别硬撑，说出来是省力气，不是丢面子。",
  "fuQi|天府|male": "你在感情上认真。你不轻易开始一段关系，一旦点头就会全力守护，是那种能让人放心的伴侣，钱上有保障，事上靠得住。你的妻子多半也是稳当的人，有积蓄、有规划，不浮夸不张扬，可能在政府机关、银行或大机构做事，话不多但心里有主意，越相处越让人踏实。她在事业上是你的后盾，靠自己的资源和人脉给你打底，不替你冲锋，但帮你守住大本营。\n\n你们两个都偏保守。日子平和，很少吵架，问题是容易平到没味道。建议你别等她来带动，每个月主动安排一次两个人的事：出门吃顿饭、看场电影、短途走一趟，把惯性打断。你不擅长说，就用做的补：她的事记在心上，重要日子提前一天准备好。有分歧当天讲清楚，别攒着，你一攒就是几年。",
  "guanLu|廉贞|male": "你吃饭靠的是才华和个人特色。你在需要创意、需要表达、需要个人风格的地方最容易发光：艺术创作、媒体、法律、军警政务、美容时尚、餐饮这些行当都对你的路子，有舞台的地方你表现最好。你是能把一个项目盘活的人，点子多、也推得动，但情绪一上来就容易把事搞砸。你还容易成为众人注意的中心，跟着来的就是眼红和闲话。\n\n建议你别把私人情绪带进工作关系。难听的话先在心里放一天再说。想自己干可以，但最好找个稳重的人管运营和账目，你只管创意和对外。平时留意两种人：看中你才华肯给机会的，和你出事时肯出面帮你说话、帮你把事谈拢的，这两种人都值得长期走动。名声比一时的输赢重要，感情上的事更别带到公司里去。",
  "caiBo|武曲|male": "你的钱靠本事挣，底子丰足。靠工作和专业挣的钱是主力，只要肯下功夫，回报看得见。你的财路是用本事换收入，越专业、越难被替代，进账越好。意外之财要碰特定的机会，指望不上。你不为面子乱花钱，存得住，只是有时候省过了头，日子过得比收入紧。钱是稳步往上加的，不会一夜之间翻倍，人到中年底子会很厚。\n\n投资上你适合稳的那一类。选自住和收租的房子、看得清收益的项目，高风险的炒作别碰。容易漏财的是三处：突发的看病和意外开销、跟人扯不清的账、以及在感情里一味往外掏。建议给自己留一笔专门的备用金，合作和借贷一律白纸黑字写清楚。真要合伙，别人出钱、你来主事的方式比较合你。",
  "jiE|天同|male": "你底子不差，大毛病不多。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天同的五行去配。真正拖你后腿的是生活方式太舒服：能坐不站、能躺不坐，运动量常年不够，体重和血糖要盯着。你也不太会把不痛快说出口，习惯用吃点好的、玩一玩来转移，情绪压着不散，身体跟着受影响。\n\n建议你把运动变成每天固定的一件小事。散步、游泳、瑜伽都行，重点是天天做，不是偶尔练一次狠的。水要喝够，甜食和高热量的东西少吃，饭菜清淡些。每年做一次体检，血糖、体重这两项盯住，数值不对就去看医生、遵医嘱。心里不痛快的时候找人说出来，别一个人闷着靠吃喝顶过去。",
  "xiongDi|天机|male": "你的兄弟姐妹多半聪明、脑子灵活。但你们之间的情分是会变的：各忙各的，聚少离多，很难有那种天天黏在一起的亲近，见面聊得挺好，分开又各过各的。合伙这件事对你要格外小心，跟你搭伙的人往往点子多但变得快，今天一个方案明天一个想法，落地就很难。\n\n建议你跟兄弟姐妹保持“常联系、少牵扯”。问候勤一点，钱和生意上的事分清楚。要合伙就做短的——一个项目结一次账，做完分钱各走各的，比长期绑在一起合适。不管跟谁搭伙，出多少钱、谁管哪一块、怎么分账，一开始就白纸黑字写下来，别觉得是亲戚就不好意思提。",
  "ziNv|太阳|male": "你的孩子多半外向、爱笑、有人缘。孩子小时候就是班里的活跃分子，长大以后路子走得开。数儿子看阳星，太阳就是代表儿子的阳星。老说法讲「晚子贵」，晚一点当爸爸反而更好，孩子来得晚，往往更有出息。做父亲最大的难处是你在意孩子有没有给家里长脸，容易把自己那套对名声的看重压到孩子身上。\n\n建议你别急着替孩子规划一条出名的路。让他自己挑，你负责托底。当着外人别拿他跟别人比，在家也少说要给家里争口气那类话。从小帮他管住用眼习惯，少熬夜、少长时间盯屏幕，该查视力就查。化忌（阻碍）时，孩子在名声或者眼睛上容易出状况，早点提醒、定期带他体检。",
  "fuDe|天相|male": "你心里其实是安稳的。你不容易被大喜大悲带着跑，日子过得下去，也是能享福的那一类。麻烦在于你做什么事都先问一句：这样合适吗？会不会让人看笑话？这层顾虑跟了你一辈子——累了不敢说，想拒绝不敢说，难受了也不敢表达，硬撑着一副体面的样子，撑到自己都觉得闷。\n\n建议你每周留半天完全属于自己。不做给任何人看：写点东西、听听音乐、一个人走一段路都行。练一句话——“我今天不想去”。说出口第一次会别扭，第二次就轻松了。中年之后找一件不为赚钱、不为面子的爱好，安排一次一个人的旅行。日子是自己过的，不是演给外人看的。",
  "fuMu|巨门|male": "你跟父母的关系，一辈子都卡在说话上。长辈的一句话能成为你最大的支持，也能成为你最深的伤。你们的缘分可能偏薄，早年就离家、或者长期在外，跟父母聚少离多。\n\n建议你把要讲清楚的话留到私下讲。当着别人的面顶回去，赢了面子输了关系。跟父母聊天多问少评，他们讲的道理不合时宜也先听完。憋着不如挑个安静的时候一次说完，说完这件事就翻篇。职场上你跟敢直说的上司反而合得来，他们的狠话背后是什么意思你听得懂，别被表面的语气吓住。",
  "mingGong|紫微|female": "你天生气场强，站在哪儿都容易成为被看的那一个。你看人准，也看得见大局，做人做事正，不太好糊弄。缺点是主观、认死理，自尊心特别强。你交朋友挑得细，宁可少也不将就，跟人相处习惯坐在上位，别人敬你多过亲近你。事业上你通常比感情顺——这股劲用在工作上，你多半能走到带队的位置；用在亲密关系里就容易变成压力，因为你很难接受丈夫跟你唱反调。\n\n你要学的是在该软的地方软下来。工作上继续往前走没问题，但别一个人扛，身边有没有肯帮你的人，比你多能干更决定你走多远。感情里试着把「我说了算」换成「我们商量」，给对方留一块你不插手的地方。还有，允许自己在亲近的人面前示弱，这不会削掉你半分能耐，反而能让你的强变得好相处。",
  "personality|紫微|female": "你天生不是小鸟依人的性子。可从小到大，周围总暗示你「女孩子收着点」。你的气势不是装出来的，眼神里有分量，进任何场合都被一眼认出。这股劲在职场上是本钱，可在两个人的关系里就成了压力。你不是不想温柔，只是很难把温柔演成顺从——你没法把自己摆在别人下面，这不是脾气坏，是你习惯了站在主位。所以你在感情里总撞同一堵墙：吸引你的男人多半也强，处着处着就互相较劲；找个温和的，又嫌他撑不住你。\n\n你不用把自己的强磨掉。该换的是剧本：你这样的人过不了传统贤妻的日子，找一个跟你平起平坐、各自都有舞台的人。挑对象就看一条：他会不会因为你强而不舒服，会就别勉强。真在一起了，哪些事各自做主、哪些一起决定，讲在明面上。",
  "fuQi|天府|female": "你在感情上认真。你不轻易开始，一旦点头就会全力守着这段关系，是那种能给人安全感的伴侣。你的丈夫多半也是稳当的人，有积蓄、有规划，可能在政府机关、银行或大机构做事，话不多但心里有主意，越相处越让人踏实。事业上他是你的后盾，靠自己的资源和人脉给你打底，不替你冲锋，而是帮你守住大本营。还有一层：你的婚姻能走多远，除了看对方是谁，更要看你自己心里安不安稳。\n\n你们两个都偏保守。日子平和、少有大冲突，问题是容易平到没滋味。建议你别等他来带节奏，每个月主动安排一次两个人的事，出门吃顿饭、看场电影、周末走一趟，把惯性打断。心里不舒服当天说，别攒；你一攒就是好几年。选人把可靠放第一位没错，但也留意：跟他在一起时你是不是能松下来。",
  "guanLu|廉贞|female": "你靠才华和个人特色吃饭。你在需要创意、需要表达的地方最容易发光：艺术、媒体、美容时尚、餐饮，都对你的路子。你办事有条理、有分寸，法律、医疗、金融、教育这类讲规矩、看资历的行当也很适合你，在里面反而更容易熬出位置、说得上话。你在单位里容易成为焦点，跟着来的就是眼红和闲话。事业本身起伏偏大，好的时候很好，淡的时候也要熬。\n\n建议你把职业上的界线摆在明处。私下的应酬少去，谈事尽量在公开场合，能省掉一大半麻烦。情绪别带进工作关系，难听的话隔一天再说。打算生孩子的话，最好等手上有一段稳定的职业期再安排，别挤在最需要往上走的那两年。人情账不要混进职业信誉里，这是你最该守住的一条。",
  "caiBo|武曲|female": "你的钱靠本事挣，底子丰足。靠工作和专业挣的钱是主力，只要肯下功夫，回报看得见。你花钱实用，对首饰、名牌的兴趣远不如别人，更愿意把钱换成房子、金子、定存这些摸得着的东西。你对家里的钱有很强的掌控欲，钱在自己手上才心安，对娘家的责任也扛得比别人重。钱是稳步往上加的，不会一夜翻倍，中年以后底子相当厚。\n\n建议你婚后保留一个自己的账户。跟家庭共同账户分开，这不是不信任对方，是你的性子就需要这份底气。投资挑稳的：自住和收租的房子、看得清收益的项目，高风险的炒作别碰。也别省过头，该花在自己身上的别克扣。",
  "jiE|天同|female": "你底子不差。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天同的五行去配；体重和血糖要盯着。真正拖后腿的是生活太舒服——能坐不站、能躺不坐。你也不太会把不痛快说出口，习惯吃点好的转移一下，情绪压着不散，身体跟着受影响。\n\n建议你把运动变成每天固定的小事。散步、游泳、瑜伽都行，重点是天天做。饭菜清淡些，甜食和精米白面少碰，水要喝够。打算要孩子的话，提前找医生做一轮检查和调理再备孕；怀孕期间血糖尤其要盯住，产检按医生安排来。四十五岁以后每周至少动三次，年度体检别落下，身上不舒服及时看医生、遵医嘱。",
  "xiongDi|天机|female": "你和兄弟姐妹是那种心离得近、人离得远的关系。聊起来很投缘，日子却各过各的，聚少离多。家里要是有个性子强的兄弟姐妹，你多半选择让一步，不愿意正面顶。这是你的长处，也是隐患——一直让，家里分家、养老这些大事上就没了你的声音。婚后跟丈夫家的嫂子、弟媳、小姑子相处，你那份敏感是把双刃剑：别人的情绪你全接收得到，最后累的是自己。\n\n建议你在家里的大事上，至少把想法完整说一遍。说完对方听不听是他的事，但不能一次都不说。跟人搭伙做生意，出多少钱、谁管哪一块、怎么分账，一开始就写清楚，别怕伤感情，丑话说在前头反而处得久。合作做短的，一件事做完结一次账。情绪上的活儿别全揽下来，帮忙之前先问一句自己有没有空。",
  "ziNv|太阳|female": "你的孩子多半外向、爱笑、招人喜欢。数儿子看阳星，太阳就是代表儿子的阳星。老说法讲「晚子贵」，晚一点生，孩子反而更有出息。你和儿子互相影响很深，你性子强，容易在不知不觉间把他的主意压下去。\n\n建议你在儿子面前多退半步。他能自己决定的事就让他定，做砸了再一起复盘，别抢着替他拿主意。教育上舍得投入，尤其是儿子，这笔账拉长看很划算，晚年也多半能靠得上。从小帮孩子练一点扛压的能力，也教他在人前怎么把话说得体。化忌（阻碍）时，孩子的眼睛和名声容易出状况，用眼习惯早点管起来，定期带他检查视力。",
  "fuDe|天相|female": "你心里底子是安稳的。你不容易被大喜大悲带着跑，是能享福的那一类。麻烦在于你做什么都先问一句：这样合适吗？别人会怎么看？这层顾虑跟了你很多年——累了不敢说，想拒绝不敢说，难受了也不敢讲，一直端着一副得体的样子，端到自己都觉得闷。你的乖是真的值得被珍惜，可你自己想要什么，好像只有你自己不当回事。\n\n建议你每周留半天只给自己。不做给任何人看：画画、瑜伽、一个人去看场展览都行。练一句话——“我今天不想去”。说出口第一次会别扭，第二次就顺了。中年之后找一件不为赚钱、不为面子的爱好，安排一次一个人的旅行。偶尔不体面一点没关系，日子是自己过的，不是演给外人看的。",
  "fuMu|巨门|female": "你跟父母是一辈子讲道理的关系。什么都能聊，也可能因为任何一件小事翻脸。你们的缘分可能偏薄，早年就离家或者长期在外，跟父母聚少离多。你说话的调子多少带着家里人的影子，那是天天相处磨出来的，不是命里定好的。\n\n建议你结婚之前跟父母认真谈一次。不是要谁道歉，是把心里的话一次说完。平时聊天多问少评，他们的道理过时了也先听完。跟公婆相处少分析多倾听，你的分析在老人听来常常是挑刺，锐利的口才留给工作。有话挑安静的时候讲，讲完这件事就翻篇。",
  "guanLu|天梁|male": "你靠专业本事和帮人解决问题攒口碑。不是靠抢风头，越是做出来对别人有用的事，你越出得来。法律、医疗、教育、宗教、咨询、公益，还有司法、外交、监察这类公家单位的位置，都很对你的路子。在团队里你是出主意、稳场面的那个人，乱的时候最清醒，缺点是态度偏冷，别人不敢靠近。帮你的贵人多半比你年长、有见识，一次引荐就能改变你的走向。\n\n建议你别只顾埋头做事。专业做到位只是一半，另一半是让该知道的人知道你在做什么，定期汇报进展，再找一位老资历的人当领路人。如果你走的是吃公家饭这条路，稳扎稳打比冒险创业合适。想换方向也别怕，你文的武的都拿得起来，路比自己以为的宽。",
  "xiongDi|天府|male": "你的兄弟姐妹多半稳重务实。他们可能在体制内、银行或传统行业做事。你们的关系偏礼数型：过节聚一聚，家里有大事都到场，平时深聊不多，谈不上谁特别提携谁。要合伙做事，你天然偏爱稳当的路子，传统行业、连锁经营、一起买套房都在你的舒适区，激进的玩法不适合你们。\n\n建议兄弟之间的钱来钱往一律记明账。借多少、什么时候还、谁出资谁占多少，白纸黑字写下来。你越是怕伤感情把账糊过去，最后伤得越深。家里分东西的时候，你那一份要自己开口讲，别指望别人替你想到。平时联系不用多，一个月一通电话就够。",
  "tianZhai|天相|male": "你对家有股天然的讲究。从客厅怎么布置到桌椅怎么摆，你都要一个说得过去的样子。比起在外面拼，你更愿意把家里弄得舒舒服服、拿得出手，家是你真正歇得下来的地方。家里的产业，天相庙旺的有一份。装修上你喜欢经典耐看的路子，木头家具、暖色调、收拾得整整齐齐。\n\n建议你买房装修别跟风。网上流行的款式过两年就腻，经典款对你更合适，钱花在用得久的东西上。交房和装修的时候，防水、水管这些看不见的地方多花点心思验收，合同和收据都留好。房子涉及签字的事，别人催你也先把条款看清楚再落笔。日常多喝水，别老忍着不上厕所，每年体检把常规项目做全。",
  "fuDe|巨门|male": "你的内心像一口深井，表面平静，底下很深。你天生爱钻研、爱探究真相、爱把事情背后的道理想明白，这份能力用对地方就是过硬的研究力。用不对就变成过度分析，一件小事能让你反复推演三天，最后什么都没做成。你这辈子操的多半是心，不是外面来的祸，但心累也是真累。\n\n建议你给思考设个截止时间。不是不想，是想到点就收，够好就动手。中年以后可以试试打坐、正念，或者养成写东西的习惯，把过度分析的劲头引到能出成果的地方。心里憋着的事定期找人说出来，说出口本身就能松掉一半。每天留半小时什么都不想，散步、听歌都行，让脑子空一会儿。",
  "guanLu|天梁|female": "你靠专业本事和帮人解决问题攒口碑吃饭。越是做出来对别人有用的事，你越出得来。法律、医疗、教育、咨询、公益，还有司法、监察这类公家位置，都很对你的路子。你身上有股男人一样的担当，独立、扛得住事，放在律师、医生、大学老师这类靠专业说话的角色里就是长处：你不站队、不依附谁，所以走得远。\n\n建议你别把事业和婚姻想成二选一。那不是命里定好的代价，是你自己怎么安排的问题。工作上你最容易吃的亏是只顾埋头做事，记得让该知道的人知道你的成绩，定期汇报、主动争取项目。团队里你态度偏冷，可以每周主动约一个同事吃饭，关系是聊出来的。",
  "xiongDi|天府|female": "你的兄弟姐妹多半稳重务实。他们可能在传统行业、公职或银行做事。你们的关系温和而保守：过节聚一聚，家里有大事都到场，平时深聊不多，稳定，但谈不上谁特别拉谁一把。婚后你和妯娌之间也处得和气，你的稳重在这类关系里很受欢迎，很少起大冲突。你最大的隐患不是吵架，是太顾着家族和睦而把自己的利益放在后面，遗产、房产、一起投资这些场合最容易吃亏。\n\n建议分家族资源的时候，你那一份要自己开口去争。别等谁替你想到。跟兄弟姐妹合作做事，用项目制：这一次出多少钱、各占多少、什么时候结账，事先白纸黑字写下来，做完一笔结一笔。借钱也一样，金额和还款时间写清楚。你越怕撕破脸把账糊过去，最后伤得越深。",
  "tianZhai|天相|female": "家在你心里的分量比你以为的还重。从客厅怎么布置到餐桌怎么摆，你都要一个说得过去的样子，屋子顺眼了，你整个人才松得下来。家里的产业，天相庙旺的有一份。装修上你喜欢经典耐看的路子——木头、暖色、收拾得有条理，网上流行的那些款式你新鲜不了几天。\n\n建议你结婚买房要亲自参与挑选。你对房子顺不顺眼特别敏感，别人替你定的房子，你住着总别扭。装修别跟风，钱花在用得久的东西上；防水、水管这些看不见的地方多花点心思验收，合同、收据、保修卡都留好。房子涉及签字过户的事，条款看清楚再落笔，谁催都不差这一天。",
  "fuDe|巨门|female": "你的内心很深。你天生爱钻研、爱探究真相、爱把事情背后的道理想明白。这份能力用对地方就是过硬的研究力。用不对就变成反复回想，一句话、一个表情能让你在心里推演半个月。你这辈子操的多半是心，不是外面来的祸，但心累也是真累，最怕一个人闷在屋里越想越深。\n\n建议你让想法流动起来，别积压。写日记、找人长期聊、认真读点书，都是你的出口。每周至少跟一位不同行业的朋友深谈一次，把心里的分析说出来，本身就是最好的疗愈。给思考设个截止时间，想到点就收。别长时间独自待在密闭的屋子里，出门走走、换个环境，很多想不通的事自己就松开了。",
  "fuQi|太阴|male": "你的另一半多半是温柔细腻、气质安静的一类女性。她善解人意，长相秀气，身上有一股体面劲儿。你自己在感情里很上心，她随口说过的喜好你都记得；但你也敏感，容易想太多，她一句话没回，你能琢磨一整天，需要对方把安全感给足。另一半在你心里分量很重。\n\n建议你把话说出口。你习惯闷着，指望她自己看出来，可她多半看不出来；心里过不去的事，当天讲清楚比憋一周强。挑对象别只看条件，看她情绪稳不稳得住。结婚前后，把跟母亲、跟太太各自的相处先理顺：大事谁定、住得多近、过年怎么安排，早点讲明白，后面大半的别扭都能省掉。",
  "caiBo|（财帛空宫|male": "你的钱来得有起有伏。不是攒下一笔就能躺着吃的路子，靠的是你脑子跟不跟得上。稳稳地帮人做事、领薪水或接活拿报酬，才是你的底子；靠运气博来的钱留不住。把脑子变成钱是你最自然的路——讲课、咨询、做方案、写东西都算。你赚钱的本事强过守钱的本事，想法一多就把钱分到好几个方向，最后哪个都没养大。早年收入起伏大，四十岁以后经验攒够了才慢慢稳下来。\n\n建议你把最好的精力放在一个主要收入来源上。别四处出击。投资方向收到两三个就够，看不懂的新东西先放一放，手上留足现金再谈别的。想试新项目就先设上限：只投亏得起的那一部分。每月发薪当天自动转一笔钱进不轻易动的账户，不靠自觉，靠自动扣款。",
  "fuQi|太阴|female": "你把感情当成一件要好好经营的事。你在意相处时的气氛、情调和细节。你最怕被忽视、被粗糙对待，情感上的伤比身上的伤难好，所以你需要一个情商够用的人。你的另一半温柔体贴、懂情调，可能做设计、艺术、房产或理财这一类工作，会把家里弄得又美又有温度。他帮你的方式不是直接插手你的工作，而是把家撑稳，让你能安心去拼，买房理财上还能给些实在建议。\n\n你们俩都感性，共鸣强。但一起上头的时候负面情绪会互相放大。定个规矩：情绪上来就先各自待半小时，谁先平静谁先开口，不在气头上谈正事。在意的细节直接说出来，别指望他猜——你不说，他是真不知道。难受的时候就讲你需要他陪一会儿，比冷着脸等他发现管用得多。",
  "caiBo|（财帛空宫|female": "你的钱来得有起有伏。靠的是你脑子跟不跟得上，不是攒一笔就能躺着吃的路子。稳稳地帮人做事、领薪水或接活拿报酬是你的底子；靠运气博来的钱留不住。把脑子变成钱最自然——讲课、咨询、做方案、写东西都算。你赚钱的本事强过守钱的本事：研究东西、比价格你是行家，可看得越多买得越多，订阅、护肤、小物件一笔笔加起来，是看不见的漏钱口子；心里不痛快的时候，更容易靠买东西转移注意力。\n\n建议你给自己定个等待期。想买的先放进清单，等满三天再决定，多数时候就不想要了。把每月的订阅列一张表，用不上的直接退掉。投资方向收到两三个，看不懂的先不碰，手上留足现金。记账你本来就在行，再加一条：每月发薪当天先自动转走一笔存起来，剩下的才是能花的。",
  "jiE|七杀|male": "你底子好、体能在人群里算强的。但越硬的东西越容易断：平时扛得住，一旦透支就可能突然垮下来，走两个极端。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗七杀的五行去配；磕碰摔伤这类意外也要留心。长期高强度工作、休息不够，抵抗力也会跟着掉。\n\n建议你定期体检。《全书》卷二疾厄七杀条说「七杀幼年多灾，长主痔疾」，体检时肛肠这一项别漏；身体有不舒服早点看医生、按医生说的办，别自己扛着。饮食少辛辣、少烟酒，蔬菜多一点。你爱运动是好事，但要加一些拉伸和柔韧的练习，别只练猛的，也别带伤硬上。最难也最重要的一课是学会休息。",
  "xiongDi|破军|male": "你和兄弟姐妹的缘分偏浅。从小聚少离多，长大各奔东西，平时不联系、出事才想起对方。这不是谁冷漠，是你这种人的性子本来如此。不过也不是每个人都这样，有人兄弟姐妹不少、处得也不错，不能一概说没缘分。合伙你最适合找同样爱开创的搭档，一起做那种拆了还能重建的事，不适合只想守摊的人。\n\n建议你合伙前把“做不起来就拆伙”的话讲在明处。出资、分工、怎么退出，白纸黑字写下来。你本来就不擅长长久绑定，先留好退路比硬撑更稳。和兄弟姐妹不用强求常联系，逢年过节打个电话、家里有事真出面，比表面热络管用。化权（掌权）时兄弟或合伙人手上有权，是拍板改革的那个，你要给自己留一份否决权。",
  "qianYi|天梁|male": "你一出门就容易碰上人拉一把。离开老家反而比守在原地顺，帮你的多半比你年长、有资历。要留神的是：你在外地特别容易变成谁有事都来找的那个人，来者不拒，最后自己累趴下。\n\n建议你出门先把自己的事排在前面。房子、工作、身体安顿好了再谈帮谁。别人开口求你，先别急着答应，说一句我想想再回你，多数事第二天就不用你管了。到了新地方主动认识几位年长的同行，他们能帮你的不少。去远地方的大决定，留两周再拍板，别当场应下。",
  "tianZhai|贪狼|male": "你的家一般布置得有品味。你还会留出能玩的地方，影音、酒柜、牌桌之类，朋友都爱往你这儿凑。家底上，上一辈留下的东西你多半指望不上。\n\n建议你装修先把预算定好。样板间好看的东西，落到自己家一半用不上。家里少摆酒柜、烟具这些随时能勾起你的东西，眼不见心才静。用火用电别马虎，插线板、燃气、油烟机定期检查。每周固定留一顿只有家里人的饭，家一旦只剩聚会，感情上的裂缝是一点点变大的，等发现就晚了。",
  "jiE|七杀|female": "你底子好、体能在人群里算强的。但越硬的东西越容易断：平时扛得住，一旦透支就可能突然垮下来。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗七杀的五行去配；磕碰摔伤这类意外也要留心。备孕时压力大、休息少，会比别人更费劲；怀孕期间你又不肯示弱，容易累过头。更年期前后是一道大考，一辈子硬拼欠下的账容易一起找上来。\n\n建议你从四十岁起就把体检做全。全面体检加上女性的常规项目，一年一次别漏；《全书》卷二疾厄七杀条说「七杀幼年多灾，长主痔疾」，肛肠这一项也别漏。身体不对劲早点看医生，按医生说的办，别自己扛着。饮食少辛辣、少烟酒，蔬菜多一点。运动要加拉伸，别只练猛的。备孕和怀孕期间主动把节奏降下来，该歇就歇。",
  "xiongDi|破军|female": "你和兄弟姐妹的缘分偏浅。从小聚少离多，长大各奔东西。不过也不是每个人都这样，有人兄弟姐妹不少、处得也不错，不能一概说没缘分。婚后和丈夫家的嫂子、弟媳处起来，你天然带着距离感，那套客套寒暄你受不了，所以显得不热络。合伙做事你最大的隐患是一上来就要“全部重新设计”，搭档跟不上你的节奏。\n\n建议你合伙先观察三到六个月。摸清对方的节奏再动手改，改之前先讲清为什么改、改成什么样。出资、分工、怎么退出，白纸黑字写下来。和她们相处不用勉强亲密，该到的礼数到位就行，把心力留给真正处得来的人。化权（掌权）时兄弟或合伙人手上有权，是拍板改革的那个，记得给自己留说话的余地。",
  "qianYi|天梁|female": "你一出门就容易碰上人拉一把。离开熟悉的地方反而比守在原地顺，帮你的多半比你年长、有资历。远嫁对你有额外的好处：你成熟、不卑不亢，很快就能在婆家站稳，甚至成了那边的主心骨。代价是跟父母的距离——你跟他们牵绊深，人在远处，心一直挂着。\n\n建议你跟父母定一个固定的视频时间。每周一次，牵挂有出口就不至于变成心事。去远地方的大决定，给自己留两周再拍板，别在饭桌上当场应下。在婆家当主心骨可以，但别把所有事都接过来，留一点给别人做。",
  "tianZhai|贪狼|female": "你的家一般布置得好看、有点艺术味。你还留着能招呼朋友的地方，大家都爱往你这儿聚。家底上，上一辈留下的东西你多半指望不上。\n\n建议你结婚前想办法给自己置一套小房子。哪怕小，那是你的底气。装修先把预算定好，样板间里好看的东西，落到日子里一半用不上。用火用电别马虎，插线板、燃气、油烟机定期检查。每周固定留一顿只有家里人的饭，家一旦只剩聚会，感情上的裂缝是一点点变大的，等发现就晚了。",
  "mingGong|破军|male": "你天生是个爱变的人。叛逆、有创造力，对老规矩本能地反感。别人觉得没路的地方，你能找到口子；别人还守着现状，你已经在想下一步。弱点是稳不住，事情刚有起色，你又想去开新的一摊。性子偏孤僻，不太看重钱，身材偏瘦。和家人、长辈的缘分偏浅，朋友圈换得快，真正留下来的是被你才华吸引来的人。压力一大，你的本能是抽身走人。\n\n建议你离开家里原有的老路子。靠一门手艺往外闯，这才是你走得通的方向。拆掉旧的之后，逼自己把新的建起来，别拆完就走——挑一个领域待够三年，把它做出个样子。做决定靠直觉可以，但大事先睡一觉再拍板，给冲动加一道缓冲。",
  "personality|破军|male": "你天生是个爱拆的人，不是有恶意，是你安不下现状。一份稳定工作做上三年就想换，一套用惯的流程看一眼就想改，一条老规矩摆在面前，你第一反应是“为什么非得这样”。这让你在开创上少有人比得过，在守摊维持上却几乎做不到。你性子偏孤僻，不太为了合群委屈自己，也不太把利益放第一位。脑子跳得快，别人想三步你想到十步，中间那几步常常是断的。\n\n建议你挑军警、手艺、创业、改革、重建。这类都是拆了还能建起来的行当，别去按部就班的岗位，你会被无聊磨死。想法跳跃就随手写下来，回头补中间那几步，别指望别人跟得上。中年是你的一道坎：挑一个领域真正沉下来做满五年，这一条决定你这辈子是开创者，还是只会拆的人。",
  "guanLu|贪狼|male": "你的事业吃两样东西：会的多，想要的也多。越是人多、热闹、靠嘴和关系打开局面的行当，你越吃得开，比如表演、餐饮、娱乐传媒、旅游商贸、美容这一类。你在团队里是活跃的那个，能露脸、能拉来人，但要你埋头磨三年的活儿，耐性就不够了。早年收入起落是常态，真正的高峰在中年以后。\n\n建议你挑定一个方向后至少做满五到七年再谈转行。换得太勤，手上攒不下真本事。创业可以，但账交给一个稳重的合伙人管，你只管往外跑、谈人、拓市场。贵人多半是圈子里人气最旺的那几位，机会都是人带来的。别让感情上的事拖进工作里，这是你最容易翻车的地方。",
  "caiBo|七杀|male": "你的钱来得快、去得也快。好的时候一笔大进账，差的时候一笔大亏空，起伏很明显。你是那种一个人硬扛着往前拼的人，钱挣进来了也不容易存住，赚得到、守不住是你最大的坎。固定收入靠本事和实干；靠机会赚的那一份，因为你敢冒险，会比别人多，但也容易在激进的投资上亏掉一大笔。漏财最多的是冲动下注、赌气花钱，还有动作太快、合同没写清楚。\n\n建议你做强制储蓄。钱一到账先划走一部分，剩下的才是能花的。投资分成两份，保底的那份不动，另外一份才拿去博高回报，本钱先保住。大额投入前先花几天把对方和项目查清楚，合同逐条看完再签。年轻时先把专业底子打扎实，中年以后用稳一点的方式攒钱。",
  "mingGong|破军|female": "你天生爱闯、爱变。对固定的老规矩打心里反感，永远在找突破口。你独立性极强，和家人有种若即若离的距离感，心思不容易被人看透——这既是保护，也是隔阂。你性子偏孤僻，身材偏瘦小，不太看重钱。才华需要时间沉淀：前期路子多变、不太稳，一旦找到真正属于自己的方向，能做出很亮眼的东西。\n\n建议你把走出去当成正路。靠一门精细的手艺或专业立住名声，比守在原地强得多。自由探索的同时给自己设个期限，比如三年，在一个领域里扎下去，让才华有落脚的地方。找伴侣要找能接受你不断变化的人，不是想管住你的人。",
  "personality|破军|female": "你不甘心照着别人给女性写好的剧本过日子。从年轻时就想活成自己的样子。你敢打破规矩、敢推翻成见、敢做别人不敢做的选择，这让你在事业和创业上格外有冲劲，人生的起伏也比别人大。你不太合群，也不太把利益算得那么精。破军的人「人呢瘦瘦的」，这是以相对命的一条，要当面对照。稳定、重复、被框住这三件事你都受不了，朝九晚五对你是种折磨。\n\n建议你往创业、艺术、媒体、改革型岗位去。这类都是容得下你这股劲的地方，别硬待在凡事按规矩办的传统单位。感情上晚一点定，年轻时你太冲，遇到的人也聚散无常，等自己沉下来再选。年轻时你拆掉了很多旧的，中年该试着搭一次——不是把过去搭回来，是搭一个只属于你的新东西，挑一个方向做满五年。",
  "guanLu|贪狼|female": "你的事业靠两样：会的多，想要的也多。凡是靠人气、口碑、个人风格吃饭的行当你都合适，美容、时尚、直播带货、活动策划、餐饮品牌、销售都算。你最会露脸、最会拉关系，但要你埋头磨几年的活儿就坐不住。早年靠长相、人缘、圈子，机会常常来得比本事快，这是红利也是陷阱：红利期一过，没攒下真本事的人，路会明显变窄。\n\n建议你在二十五到三十岁这几年就动手。把人气换成能留下来的东西：一张过硬的资格证、一套替代不了的技能，或者一个自己的牌子。挑定方向后至少做满五到七年再谈转行。也别把自己只锁在「靠魅力」这条路上，管理、带团队、扛业务这类硬岗位你同样做得来。打算生孩子的话，产后的恢复和情绪起伏提前排进计划。",
  "caiBo|七杀|female": "你的钱来得快、去得也快。好的时候一笔大进账，差的时候一笔大亏空，起伏明显。你的钱是跑出来、闯出来的，金融、销售、创业、外贸这类节奏快的路子最合你，赚得到、守不住是最典型的坎。有个盲点值得一提：你对自己特别苛刻，事业最忙的那几年，吃穿用度反而将就；另外越能赚，你在家里说话越硬，丈夫容易觉得自己被晾在一边。\n\n建议你做强制储蓄，钱一到账先划走一部分。投资分成两份，保底的那份不动，另外一份才拿去博高回报。每个月留出收入的百分之五到十，专门用来犒劳自己，买想要的东西、出去玩都行。家里的大笔开销和买房投资，主动叫上丈夫一起决定，让他有参与感；同时自己留一个独立账户，这件事一开始就谈清楚更好。",
  "mingGong|天相|male": "你天生适合做那个把事情做稳的人。你为人忠厚，做事守规矩，说到做到。越是要细心、按规矩来、能长期坚持的活，你做得越漂亮。你不是没脾气的老好人，看见谁做得不地道，心里那口气压不住。弱点是太厚道，争利益的场合容易吃亏，不会替自己开口，常常能力很强却因为不爱表现被忽略；长期不被当回事，心里会积下很深的委屈。\n\n建议你把自己做过的事主动说出来。不是邀功，是让人知道活是谁干的。开会先讲一句自己的判断，别一上来就问别人怎么看，问着问着主意就没了。遇到规则之外的新事，找一个敢闯的人搭伙，你负责稳、他负责冲。该松手的事就松手，别拿死磕当负责。",
  "personality|天相|male": "你是那种放在哪都让人放心的人。你稳重、配合度高、爱面子但不张扬。给带头的人当左右手，比自己当头儿舒服；你不爱冲在最前面，可凡是你接下的事都办得妥当。说话实在，不来虚的；看见别人有难会心软，看见谁做得不地道心里就来气——你不争不抢，但那把是非尺很直。你讲究体面，穿着、谈吐、家里的样子都有分寸，这不是显摆，是你觉得做人就该有个样子。\n\n你的短板不是没主见。你认定的事别人很难把你带偏；短板是不肯先开口——该自己拍板时习惯先问一圈，问着问着自己的判断就没了。建议下次拿主意，先把自己的答案写下来，再去听别人的意见。做配角不丢人，但你要确认这是你自己选的位置，而不是从来没给自己上过场的机会。",
  "caiBo|天府|male": "你的钱是攒出来的，不是搏出来的。收入主要来自稳定的工作和日积月累的储蓄，因为花钱有节制，时间一长家底自然厚，属于细水长流那一类，中年以后手里会相当充实。你守钱的本事强，不会冲动乱花，但有时省过了头，该花在身体和生活上的钱也舍不得。真正漏钱的地方有两个：一是太保守，好机会摆在眼前也不敢上；二是感情和家里的大额开销。\n\n建议你把钱分成三份。大头放长期拿得住的地方，比如自住的房子，或者风险低、放着安稳的存款和理财；一小份应急；再留一小份专门试机会，亏光了也不影响日子。投资上你适合买了就放着，别频繁进出，高风险的金融产品不碰。每年给自己定一笔非花不可的预算，用在体检、学习和休息上。婚姻稳，你的财才稳。",
  "mingGong|天相|female": "你做事细心周到。别人顾不上的地方你都能照顾到，不管在单位还是在家里，你都是那个撑住局面的人。但很多活是你干的，最后台前的光环常常落在别人身上。温和配合只是你的外表，心里那股志气一点不比男人小，别把自己只当配角。感情上你忠诚稳定，认定一个人就全力经营；但配合得太过，你的主张会一点点消失，委屈越积越多。\n\n建议你练两件事。一是把自己的需求说出口，想要什么、不接受什么，讲清楚比忍着强；二是给自己划一条线，别人的事你帮到哪一步，心里要有数。工作上行政、法务、人力资源、助理这类岗位你最出彩，但别停在只做执行，每年主动向上提一次自己的想法。要找的是看得见你付出的人，把你的好当成理所当然的，不值得你耗。",
  "personality|天相|female": "你得体、周到、顾家。你是别人口中“会过日子”的那种女人。你不爱争先，但事情到你手上都处理得妥当；不擅长制造话题，却能把一个家安排得井井有条。你讲究体面，从穿衣到待客都有分寸，不想让家人在外人面前失了面子。要说清楚的是：你的温和是修养，不是没志气，这两件事别混为一谈。你不是没有自己的想法，只是习惯把它排在别人后面。\n\n建议你从小事开始，把自己排到前面一次。这顿饭按你想吃的点，这个周末按你想去的地方安排。别人开口求你，先问自己一句今天有没有余力，没有就直说。每年给自己买一件贵一点、只为自己开心的东西。二十年后回头看，你为家人做的那些事会被忘掉一半，但那件东西你每次拿起来都会笑。",
  "caiBo|天府|female": "你的钱是攒出来的，不是搏出来的。收入主要来自稳定的工作和日积月累的储蓄，花钱有节制，时间一长家底自然厚，中年以后手里会相当充实。你很会经营一个家的账本，丈夫和孩子都能因为你的规划受益。你看重的是实打实的保障，房子、存款、保险这些，不图面子上的排场；也会留一笔自己的应急钱。漏钱的地方有两个：太保守错过好机会，以及家里的大额开销没提前规划。\n\n建议你每个月固定留一笔给自己的预算。这笔钱用在学习、健身和形象上。你对别人大方、对自己太省，这笔钱看着像花掉了，其实是把生活的质量买回来。投资上你适合买了就放着，别频繁进出，高风险的金融产品不碰。夫妻两个人的钱当一盘棋来安排，每年坐下来对一次账。婚姻稳，你的财才稳。",
  "mingGong|太阳|male": "你天生外向，热情大方。你走进哪个群体都能把气氛带起来。你最大的本事是影响力——说话做事自带感染力，别人容易信你、愿意跟着你走，在公开场合尤其出彩。弱点是太在意别人怎么看你，名声对你几乎跟命一样重，一有损形象的事就焦虑，光撑着这个形象就耗掉不少力气。你朋友多、不挑身份，但关系广而不深，真能走进你心里的没几个；外面看着风光，一个人待着时反而容易怀疑自己。\n\n建议你每周留出固定的独处时间。别一停下来就急着找事做。遇到误解和差评，先压两天再回应，你越急着挽回，事情往往闹得越大。重要的决定隔一夜再拍板，别在情绪上头的时候下判断。朋友里挑两三个敢跟你说实话的深交，剩下的按交情来就行。",
  "personality|太阳|male": "你是那种一走进房间就能把气氛点起来的人。你大方、直率、爱笑、敢表态，陌生人很容易喜欢你，因为你不藏心思。但这份阳光是有代价的：你不擅长反省，也不擅长独处，停下来想事对你是种煎熬，所以你干脆不停地忙。你看重面子胜过里子，这不是虚荣，是你真觉得被人看见很重要，年轻时也因此容易把自己累垮。太阳落陷（力量弱）的人更明显，付出多、回报慢，名声来得晚，脾气也更拗。\n\n建议你每天留半小时不干活、不见人。哪怕只是走一走，习惯了就不难受了。累了就直说，别硬撑到身体报警。那股倔劲用在真正值得坚持的方向上，认死理之前先问自己一句：这是对的，还是我只是不想认输。你要学的不是更拼，是把照出去的光收回来一点给自己用，剩下的才照得久。",
  "fuQi|天同|male": "你在感情里温柔体贴。你愿意为了不起争执先退一步，跟你在一起的人会觉得舒服、没压力。你不太看重对方的家底，更在意两个人合不合得来、日子过得暖不暖。你太太多半性格温和、会过日子，可能做服务、设计、餐饮这类跟生活美感有关的工作，能把家布置得让人待着不想走。她不一定帮你在外面打天下，但你累了回家能缓过来。你们都不爱吵，问题反而出在太安逸，久了容易没热度。\n\n婚事不用赶，你晚一点成家反而更稳。古书说天同在夫妻宫夫宜年长、妻宜年少，你比她大一些相处更自在；这是参考，不是硬条件。日常别把「不吵架」当成感情好，主动安排点两个人一起做的新事——出去旅行、学一门手艺、换个地方住一阵都行。她提要求时别一味答应了事，把自己的想法也讲出来，感情才不会变成你一个人在迁就。",
  "jiE|廉贞|male": "你身上有股火气，情绪起伏大。火一上来身体跟着有反应：容易上火、睡不安稳。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗廉贞的五行去配。你的健康和心情基本是一回事，生气、憋闷、感情上受挫的时候，人很快就垮下去一截。喝酒和重口味会让这股火更旺。\n\n建议你每年定期体检。查哪几项听医生安排；有不舒服就去看医生、按医嘱来，别自己扛着，也别上网对号入座吓自己。吃得清淡些，蔬菜多吃，辛辣和酒少碰。找一项能把火发出去的运动，跑步、打拳、跳舞都行，一周三次，比吃什么补品都管用。真要安排手术，提前跟主治医生把时机和准备聊清楚。",
  "xiongDi|武曲|male": "你的兄弟姐妹多半个性刚、各过各的，人数偏少。你们从小也谈不上腻在一起。这不是感情不好，是你们这一家人都习惯把事情摆在明面上讲，谈事容易，谈心难，不用强求手足之间非得亲密无间。你跟他们之间，钱的关系往往比感情的关系更实在：亲兄弟也明算账，借钱要打借条，合伙要写合约。\n\n建议你别做那种「够意思就行」的口头合伙。这在你身上翻脸的概率很高。要一起做事，就按项目来，合约写细，分账和退出怎么办先谈清楚，最好有个双方都认的第三方看着账。",
  "ziNv|天府|male": "你的孩子多半好带。他从小省心，不叛逆、不出格，学业稳定，跟人也处得来。真正要留心的不是他会闯祸，而是他太不闯：习惯了安稳，容易规规矩矩过完一生，少了试错的胆子。\n\n建议你主动给孩子安排安全的冒险。一个人出趟远门、去外地实习、参加户外营或游学都行。不用真让他吃苦，但要让他见过世面，再自己选走哪条路。孩子说一个你不认同的打算，先别急着否决，问三个问题：钱从哪来、最坏会怎样、多久看结果。他答得上来就让他试。",
  "tianZhai|紫微|male": "房子是你这辈子最重要的钱袋子。而且靠你自己买下的那套最旺，指望家里留下来的反而不是主线。你对住的地方要求高：地段、面积、装修都得撑得住场面，这也是你花钱最凶的一块。\n\n买房先挑地段好的。市中心、地铁口、好学校旁边，占住一样也行，这是你家底的根。二线以下城市纯为赚差价买房要慎重，你的钱是靠好资产慢慢涨出来的，不是靠短线倒手。买之前把产权写谁的名字、家里的钱谁管，跟妻子摊开讲清楚。装修走稳重路线就好，太张扬反而招闲话。",
  "fuDe|天机|male": "你心里其实挺热闹。好奇心一直在线，对哲学、宗教、命理这些想不明白的事有天然的兴趣，读得越深越上瘾。你的日子多半是先累后闲——年轻时精神头都耗进去了，中年往后才慢慢得空。你享受琢磨事情的乐趣，也被它困住：脑子像不关机的机器，出成果的时候是天赋，停不下来就成了负担。\n\n建议你每天固定留一段只用身体、不用脑子的时间。走路、拉伸、做饭、修点东西都行，让注意力落到手上。中年以后挑一件专注一处的事长期做：打坐、太极、瑜伽、长跑都行，光靠读书和聊天压不住你这份心思。再定条规矩：一件事想过三天就必须挑一个，挑错了边做边改，别在脑子里熬通宵。",
  "fuMu|天相|male": "你的父母多半是讲规矩、有教养的那类人。家里可能出过公务员、老师或者专业岗位上的人，你从小在一个体面的环境里长大。你跟父母的缘分不薄，相处平和，少有大的分离和争执。这份家底给你的不只是条件，还有一套做事的分寸感，你身上的稳，很大一部分是从他们那儿来的。\n\n有一点要早做安排。家里长辈答应过的事、老人的房产和合约，最好趁大家都清楚的时候白纸黑字写下来，别指望口头说过就算。父母年纪上来，定期带他们体检，别等出事才跑医院。职场上你跟强势、说话有分量的上司最合得来，可以主动去找一位愿意带你的领导，跟对人对你的事业加成很明显。",
  "mingGong|太阳|female": "你外向、热情、讲公道。你人缘一向好，是朋友圈里大家最信得过的那个。太阳守命的女命，《全书》按太阳的亮度和有没有煞星分开断。父亲、丈夫的情况另看父母宫、夫妻宫的太阳和大限，不从命宫太阳直接断。化忌（阻碍）时，名声上的麻烦或者丈夫那边的是非，会直接压到你身上。\n\n建议你不管结不结婚，都给自己留独立的收入和账户。底气要握在自己手里。身边有资源的男性长辈和同事，该请教就请教，但别把整条路押在某一个人身上。挑伴侣看他做事扛不扛得住，别只看头衔和排场。他忙起来顾不上你时，与其等他回头，不如把自己的事排满，你越有自己的重心，这段关系反而越稳。",
  "personality|太阳|female": "你身上有一股果断、能扛事的劲儿。别人还在犹豫，你已经动手了。这让你在职场上很吃得开，但放在老一辈对女人的那套期待里，常被说太冲、不够软。你不会撒娇，也很难把光让给别人、安静做个贤内助——不是不愿意，是做不到，硬做也别扭。所以你在婚姻里常常不知不觉就走到主导的位置，不是你要抢，是天性如此。你人缘很好，心里其实也想被人照顾，只是从来不开口要。\n\n建议你把想要的直接说出来。累了就说累了，想被抱一下就说出来，别人不会读心。硬和软可以同时存在，白天你照样是那个发光的人，晚上允许自己也需要人哄。太阳落陷（力量弱）时脾气更拗，认准的事不肯回头，争理时容易伤人；养成一个习惯，话到嘴边先数三秒再出口，口才用在把事办成上，别用在争输赢。",
  "fuQi|天同|female": "你在感情里温柔体贴。你凡事以和为贵，为了不起争执愿意先退一步，跟你在一起的人会觉得放松、没压力。你不太看重对方的条件，更在意两个人过日子合不合拍。你先生多半性格温和、懂得享受生活，可能做服务、艺术、设计、餐饮这类跟美感有关的事，把家过得舒服是他的长处。他不一定在外面替你冲锋，但你累的时候他能给你缓过来的力气。你们都不爱吵，问题反而是太平静，久了容易没劲。\n\n婚事不用赶，晚一点成家对你反而更稳。古书说天同在夫妻宫夫宜年长、妻宜年少，对方比你年长一些相处更自在；这是参考，不是硬条件。日常别用一味迁就去换和气——你不说，他是真的不知道。有想法就当场讲，讲完照样可以温柔。两个人要有一起做的新事，出去旅行、学点什么、换个环境住一阵都行，感情才不会停在原地。",
  "jiE|廉贞|female": "你身上有股火气，情绪起伏大。火一上来身体跟着有反应：容易上火、睡不安稳。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗廉贞的五行去配。你的健康和心情基本是一回事，生气、憋闷、感情受挫的时候，人很快垮下去一截。每个月那几天，量和天数变化明显的话别拖着，去查一下。\n\n建议你每年定期体检。全面体检和女性的常规检查都别落下，有不舒服就去看医生、按医嘱来。吃得清淡些，蔬菜多吃，辛辣和酒少碰。找一项能把火发出去的运动，跑步、跳舞、打拳都行，一周三次。怀孕前后情绪起伏大的话，提前跟家人说好请他们搭把手，需要时找专业的人帮忙也很正常。要安排手术，提前跟主治医生把时机和准备聊清楚。",
  "xiongDi|武曲|female": "你的兄弟姐妹人数偏少，各人个性都硬。你们从小就谈不上腻在一起，谈事容易，谈心难。你们之间钱的关系往往比感情的关系更实在，亲兄弟姐妹也明算账，借钱打借条，合伙写合约。真要起波澜，多半也是在钱上：分家、老人赡养、一起投了什么，这几处最容易闹。婚后跟丈夫家的嫂子、弟媳相处，对你也是一道考验。\n\n建议你别勉强自己变成那种把感情挂嘴上的人。你不擅长说的话就用动作来做：记住生日、逢年过节带点东西、有事先问一句。合伙的事，账目和分成讲在前头，退出怎么办也先谈好，你的直来直去配上清楚的规矩，才不会被当成不近人情。",
  "ziNv|天府|female": "你的孩子多半好带。他从小是省心型，不叛逆、不出格，学业也稳。你做妈妈特别有优势，你的稳重让孩子从小就有安全感，亲子关系一路都稳。真正要留心的是另一头：你的疼爱容易把孩子护得太严实，安稳给多了，他反而少了去闯、去试错的胆量。\n\n建议你主动给孩子安排安全的冒险。户外营、一个人出趟远门、去外地实习或游学都行，让他把眼界打开再回来选路。孩子提一个你不认同的打算，先别急着否决，问他钱从哪来、最坏会怎样、多久看结果；答得上来就让他试。你的担心可以说出来，但说完把决定权还给他。",
  "tianZhai|紫微|female": "你对家的要求高。地段、品位、住着舒不舒服、能不能请人来坐坐，样样都要顾到，这也是你花钱最凶的一块。房子这件事，靠你自己买下的那套最旺。跟公婆住在一起多半不合适——你的做派和花钱习惯，在老一辈眼里容易被看成不会过日子。\n\n结婚前就在自己名下买一套小房子。这是最要紧的一条建议，哪怕小也要有。这不是为离婚做准备，是给自己留一块谁也拿捏不了的底气。婚后哪怕跟公婆住得近，也一定各住各的。买房之前，把产权写谁的名、家里的钱谁管、以后跟谁住，跟丈夫一条条谈明白，落到纸上。",
  "fuDe|天机|female": "你心里有一个别人看不见的世界。各种可能在脑子里翻来覆去地算，对哲学、命理、修行、艺术有真兴趣，一头扎进去能待很久。你的日子多半是先累后闲，年轻时心里的劲儿都耗在想事上，中年往后才慢慢松下来。你这辈子最难的功课就是按下暂停键——想得停不下来的时候，凌晨三点还醒着，第二天什么都干不动。\n\n建议你每天留出半小时不动脑子的时间。冥想、瑜伽、慢跑、养花、画画都行，让注意力落在手上和身体上。睡前把没想完的事写在纸上，写完合上本子，告诉自己明天再说。中年以后可以学打坐这类专注一处的功夫，也可以找专业的咨询师聊一聊，把心里的事说出来比自己闷着强。",
  "fuMu|天相|female": "你的父母多半讲规矩、有教养。家里可能出过公务员、老师或者专业岗位上的人，你从小在一个体面的环境里长大。你跟父母缘分不薄，相处平和，少有大的分离和争执。结婚以后，你很容易成为公婆嘴里的模范儿媳——稳重、得体、肯配合，人人都夸。但这份夸奖是有代价的：夸着夸着，家里的事就默认该你做了。\n\n建议你小心被夸奖绑架。想做个好儿媳没错，但别拿自己的边界去换一句好评。老人的事、家里的活，早点把分工摆到桌面上按人头谈，别默认谁顺手谁上。长辈答应过的事、老人的房产和合约，趁大家都清楚的时候白纸黑字写下来，别指望口头说过就算。父母上年纪了，定期带他们体检，别等出事才跑医院。",
  "guanLu|太阴|male": "你的路子在美感和人情上。房地产、文化艺术、设计、时尚美容、心理咨询、教育、财务这些要细心、要审美的行业最容易出成绩。环境有温度你效率就高，天天比业绩、硬碰硬的地方你待着难受。团队里你是调气氛的那个，谁跟谁别扭你一眼看得出。你的钱适合来自稳稳的收入：领固定薪水、把专业做深，比下海冒险稳当。帮到你的人常是有资源、有眼光的女性长辈。\n\n挑一个领域扎下去，把口碑做起来，收入自然就稳。真要自己干，选小而精的方向：个人品牌、设计、咨询这类，别做要砸大钱、拼速度的生意。你擅长照顾别人的感受，但该说的不同意见还是得说，不然久了没人把你当回事。你太在意别人怎么评价你，一句话能让你半天静不下来——把在意的评价攒到一处，固定时间看一次，别随时接。",
  "ziNv|七杀|male": "你的孩子从小就有自己的主意。像个小将军，不太肯被大人完全管住。孩子多半不会太多，晚一点当爸爸反而更从容。最容易出问题的是青春期那几年：你越拿家长的身份压他，他越往外躲，硬碰硬只会把人推远。这样的孩子如果放对地方，比如军警、创业、运动、科研这类要闯劲的路，往往能做出成绩；硬要他当个乖小孩，双方都难受。\n\n建议你早早把规矩立好，规矩之内放手，别管细节。跟儿子说话少下命令，多摆事实让他自己选，选错了让他自己收拾后果。孩子长大以后多半会往外走，求学或工作都可能离得远，聚少离多是常态，所以从小就把感情联结做扎实：固定通话、记得他的事，距离才拉不散。",
  "jiaoYou|贪狼|male": "你的朋友从老板到普通同事都有。从艺术家到生意人也都有，这是你最值钱的本事：认识的人能换成机会、消息和资源。麻烦也在这里，陪你喝酒玩乐的人特别多，真到要紧关头能出手的没几个。用人也要留神，看着最风光、最能干的那位，反而容易在关键处给你捅娄子。\n\n建议你把朋友分三层记清楚。分别是能在事业上帮你一把的、能一起做生意的、只能一起吃饭喝酒的，心里有数就不会指望错人。用人先给小事，做成了再加担子，别一上来就把钱和公章交出去。哥们义气是你最容易栽的地方，担保、借钱、合伙这三样，答应之前先隔一天再回话。",
  "fuMu|破军|male": "你和父母的缘分偏浅。往往聚少离多，成长过程中常是父母不在身边，或者人在身边、心却不亲。你心里有他们，只是表达不出来，也很难像别人那样自然地亲近。父亲对你的影响多半是两种：要么管得很严，要么长期缺席。和父亲的和解，是你中年以后要过的一道关。\n\n建议你别等父母开口。中年以后主动给他们安排常规体检，有情况听医生的、遵医嘱，别自己上网对号入座。离得远就把联系做成固定动作：每周一个电话，说三分钟也行。和父亲之间不用非要谈开，一起做点具体的事——修个东西、陪他们跑一趟医院，比谈心有用。",
  "guanLu|太阴|female": "你的路子在美感和人情上。房地产、文化艺术、设计、时尚美容、心理咨询、教育、财务这些要细心、要审美的行业最容易出成绩。团队里你是调气氛的那个，谁跟谁别扭你一眼看得出，做事也细，但天天比业绩、硬碰硬的地方你待着难受。你的钱适合来自稳定的收入。最大的隐忧是家里或感情一乱，工作输出跟着掉，容易给上司留下不稳的印象。\n\n把生活和工作的门关严，家里的事别带进办公室。备一份低谷清单，状态差那几天只做上面三五件，别让情绪把整块工作拖下去。打算生孩子，就提前把带娃的人手排好，别一个人硬扛，回职场那阵的拉扯会小很多。四十岁以后可以往更自主的方向走，像设计师、咨询顾问这类靠专业吃饭的活，但底下仍要有稳定的收入托着。",
  "ziNv|七杀|female": "你的孩子从小就有自己的主张。不太肯被完全管住，身上有股闯劲。孩子多半不会太多，晚一点生反而更从容。最容易出问题的是母女之间：女儿越大越像另一个你，你越压她越顶，你管得越细她躲得越远，两个人容易变成较劲。孩子如果走军警、创业、运动、科研这类要闯劲的路，往往能做出成绩。\n\n建议你把管教换成定规矩。底线讲清楚，细节放手，让孩子自己承担选错的后果。跟女儿少下命令、多商量，把她当成一个能自己拿主意的人来谈。别为了孩子把自己的事业全放下，你有自己的一片天，母女之间反而更松快。孩子长大以后可能去外地发展，固定通话、记得她的事，距离就拉不散。",
  "jiaoYou|贪狼|female": "你认识的人多而杂，闺蜜一大把但质量参差。这是你最值钱的本事：认识的人能换成机会和资源。麻烦也在这里，陪你逛街喝酒的多，真到要紧关头能出手的少；越是看着风光能干的那位，越要看清楚再托付。男性朋友里对你有意思的特别多，处得好是贵人和生意伙伴，处不好就是没完没了的纠缠。\n\n建议你跟男性朋友把界线摆到明面上。不深夜单独见面、不深夜聊私事、来往尽量放在能看见的场合。已经结婚的更要注意，你天然的亲和力容易被外人解读成别的意思，伤的是家里的信任。朋友分层记清楚：能帮你办事的、能做生意的、只能一起玩的。借钱、担保、合伙，答应之前隔一天再回话。",
  "fuMu|破军|female": "你和父母的缘分偏浅。往往聚少离多，成长过程中常是父母不在身边，或者人在身边、心却不亲。你心里有他们，只是很难像别人那样自然地亲近。婚后和公婆相处，你最受不了的是“装乖儿媳”这件事——你那股劲压不住，硬装下去自己先崩。\n\n建议你中年以后主动给父母安排常规体检。有情况听医生的、遵医嘱，别自己上网对号入座。离得远就把联系做成固定动作：每周一个电话，说三分钟也行。和公婆相处，该到的礼数一样不少，情感上保持独立，不勉强亲密，长期反而处得住。职场上你和那种敢做改革的女上司最合得来，遇到了就跟紧。",
  "fuQi|七杀|male": "你在感情上很直接。你喜欢就追，不喜欢就走，不会绕弯子，有时候会让对方觉得有压力。你很看重自己的空间，不喜欢黏得太紧，也不想成为谁的负担。你的妻子多半也是个有主见的人，有自己的事业和野心，可能做军警、创业、外贸、运动这类需要闯劲的工作，不会因为结婚就放下自己。你们互相欣赏，也容易互相较劲；两个人都不肯先低头的时候，家里就容易冷场。\n\n建议你不用急着成家。晚一点结、把磨合的时间留够，反而更稳。平时把两个人的界线谈在前面：各自的事业、各自的朋友、钱怎么管，先说清楚，好过事后争输赢。吵完之后记得主动走回去一步，说句软话、做顿饭都算，你们不缺火花，缺的是收场时的温柔。",
  "qianYi|贪狼|male": "你在外面跑比守在家里有机会，但也确实累。你的钱常常是从饭局、应酬、人情来往里挣出来的。出差调动对你多半是好事，动一动常常就往上走一格。另一面也得说清楚：外地的酒局、夜场，能让你动心的人格外多，人在外地又容易放松，这几样凑一起最容易出事。\n\n建议你出差立几条硬规矩。晚上尽量不去酒局，喝了酒不开车，异性单独邀约推掉或者带上同事。钱包也要设防，赌场、夜场、奢侈品这三样在外地最容易失手。证件和行程自己收好，发一份给家里人。在外面挣的是人情钱，谁帮过你记下来、事后补上，比多喝三杯管用得多。",
  "jiaoYou|太阴|male": "你的朋友圈以女性为主。男性朋友数量少，但交下来都稳。\n\n跟女性朋友把界线划清楚。你的细心在对方感情低谷时很容易被读成暧昧，该保持的距离要保持。已婚的更要走在明面上，约见面拉上别人、跟太太提前说一声，比事后解释省事。有人拉你当中间人，听可以，别下场表态——替别人做决定，最后两头不落好。",
  "fuDe|破军|male": "你的脑子几乎不停。永远在想推翻重来，心思很难真正清闲下来，操心费力是常态。这份不安既是你最大的天赋，也是你最大的功课。最容易掉进去的坑是“拆完就空”——把旧的推倒之后，不知道接下来要建什么，于是干脆再去拆下一个，一圈圈空转，人越来越累。\n\n建议你给自己定一条规矩。想拆什么之前，先把要建成什么样写下来，写不出来就先别动。中年以后挑一个领域深耕，哪怕摊子小，做深做透，心才有地方落。每天留半小时什么都不干，不看手机也不想计划，让脑子空一会儿。",
  "fuQi|七杀|female": "你性格刚强、独立。你对感情的要求很高，受不了平庸的关系，也受不了不对等的关系，宁可一个人也不愿将就。所以磨合期会长些。太早结婚磨合会多一些；等自己定下来再谈婚嫁，更容易碰上真正匹配的人。你需要的丈夫，是在某个领域能让你服气、同时给得起你空间的人，你服气了才肯让步。\n\n建议你不急着把自己嫁出去，越急越容易受伤。找对象看三样：够成熟、扛得住事、不怕你比他强。恋爱阶段就把你要的空间和界线讲明白，比如工作强度、各自的朋友、钱怎么算，先说清楚好过婚后慢慢磨。吵架的时候对着事说，别翻旧账、别评价对方的为人。",
  "qianYi|贪狼|female": "你出门在外比守在家里有机会。钱和路子常常是从饭局、应酬、人情往来里挣出来的，只是人也确实累。去外地、去海外发展对你是加分的，但一个人在陌生城市，孤单的感觉也比别人重。外地的社交场、夜场最容易遇到让你心动的人，异地恋对你来说尤其难熬。\n\n建议你出差和一个人旅行时立几条硬规矩。夜场不去、酒少喝、陌生男性的单独邀约推掉，网上认识的人不单独见面。证件和贵重物品自己收着，行程发一份给家里人，住处挑安全的地段。已经结婚的话，尽量不要跟丈夫长期两地分开；真躲不开，把回家的频率提前说定。",
  "jiaoYou|太阴|female": "闺蜜是你朋友圈的核心。女性朋友的数量和深度都远超男性朋友，这是你最舒服的地方。身边的女性朋友常把你当倾诉对象：失恋找你哭、离婚找你抱、孩子叛逆找你出主意，接得太多，最后自己先垮。\n\n你得学会关上一点阀门，不是每一份痛苦你都要接住。听人诉苦给个时限，半小时到了就换话题，或者直说今天我状态不行、改天再聊——真朋友不会为这个跟你翻脸。别人的感情纠纷别选边站。你性子软又温柔，异性容易误会，已婚的跟男性朋友来往走在明面上，多约几个人一起，少单独见。",
  "fuDe|破军|female": "你的脑子几乎不停。永远在想推翻重来，心思很难真正清闲下来，操心费力是常态。这份不安既是你最大的天赋，也是你最大的功课。最容易掉进去的坑是“拆完就空”：把旧的推倒之后，不知道接下来要建什么，于是干脆再去拆下一个，一圈圈空转，人越来越累。\n\n建议你给自己定一条规矩。想拆什么之前，先把要建成什么样写下来，写不出来就先别动。年轻时你拆掉了很多旧的，中年该试着搭一次——不是把过去搭回来，是搭一个只属于你的新东西。每天留半小时什么都不干，让脑子空一会儿。",
  "jiE|巨门|male": "你的身体跟心思绑得很紧。想得越多，身上越不舒服。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗巨门的五行去配。跟人起了口舌纠纷，或者心里压着一股火的时候，身体最先报警。\n\n建议你少跟人较劲，也别把气憋在肚子里。跟人拌了嘴，当天就找人说出来或者写下来，气顺了身体才跟着松。吃饭定点定量、细嚼慢咽，少吃生冷辛辣，别暴饮暴食。每年做一次全面体检，四十岁以后查得勤一点；身体哪里不对劲及时看医生、遵医嘱。",
  "jiE|巨门|female": "你的身体跟心思绑得很紧。想得越多，身上越不舒服。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗巨门的五行去配。跟人起了口舌纠纷，或者心里压着一股火的时候，身体最先报警。\n\n建议你吃饭定点定量、细嚼慢咽。少生冷少辛辣，饭后散散步。情绪长期压着，身体的节律也会跟着乱，心里有事尽早找人说，别自己扛。打算怀孕就提前做一轮孕前检查，孕期按医生安排来。每年做一次全面体检；身体不对劲及时看医生、遵医嘱。",
  "caiBo|巨门|male": "你的钱跟口才和专业本事直接挂钩。不靠家里给，得自己白手起家，而且钱要在人多热闹的地方赚。稳定的收入来自专业服务和把知识卖出去，本事涨收入就涨；额外的机会靠人脉和消息抢先一步。心气太高、口气太大的时候，反而容易一下子把攒下的赔进去。\n\n建议你把最大的力气放在两件事上。攒口碑、躲纠纷，这两样做好了，财运自然稳。投资挑你能研究明白的方向，版权、知识产权、教育这类靠信息吃饭的领域最合适，别跟风追热闹。给自己定几条判断标准，够格就下手，别研究到机会跑了。和解费、律师费这类钱最冤，重要的事先把字写清楚。",
  "caiBo|巨门|female": "你的钱跟口才和专业本事直接挂钩。不靠家里给，得自己白手起家，钱要在人多热闹的地方赚。你管钱偏研究型，买理财、看项目之前会反复比对，话术很难把你带走。最容易漏财的地方一是纠纷的和解费、律师费，二是研究太久，好机会等你想明白就过去了。\n\n建议你给自己定一张快速判断表。挑五项关键指标，都符合就动手，不再纠结。投资挑你能研究明白的方向，版权、知识产权、教育这类靠信息吃饭的领域最合适，别跟风追热闹。家里谈钱注意方式，你的分析在另一半听来常常像质疑，先说「一起看看」，再摆你的道理。最要紧的还是攒口碑、躲纠纷，这两样做好钱就稳。",
  "guanLu|太阳|male": "你吃的是名声这碗饭。被更多人知道，机会才来，收入也跟着往上走。适合你的是要站到台前的行当：政治、公共管理、媒体、公关、教育演讲、品牌营销；军人、警察、法官、外交官这几条路也对，文的武的都走得通，就怕被埋在幕后没人看见。你天生会带队、会表达，能把方向讲得让人愿意跟，短板是细节和后台执行。帮你的人常是有分量的长辈，而且多在关键时刻才出手。\n\n建议你别怕抛头露面，能上台就上台，能署名就署名。身边配一个盯细节的搭档，把执行交出去，你只管方向和对外。人缘好是优势，但该表态时要表态，一味当好人反而没人真拿你当回事。最要紧的是言行一致——名声塌一次要好几年才补得回来，所以宁可少接几件事，也别答应了做不到。",
  "jiE|紫微|male": "你的底子偏结实。整体健康状况不错。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗紫微的五行去配。你的身体跟情绪绑得特别紧：自尊心强的人一受挫、被否定，压力全闷在心里，最先扛不住的是睡眠和头部的不舒服。\n\n吃饭按点吃、七分饱。少油腻、少喝酒，别一顿撑一顿饿。运动选散步、太极、强度中等的有氧就够，别去拼太激烈的竞技项目。每年做一次全面体检，40 岁以后查得勤一点；身上有任何不对劲，早点看医生、按医生说的做，别自己扛着上网瞎查。还有最重要的一条：找个能说话的人，把闷着的事讲出来，情绪顺了，睡眠和精神才跟着顺。",
  "xiongDi|廉贞|male": "你的兄弟姐妹人数不多，但个个有故事。他们经历不寻常，或者感情、职业上走的路跟旁人不一样。你们的关系比一般人家复杂：好的时候能聊到半夜，淡的时候几年不打一个电话，感情和利益还常常搅在一起。最容易出事的地方就在这里，今天靠交情把事办了，明天就说不清谁欠谁。化禄（进财）的时候，兄弟姐妹在文化、艺术这类行当上能互相帮上忙。\n\n建议你跟家里人合伙一律走合同。钱怎么分、活怎么派，白纸黑字写下来，别拿交情当合约用。借钱也一样，说清楚是借还是给。要是哪个兄弟姐妹正陷在感情或者官司的麻烦里，帮忙可以，但别把自己的生意和钱跟他绑在一起。",
  "qianYi|天机|male": "你是出门比守家更吃得开的人。离开熟悉的地方，反而容易碰上愿意拉你一把的人；一直待在原地，琐碎的是非反倒多。在一个地方待久了你会被磨钝，你这种脑子要常有新东西进来，才保持得住那份敏锐。销售、咨询、外派、跨地区的项目这类要跑动的活，特别适合你。\n\n建议你在职业里主动争取跨城、跨区的机会。每换一次环境都是一次长见识，别等公司安排，自己开口要项目、要外派。每年至少去一个没去过的城市住上几天，见两三个不同行业的人，把听来的东西记下来。出远门前把行程、住处、备用方案都定好，别到了再说，你经不起临时乱。",
  "tianZhai|武曲|male": "房子是你最实在的资产，钱放在砖头里你才安心。祖上留下的家底，在你手里各有去向。你对家的要求也很实在，简洁、好打理、东西顺手就行，花里胡哨的装饰在你这儿没什么位置。\n\n建议你先把一套核心地段的好房子立起来当底盘。再慢慢加配置，自住一套加投资一套是比较顺的结构。大额买卖之前，合约条款逐字看一遍，别嫌麻烦；邻里、物业、装修这几处纠纷，事前讲清楚比事后争省力得多。家里的厨房油烟和老化电器每年检查一次。",
  "fuDe|天同|male": "你天生知足，快乐来得容易。吃顿好的、睡个饱觉、跟朋友玩一天，精神就回来了，不需要靠大起大落来证明自己活得好。这是很稳的一种幸福。真正的坎在中年：只靠享受撑着的日子，过久了会冒出一个问题——我到底做成过什么。\n\n建议你三十五岁以后立一个跟享受无关的目标。做一件公益的事、把一门爱好练到能拿出手、或者认真做一件属于自己的事业。目标要具体到能写下来、每个月看得见进度。心里发慌的时候别一个人扛，把担心说给信得过的人听，或者动手去做点具体的事，你这种情绪靠行动散得最快。",
  "guanLu|太阳|female": "名声是你最值钱的职业资产。被更多人知道，机会才会找上门，收入也跟着涨。适合你的是要站到人前的行当：政治、公共管理、媒体、公关、教育演讲、品牌营销；军人、警察、法官、外交官这几条路也走得通，文的武的都行，唯独怕被压在幕后没人看见。你会带队、会讲，能把一件事说得让人愿意跟着干，短板是细节和后台执行。帮你的常是有分量的长辈，而且多在关键时刻才出手。\n\n建议你主动争取露脸的机会。能上台就上台，能署名就署名，别把功劳埋在团队里。身边找一个盯细节的搭档，执行交给他，你管方向和对外。人缘好是你的优势，但该表态时别和稀泥，偶尔亮一点态度，别人才当真。名声一旦塌了要好几年才补得回来，所以宁可少接事，也别做不到还硬应下来。",
  "jiE|紫微|female": "你的底子偏结实。整体还不错。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗紫微的五行去配。你的身体跟情绪绑得很紧：自尊心强，一受挫就把压力全闷着，最先扛不住的是睡眠。女生还多一层——情绪和身体的节律互相影响，经期前后情绪起伏大、周期不太规律比较常见，值得你自己记一记。\n\n吃饭按点、七分饱。少油少酒；运动选散步、太极、强度中等的有氧就够。每年做一次全面体检，40 岁以后查得勤一点；女性的常规检查也每年做一次，具体查哪几项听医生安排。怀孕生产期间千万别凭自己的主意硬来，医生怎么说就怎么做；身上有任何不对劲，早点看医生。",
  "xiongDi|廉贞|female": "你的兄弟姐妹人数不多，但各有各的故事。他们经历不寻常，或者感情、职业上走的路跟旁人不一样。你跟他们的感情很深，也很容易缠在一起：好的时候能聊到半夜，淡的时候几年不通电话。最容易出事的是把感情账和利益账混着算，因为聊得来就忽略了生意上的界线，最后感情一断，生意也跟着断。化禄（进财）的时候，兄弟姐妹在文化、艺术这些行当上能互相帮上忙。\n\n建议你记住一句话。聊得来的人，不一定适合做合伙人。真要一起做事，钱怎么分、活怎么派、退出怎么算，先写下来。借钱说清楚是借还是给。要是哪个兄弟姐妹正陷在感情或者官司里，帮忙可以，但别把自己的钱和事业跟他绑在一起。",
  "qianYi|天机|female": "你是出门比守家更吃得开的人。换个地方读书、工作，反而容易碰上愿意拉你一把的人；一直守在原地，琐碎的是非反倒多。长期困在一个小圈子里，你会开始胡思乱想，人就闷住了。异地求学、出国、跨城工作，往往决定你后半生能走多宽。\n\n建议你成家前先在外地独立生活一两年。这段日子尽量给自己争取来，后面会一直用得上。成家以后跑动少了，可以往远程办公或两地跑的模式上靠，你不需要扎根一个地方才舒展得开。出远门前把行程、住处、回程方案定好，跟家里人报备一声。路上心里堵了就给朋友打个电话说出来，别一个人闷着往深里想。",
  "tianZhai|武曲|female": "房子对你格外重要，那是你最硬的底气。祖上留下的家底，到你手里各有去向。不管结没结婚，你都倾向于在自己名下留一套房，这不是不信任另一半，是你这个性子本来就要钱和产在手里才安心。装修上你喜欢简洁实用，最烦花里胡哨。\n\n建议你早一点把自己名下那套房落定。日子顺的时候它是助力，遇上难处它是底牌。大额买卖前，合约条款逐字看一遍，别嫌麻烦；邻里、物业、装修这几处的麻烦，事前讲清楚比事后争省力。",
  "fuDe|天同|female": "你的快乐来得很实在。吃顿合口的、睡个饱觉、被人温柔对待，心里就满了，不需要靠什么大道理撑着。这种从日常里长出来的幸福最稳，也最不容易丢。中年以后这种怕被忽略的感觉会更明显。\n\n建议你培养一件只属于自己的事。瑜伽、看书、烘焙、种花都行，条件是不需要别人陪、做起来你就高兴。它的用处是让你一个人待着时心里也是满的，而不是等着谁来填。心里发慌的时候，把话直接说给对方听，问出来往往就没事了，别一个人在心里演。每周留一段谁都不打扰的时间，雷打不动。",
  "mingGong|廉贞|male": "你是个很有魅力又不太好看透的人。你会的东西多，往人群里一站有存在感，心里那股想要的劲一直没停过。你骨子里不服气，敢把旧的一套推倒重来，放在需要魄力的位置上最容易出头，到了陌生地方也能很快让人记住你。麻烦的是脾气硬、爱争，情绪起伏大，压力一来或者感情出事，反应容易走极端，不是爆发就是把自己整个关起来。吸引来的人多了，感情上的纠纷和背后的闲话也跟着多。\n\n建议你给情绪留个缓冲。气头上先别做决定，也别急着回话，隔一晚再谈，这一条能替你挡掉大半麻烦。把这股劲用在正事上，去做需要魄力和创意的工作，比跟人较劲划算得多。跟人来往，男女之间的是非主动少掺和；跟谁走得近、能走多近，自己心里先画条线。",
  "personality|廉贞|male": "你的心里永远比脸上复杂。你不是好脾气的人，那团火一直烧着，只是有时候压着不发。你爱憎分明：喜欢一个人喜欢得很深，不喜欢的能记很久。你聪明，但这份聪明常用错地方，为了一句话反复琢磨对方什么意思，一个细节能在心里过好几个月。你适合走从政、司法、军警、艺术，或任何需要敏锐判断的复杂行业，带点锋芒的路你走着反而顺。要当心的是另一面：赌钱、男女关系、打官司这三件事，一旦沾上就不容易抽身。\n\n建议你给那些反复琢磨的事设个期限。过了就落地：要么把话直接问清楚，要么彻底放下，别在心里养着。这辈子最要紧的功课是分清哪些事值得计较、哪些不值得：动气之前先问自己，这件事一年后还重要吗。灰色地带的关系、能不打的官司、来路不明的钱，能躲就躲。",
  "guanLu|武曲|male": "你的事业靠真本事说话。你不靠关系也不靠形象，在需要硬实力的位置上最吃得开。金融财务、工业制造、军警执法、外科医疗、工程建设、资产管理，或者要管人拍板的岗位，都很适合你。手里有实权、能自己拍板时，你发挥得最好。你做事不拖延、不废话，团队里有你在事情推得快，但管人偏硬，下属压力不小。你的钱来自实干，做多少拿多少。\n\n建议你在职位上把执行和管钱的本事做实。要不要自己创业，看财帛宫有没有禄、权，不凭官禄武曲一颗星定。最该防的是独断，重要决定前固定找一两个人讲反对意见，听完再拍板。对同事和下属多说一句认可，队伍才带得住。帮得上你的人多在资金和资源这头，投资人和做实业的前辈值得多走动。要不要自己做生意，看的是财帛宫有没有禄。",
  "caiBo|紫微|male": "你的钱主要跟着位置走。工资、职位、头衔带来的收入稳定，数目不小；靠投机、赌一把快速暴富不是你的路数。手里并不紧，但开支也大，攒钱偏慢，因为你重面子，买东西偏爱好的、贵的，维持形象常年花销不少。另一个漏钱的地方，是你太相信自己的判断，拍脑袋做的决定一旦错了，损失往往不小。你的财运来得偏晚，中年以后位置上去，钱明显宽裕，越往后越稳。\n\n建议你把重心放在把自己做成一块招牌上。做顾问、做行业里别人第一个想到的那个人，名气越响收入越高。财务细节找个专业的人帮你把关，大额支出设一道二次确认，别一个人拍板。投资走稳的路线，长期拿住好资产，别碰高风险的快钱。家里的钱跟妻子一起规划，比你一个人算账有效得多。",
  "jiE|天机|male": "你属于神经敏感的体质。脑子转得太久，身体先扛不住。最容易出状况的是睡眠：心里一堆事放不下的时候，往往先是睡不踏实，人容易累、容易头疼。担心和反复琢磨停不下来，是你最该留意的地方，情绪一紧，身体跟着紧。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天机的五行去配。\n\n建议你把作息固定下来。每天尽量同一个点睡、同一个点起，这一条比什么补品都管用。吃得清淡些，辣的和咖啡因少碰，下午之后别再喝咖啡。运动挑有节奏的——快走、慢跑、游泳、骑车，一周三次、每次半小时，让身体带着脑子降温。每年做一次常规体检，查哪几项听医生安排；身上有不舒服别自己上网查症状吓自己，去看医生，按医生说的做。",
  "ziNv|天梁|male": "你的孩子多半早熟。在家像个小大人，会看你的脸色，主动替家里分担。老说法里孩子大致是两个。传统将天梁算阳星，子女宫见天梁会有男孩。你当爸爸最大的隐忧不是孩子不懂事，恰恰是太懂事——懂事太早，等于把童年提前交出去了。\n\n建议你有意识地让孩子做回小孩。家里的难处别一股脑讲给他听，你的情绪自己消化，别让他当你的听众。他做得不好的时候，允许他不好，别急着讲道理。带他去做点没用的事，打球、乱跑、发呆都行。身体上按时带他体检，有不舒服听医生的。你对他说谢谢的次数，比讲一百遍道理管用。",
  "jiaoYou|太阳|male": "你的圈子又广又显眼。你认识的人里有不少有身份、有名望的，关键时候能给你带来实打实的资源。太阳在这一宫的亮度，决定朋友和下属肯不肯替你出力。男性朋友是你人脉的主干，但讲义气讲过了头，也最容易替人背锅。\n\n建议你对每一个要公开合作的朋友，先打听打听。看他过往的口碑——这不是势利，你一旦被别人的是非牵连，损失最大。跟位置高、路子正的朋友保持长线往来，别总是有事才找。风评不好的早点淡出，别等出事再撇清。化忌（阻碍）时，朋友那边的是非最容易砸到你的名声，该断的别拖。有人张口借钱或者要你签字担保，先想想这事能不能摆上台面，不能就直接回绝。",
  "tianZhai|天同|male": "你的房子基本靠自己买。家里留下的有限，年轻时不容易，中年以后越置越顺，所以二十几岁跟人比房子没什么意义。你买房看的是住着舒不舒服，不是能涨多少，这本来也没错。\n\n建议你用制度替自己管钱。公积金交满、房贷按月扣、每月固定转一笔进买房的账户，比靠自己忍着管用。房贷别顶着上限借，留出让自己过得舒服的那部分钱，不然中途容易撑不住。装修别学那种冷硬的灰白风格，地毯、靠垫、暖光、香薰这些不起眼的小东西对你很要紧，该花的钱别省。",
  "mingGong|廉贞|female": "你这个人做事有分寸、有自己的标准。你气质干净，不轻易跟人套近乎，别人对你多是敬重而不是随便。你才艺好、路子宽，艺术、法律、财务这几条路都走得通。感情上你态度认真，不轻易动心，一旦认定就很坚定，魅力是别人被你吸引过来，不是你主动去招惹。\n\n建议你别把标准端得太高。在守住自己原则的同时，对真正在乎你的人多露一点柔软。事业上可以放心多试几个方向，不必早早锁死一条路。感情上不用急，你这样的人晚一点遇到对的人反而更稳；真遇上了，把界线和分寸讲清楚，比什么都管用。",
  "personality|廉贞|female": "你身上有种让人想多看一眼的气质。不是甜的那种，是有分寸又不太好看透的那种。你对自己有标准，不跟着别人起哄。你感性、敏感，对美的东西格外有判断力，可这份感性也是负担：情绪起伏大，今天能为一首歌哭，明天因为一句话就冷下来。爱起来你毫无保留，可一旦感情断了，那种痛要很久才消化得掉。关注你的人不少，人际关系也因此常常变复杂。\n\n建议你把心里反复重演的那些细节找个地方放出去。写下来、画出来，或者一个人出去走一趟，别堵在胸口变成内耗。跟人相处先把距离和分寸摆明，能少很多麻烦。走艺术、设计、法律、心理咨询这类既讲专业又容得下复杂情绪的路子，你的敏感是本事不是毛病。情绪上来的时候先别做决定，隔一天再说。",
  "guanLu|武曲|female": "你的事业靠真本事说话。你不靠关系也不靠形象，在需要硬实力的位置上最吃得开。金融财务、工业制造、军警执法、外科医疗、工程建设、资产管理，或者要管人拍板的岗位都很适合你，手里有实权时你发挥得最好。你做事不拖延、不废话，事情推得快，但管人偏硬，下属压力不小。你这类女性事业往往比感情顺，事业成就是你最硬的底气。\n\n建议你把重心放在事业上。专业能力就是你的话语权。最该防的是独断，重要决定前固定听一两个反对意见再拍板。对同事和下属多说一句认可，队伍才带得住。帮得上你的人多在资金和资源这头，投资人和做实业的前辈值得多走动。要不要自己做生意，看的是财帛宫有没有禄。",
  "caiBo|紫微|female": "你的钱主要跟着位置走。工资、职位带来的收入稳定，靠投机、赌一把暴富不是你的路。手头不算紧但攒得慢，因为你花钱有自己的讲究——牌子、品位、出门要体面，包、首饰、形象维护这几项常年不便宜。家里的账你很少甘心当被动记账的那个，多半是你在管钱，而且习惯在共同账户之外，自己留一份谁也动不了的。你的财运来得偏晚，中年以后位置上去了，钱才明显宽裕。\n\n建议你把赚钱的重心放在把自己做成一块招牌上。名气越响收入越高。花钱这块给自己定一条线：形象上的支出按月设个上限，超了就等下个月。最要紧的是婚前就把钱怎么算讲清楚：各自留独立账户、共同开销怎么分——你这样的人一旦经济上被人管着，日子就过得不痛快。",
  "jiE|天机|female": "你属于神经敏感的体质。脑子转得太久，身体先扛不住。最容易出状况的是睡眠：心里放不下事的时候，先是睡不踏实，人容易累、容易头疼。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天机的五行去配。情绪和身体是连着的——压力大、心里憋着火的那阵子，月经容易不太规律，来之前脾气也变大。怀孕那段日子和更年期那几年，情绪起伏会更明显，心里先有准备就不慌。\n\n建议你先把作息固定下来。每天尽量同一个点睡、同一个点起。吃得清淡些，多吃蔬菜，辣的少碰，下午之后别喝咖啡。运动挑有节奏的：快走、慢跑、游泳、骑车，一周三次、每次半小时，最能把火气排掉。每年做一次常规体检，把睡眠、情绪、月经的变化记在手机里，看诊时给医生看；心慌、出汗多、体重忽上忽下，就按医生的建议去做检查，别自己上网查了吓自己。",
  "ziNv|天梁|female": "你和孩子之间的牵绊特别深。你能看穿他心里在想什么，他也感觉得到你的温度。这样的孩子多半早熟，懂事得让人心疼，在家像个小大人。老说法里孩子大致是两个。传统将天梁算阳星，子女宫见天梁会有男孩。最大的隐忧是他替你扛情绪——你心里不稳的时候，孩子会本能地提前长大来照顾你。\n\n建议你先把自己的情绪安顿好。这是对孩子最实在的保护：难受时找同龄人说，别把他当你的听众。他做得不好，允许他不好，先别急着讲道理。带他去做点没用的事，打球、乱跑、发呆都行，童年就是用来浪费的。身体上按时带他体检，有不舒服听医生的。孩子不需要一个完美的妈妈，需要一个真实的、也会累的妈妈。",
  "jiaoYou|太阳|female": "你的圈子又广又显眼。你认识的人里有不少有身份、有名望的男性，聊得来也谈得深。这是你的优势，也是最容易被人说闲话的地方——外人看不见你们谈的是正事，只看见你们走得近。太阳在这一宫的亮度，决定朋友和下属肯不肯替你出力。\n\n跟男性朋友相处，建议你把界线摆到明面上。聚会有第三个人在场，晚上不单独约，来往的事不藏着。跟女性朋友相处，有意识地放低姿态，多替对方捧场、少纠正对方；挑两三个同样有事业心的深交，比认识一百个泛泛之交管用。化忌（阻碍）时，朋友带来的是非会直接伤到你的名声，该断的关系早点断，别拖到出事。",
  "tianZhai|天同|female": "房子这件事你基本靠自己。家里留给你的有限，年轻时紧一点，中年以后才慢慢宽裕起来。你在过日子上天赋很高：挑东西的眼光、把日常过出仪式感的本事、让人一进门就想赖着不走的氛围，都是你的长处。婚后你很适合当家里的中心，张罗节日、招待亲友这些事会让你特别有成就感。\n\n建议买房优先看三样。采光、离不离公园近、邻居好不好相处，这几样对你的幸福感比升值空间实在得多。存钱靠制度别靠忍：每月固定转一笔进专门的账户，剩下的随便花。装修别用冷色调和冷白光，暖光、暖色、软一点的布艺才是你的地方，这部分钱别省。",
  "mingGong|天府|male": "你是天生的守护者。你稳重踏实，凡事先看稳不稳，是身边人眼里的压舱石。天府管钱财、房产和一辈子的衣食，像一座存钱的仓库，所以你多半不缺钱，手里已有的资源和人脉也守得住。别人觉得你可靠、说话算数，愿意把要紧的事交给你。你看着温和厚道，其实心里有一本账：温和是表层，算得清楚才是里子。你的短板是太保守，要冒点险才抓得住的机会，常常等到过期。\n\n建议你每年强迫自己试一两件没把握的事。从赔得起的小额开始，输了不伤本，赢了就补上你最缺的那点闯劲。你不爱主动结交新人，就借着工作把关系走出去，一年多认识几个人就够。压力大的时候别只顾着加固防线，先问一句：最坏能坏到哪，答得出来就敢动了。",
  "personality|天府|male": "你是那种看着普通、其实很稳的人。你不爱出风头，凡事却算得清楚；不擅长撑场面，关键时刻却顶得住。你心里有个本能，攒下来比铺开摊子重要，保住比赢更重要。年轻时你显得慢半拍，同龄人在闯，你在攒；中年以后这份稳就显出好处，钱稳、家稳、关系也稳。你性子是温和，但温和只是性子温和，不等于没算计——心眼其实不少，该算的账一笔没落下。\n\n你最在意的是体面，不求最大，但不能失分寸。感情上你不是激情型，更像一个靠得住的合伙人，不浪漫，但不会突然消失。你最大的短板是缺爆发力，容易错过那种非出手不可的窗口。建议你这辈子至少安排一次豁出去的决定：换城市、换行业、把一笔攒久的钱投在自己身上都算。算清最坏结果，能接受就动手，你的稳才会变成强。",
  "guanLu|天相|male": "你的本事在幕后。在大平台里做那个核心支撑的人，比站在最前面领队更适合你。行政、法务、会计财务、人力资源、秘书文书、大企业运营这类按规矩办事、管流程的岗位最顺手，制度越健全的地方你效率越高。你把事做得让人放心，但不太会主动争资源和升迁，功劳容易被别人拿走，太老实还容易被当成理所当然。收入稳，但涨得慢。\n\n建议你每年至少向上司明确提一次升职或加薪。把这一年做成的事列成具体数字给他看。选工作优先看平台，平台的高低对你比个人埋头苦干更关键。真要创业，找一个有野心、有资源的人主导大方向，你管内部和落地，分工写清楚。多留意直属上司和行业里说话有分量的前辈，你的贵人是长期带你的那种人。",
  "jiaoYou|天梁|male": "你的朋友圈里长辈多、有资历的人多。年轻热闹的场子你反而待不久。这不是坏事，你身边的帮手多半靠得住，你不在的时候摊子有人替你看着。古书说天梁在这一宫「奴多旺主」，意思是身边的人多，又能旺你。\n\n建议你分清给建议和担后果。别人问你，把利弊讲明白就够了，别替他做决定，更别替他去办，他自己选的路才扛得住。交朋友宁可少而深，有些人看着走得近，其实并不一条心，深交要慎重。还有，你也可以开口求人——你帮过那么多人，让他们回报一次，关系才是平的。",
  "tianZhai|巨门|male": "房子这件事，你得靠自己。祖上的家产，到你这里守不住。家里的气氛同样要紧：一家人能坐下来把事讲清楚的时候最舒服，天天为小事拌嘴的时候最耗你的精神。\n\n房产的事，产权先理清。买房、过户这类大事先找专业人士把合同一条条看过，产权写清楚，别嫌麻烦。家里吵起来先各自待五分钟再谈。",
  "mingGong|天府|female": "你是天生的持家人。你稳重踏实，对安全感的要求很高，是最能让一个家安定下来的那类女性。天府管的是钱财、房产和衣食，你很会管钱、管资源。你做人正派，脑子也灵，对丈夫和孩子都有实打实的帮助。你不是只会顺从的人，想得比外表看上去快，只是不爱争。感情上你忠诚，看重婚姻实在的那一面，更看重对方靠不靠得住。\n\n你的弱点是太保守。新东西摆在面前，往往等到别人都上手了才动。建议给自己留一条试错的口子：每年学一样新技能、认识几个圈子外的人。挑伴侣你看重实力和人品是对的，但别把条件列成清单，多留意相处时舒不舒服。还有一点：你太想把家里人护在安全范围里，容易把他们的空间压没了；家人做的决定你不认同，先听完再说。",
  "personality|天府|female": "你做人正派、脑子也灵，只是不爱显山露水。你不是温吞，是不争：不爱抛头露面，可事情到你手上都安排得井井有条；不爱跟人争辩，心里其实明明白白。你的稳让伴侣有安全感，家里也跟着转得顺。可这份稳容易被低估，别人只看到你温顺，看不到你心里那份聪明。你最适合做家里的定海神针，但这不等于你只能持家，放到今天，你完全可以有自己的事业，只是节奏比别人慢一点、稳一点。\n\n你这辈子最容易吃亏的，是不敢为自己开口。替家人争利益你毫不犹豫，轮到自己总要退一步。建议从小事开始练：分家里的东西，说出你想要哪一份；工作上该拿的报酬，直接开口谈；不想去的场合，就说不去，不用编理由。你为自己说不的那些时刻，恰恰是身边人开始真正尊重你的起点。",
  "guanLu|天相|female": "你的本事在幕后。在大平台里做核心支撑的那个人，比站到最前面领队更适合你。行政、法务、财务、人力资源、文书、大企业运营这类按规矩办事、管流程的岗位最顺手。你是单位里最被信任的那个女员工，重要的、要保密的、要做细的活，上司都放心交给你。可这也是陷阱：你容易被当成好用的助手，而不是接班人，功劳被人拿走，收入稳但涨得慢。\n\n想打破这层天花板，建议做三件事。每年至少向上司明确提一次升职或加薪；公司讨论方向的场合主动进去说话，别只做落地执行；在单位之外攒一个属于自己的专业身份，比如进行业协会、去讲课、写行业文章。休完产假回来，很多人会默认你该多担家务、少担工作，这件事在生产之前就跟家人和上司把分工谈清楚。",
  "jiaoYou|天梁|female": "你的朋友圈里长辈多、有资历的人多。年轻热闹的场子你反而待不久。古书说天梁在这一宫「奴多旺主」，意思是身边的人多，又能旺你。\n\n建议你练一个新习惯：听完，不替对方解决。很多时候人要的只是有人认真听，不是答案。真想帮，就问一句你打算怎么办，把主意还给她。交朋友宁可少而深。还有，你也可以开口求人——你帮过那么多人，让她们回报一次，关系才是平的。",
  "tianZhai|巨门|female": "房子这件事，你得靠自己。祖上的家产，到你这里守不住。家里的气氛同样要紧：能坐下来把事讲清楚的时候最舒服，天天为小事吵的时候最伤人，婆媳、母女之间的话头最耗你的精神。\n\n建议你给自己留一处能独处的角落。哪怕只是一张桌子。这不是不信任另一半，是你这样的人需要一个安静想事情的地方。买房、过户这类大事先找专业人士把合同一条条看过，产权写清楚。家里吵起来先各自待五分钟再谈。",
  "guanLu|巨门|male": "你的事业靠一张嘴吃饭。口才和专业表达是你最值钱的本钱，在要说服人、传递信息、替人争取权益的岗位上最出彩。律师、老师讲师、记者、销售顾问、心理咨询、主持、编辑写作，这些用语言干活的行当最适合你。你在团队里是敢提尖锐问题的那一个，太敢说有时会惹同事不快。最大的风险是因为一句话惹出纠纷甚至吃官司。\n\n建议你专门练一件事。话还是那些话，换个时机、换个说法再讲出来。提意见挑私下的场合，公开场合只讲事、不评人。想自己干就走知识服务这条路，培训、咨询、自媒体、法律服务，靠口碑攒客户。多接触欣赏你的行业前辈，他们一句引荐比你投十份简历管用。收入的天花板靠个人品牌往上抬。",
  "jiaoYou|天相|male": "你的朋友不在多，在合得来。你不爱混乱的场子，也不喜欢吵闹低俗的应酬，跟你最舒服的是那种做事有分寸、说话客气、办事有条理的人。真正得力的帮手和下属，多半要到晚年才聚到你身边，早些年人手不齐是常态，不用因此怀疑自己。身边常有人开口求你签字、做担保、找关系。\n\n建议你把“我先想想”练成口头禅。别人一开口求帮忙，别当场答应，隔一晚再回话。牵涉到钱和签字的事，一律说“这个我不方便”，不用解释太多。想扩圈子，就从专业的路子入手，行业协会、同行聚会、课程班，这些地方碰到的人跟你是一路的，比酒桌上认识的靠谱。",
  "fuMu|天府|male": "你父母稳重务实。家底相对厚实，父亲多半是体制内、银行或传统行业里的稳定型人物，家教讲的是勤俭持家、稳中求进。父母缘分整体是完整的，你最大的福气就来自这里：有家底可以接，有做事的规矩可以学。\n\n建议你别指望说服父母理解你的生活方式。把力气放在他们能接得住的地方：定期回家吃饭、每年陪着做一次体检。争执起来先停半分钟，他们要的往往不是你听话，是确认你过得稳。职场上多亲近稳重型的上司，传统行业、银行、政府背景出来的人最容易赏识你。",
  "guanLu|巨门|female": "你的事业靠一张嘴吃饭。口才和专业表达是你最值钱的本钱，律师、培训师、主持人、翻译、记者、咨询这些行当你有明显优势。你在团队里敢提尖锐的问题，但太敢说有时会惹人不快，职场上对「太能说」的女性也确实还有偏见。最大的风险是因为一句话惹出纠纷。\n\n建议你把锐利转成说服力。内容照样锋利，语气、节奏、表情放柔，让人愿意听完。提意见挑私下的场合，公开场合只讲事、不评人。想自己干就走知识服务这条路，培训、咨询、自媒体、法律服务，靠口碑攒客户。生了孩子也不必跟工作断线，你沟通能力强，休假期间线上保持联系、产后回到会议节奏都比别人快，只是双重压力下要留意肠胃，别拿身体硬扛。",
  "jiaoYou|天相|female": "你的朋友不在多，在合得来。你不爱混乱的场子，也不喜欢吵闹的酒局，跟你最舒服的是那种说话有礼、生活有条理、手里有一份自己事业的女性。真正合拍、能帮上忙的人，多半要到晚年才聚到你身边，早些年圈子单薄是常态，不用勉强凑数。身边的朋友常来找你诉苦，时间久了，你容易成了她们的情绪出口，自己却空了。\n\n建议你练一种温和的拒绝。不用放弃体面，一句今天我状态不好、改天再听你说，就够了。听朋友倒苦水，给自己定个时间，一小时就打住。牵涉到借钱、担保、托关系的事，一律隔一晚再回话。想扩圈子，从自己的兴趣和专业入手，看展、读书会、行业聚会，这些地方遇到的人跟你是一路的。",
  "fuMu|天府|female": "你父母稳重务实，家底相对厚实。他们多半在体制内、银行或传统行业，家教讲的是勤俭持家、稳中求进。你和母亲的关系特别融洽，母女像姐妹一样亲，持家、带孩子这些事，她是你最大的老师。婚后你和公婆也处得不错，他们欣赏你稳重持家，只是你的付出容易被当成理所当然。\n\n建议你早点把边界立起来。帮忙可以，哪些事你不接，说在前面，别等憋出委屈才讲。对父母也一样，定期回家吃饭、陪他们做体检，比说服他们理解你的生活方式实在得多。你为这个家做的事，顺口说出来让他们知道，别默默做完就算了。",
  "fuMu|太阴|male": "你跟母亲的缘分特别深。她是你精神上最大的支点；你跟母亲怎么相处，也会不知不觉搬到你跟太太、跟女儿的相处里。父亲对你的影响相对小一些，但一直是稳定的支持。职场上你跟女上司配合往往格外顺。\n\n定期安排母亲体检，别等她说不舒服才动。有些事你要当桥，不当传话筒：母亲和太太都跟你讲对方不是的时候，各自接住，别把原话转述过去。也留意一点，你对母亲的依赖别原样搬到太太身上——她是伴侣，不是第二个妈。母亲年纪上来以后，多陪着说说话，比买东西管用。",
  "fuMu|太阴|female": "你跟母亲近到几乎分不开。她是你精神上最大的支点，也是你将来当妈的模板。母女处得好，你一辈子都有人兜底；母女处得紧张，你可能要用很多年跟她的影子和解。婚后跟公婆相处，你容易拿婆婆跟亲妈比，一比就失望。\n\n四十五岁以后，主动把母亲的全面体检安排上。别等她喊不舒服。对公婆把期待放低，礼数到位、客气周全就行，那份母女的深情留给亲妈，不必强求婆婆也这样待你。跟母亲之间的老账，挑个心平气和的时候摊开谈一次，说出来的比憋着的伤人少。母亲年纪上来以后多陪她说说话，比买东西管用。",
  "fuDe|太阴|male": "你的精神状态像月亮一样有圆有缺。好的时候整个人是饱满的，低的时候就往里收，谁也不想见。安静少打扰的时段是你最活跃的时候，一个人待着、看书、写东西、发呆，效率反而最高。\n\n把独处的时间正经排进日程。不是有空才留，是先留出来。情绪低的时候别憋，写下来、跟信得过的人讲一讲，让它流动出去。中年以后可以接触些安静的路子：打坐、慢瑜伽、一个人走长路，都对你有用。还有一句——这个时代夸的是阳光外向，但你的安静细腻不是毛病，是你的本事。",
  "fuDe|太阴|female": "你的精神状态像月亮一样有圆有缺。换季、家里人的事，都会明显牵动你。安静少打扰的时段是你最活跃的时候，一个人看书、写东西、发呆，效率反而最高。\n\n关键是让敏感流动起来，别让它积在心里。写日记、画画、长时间的深度阅读，都是你的出口；实在压得慌，找个能长期聊的咨询师——不是出了大问题才去，是给情绪挖一条固定的排水沟。中年以后接触打坐、瑜伽、艺术这类安静的事，对你格外有用。别想着把自己磨成没感觉的人，你要的不是变钝，是给敏感加一道屏障。",
  "ziNv|破军|male": "你的孩子独立性极强、爱推翻规矩、有一股创新劲。从小就是那种性子刚、不好摆布的小家伙，是最让父母管不住的一类。父子这条线多半早年有波折、后来才慢慢顺起来，小时候不见得贴心，日子久了反而处出感情。孩子放对地方——创业、艺术、技术、改革这条路——会有大出息；放进那种要求乖巧守规矩的家庭，就成了你的心头大患。\n\n建议你当爸爸的主动接受孩子的“拧”。别想把他框成温顺听话的样子，那会把他的天赋掐掉。规矩少立几条，立了就守住，剩下的放手让他自己撞。他顶嘴的时候先听完再说话，你越压他越反。",
  "jiaoYou|七杀|male": "你的朋友不多，但都是能交心、能托付的那种。你身边的朋友多是独立、干脆、不绕弯子的人，一年见一次也不影响感情。要当心的是钱：能干的下属、讲义气的朋友，都可能慢慢反过来做主，在账上让你吃暗亏。身边常有人让你担保、让你出头、让你去摆平，答应下来，最后卷进去的是你。\n\n建议你用人先立规矩。钱的权限和签字的权力握在自己手里，账目定期对，亲兄弟也明算账。凡是担保、借钱、出面替人解决麻烦这类事，一律先睡一晚再回话，第二天你多半会有不同的判断。真心待你的那几个，主动约、主动联系，你朋友本来就少，每一个都值得你花心思。",
  "fuMu|贪狼|male": "你家里比一般家庭热闹，也更复杂一些。父母多半是会来事、路子宽的人，可能做销售、艺术、娱乐这类跟人打交道的行当，他们自己的感情经历也常常不简单。你跟父母的缘分偏淡，早早离家、在外地上学工作，或者由别的长辈带大都不稀奇。\n\n建议你把跟父母的联系做成固定动作。每周一个电话、每月回去一趟，比住在一起天天拌嘴强，你们这种关系本来就是隔着点距离才处得好。观念上对不上就别争，听着、不照做就行。四十五岁以后主动帮父母安排每年体检，陪着去，报告照医生说的执行。工作上你跟活络的上司合得来，碰上刻板的领导，少辩解、多交结果。",
  "ziNv|破军|female": "你的孩子独立性极强、爱推翻规矩、有一股创新劲。从小就是那种性子刚、不好摆布的小家伙。亲子这条线多半早年有波折、后来才慢慢顺起来。最容易起冲突的是你和女儿之间：你越要她守规矩，她越想推翻；你越希望她稳，她越想冒险，其实你们是一个脾气。生孩子这条路你也常有曲折，晚一点怀、试几次才成，都很常见。\n\n建议你主动接受孩子的“不一样”。别拿邻居家的乖孩子当模板，那会把她的天赋掐掉。规矩少立几条，立了就守住，剩下的让她自己撞。起冲突时先听完再开口，你越压她越反。打算要孩子就提前把身体和作息调理好，别赶时间。孩子体质上有情况，定期检查、遵医嘱就好，不往某个器官上对号入座。",
  "jiaoYou|七杀|female": "你的朋友很少，但每一个都够深。你身边的朋友多是独立、干脆的女性，一年见一次也不影响感情，彼此说话不用客套。要当心的是钱：能干的下属、讲义气的朋友，都可能慢慢反过来做主，在账上让你吃暗亏。\n\n建议你用人先立规矩。钱的权限和签字的权力握在自己手里，账目定期对。凡是担保、借钱、出面替人解决麻烦这类事，一律先睡一晚再回话。合不来的圈子不用勉强自己融入，省下来的力气留给对的人。朋友少就更要主动约、主动问一句最近怎么样，关系是走出来的。",
  "fuMu|贪狼|female": "你家比一般家庭热闹，也更复杂。父母多半是会来事、路子宽的人，可能做销售、艺术、娱乐这类跟人打交道的行当，他们自己的感情经历也常常不简单。你跟父母的缘分偏淡，早早离家、在外地念书工作，或者由别的长辈带大都不稀奇。\n\n建议你把跟父母的联系做成固定动作。每周一个电话、每月回去一趟，比住在一起天天拌嘴强，这种缘分本来就靠点距离维持。观念上对不上就别争，听着、不照做就行。四十五岁以后主动帮他们安排每年体检，陪着去，报告照医生说的执行。跟公婆相处收着点社交那一面，不用装成另一个人，少在他们面前展示那份惹眼的魅力。",
  "fuQi|破军|male": "你在感情上自由随性。你不喜欢被拴住，早年容易变来变去，太早把关系定下来往往不稳。感情容易聚散不定、一进一退，晚一点成家反而稳当；分合几次不能只凭这一颗星断。等你自己的节奏稳下来，才真正搞明白要什么样的人。命里的妻子有个性、主意很正、不依赖人，可能做技术、旅游、外贸、艺术或者自己创业，也可能年纪比你稍大、性子更稳；她常常是你某次转型的推手。\n\n建议你别急着在年轻时把婚事定死。先把自己的节奏稳住。两个人都爱自由，就得有一个人负责把日子稳住：谁管钱、谁管家，事先说清楚。相处里少用“换个人试试”解决问题，有矛盾当天讲开。光靠激情撑不久，把长期一起过日子的打算摊到桌面上谈。",
  "qianYi|七杀|male": "出外是你的主场。你在外面的日子往往比在家多，离开家乡、换个城市甚至换个国家，反而更容易做成事——在一个没人认识你的地方，你能凭本事重新开一片天。但在外也容易奔波不定、惹上是非：开车、跟人起冲突、合同上的纠纷，这几样都要多留心。\n\n建议你出去就挑有挑战的活。创业、开拓市场、被派去外地做项目都行，别选那种只是换个地方坐办公室的差事，那会把你的劲耗光。在外喝了酒就别碰车，遇到争执先走开，事后再谈。到一个新地方，先花三个月认认真真结交几个本地朋友，路才走得稳。",
  "fuDe|贪狼|male": "你心里很难真正闲下来。重复的、稳的、一眼望到头的日子对你就是活受罪，一有新鲜东西冒出来你就静不住。热闹是你的常态，安静反而让你慌。年轻时累一点忙一点没关系，你这种人多半是先忙后享，越往后越能过得舒服。\n\n建议你别跟自己的欲望硬碰，管住它比灭掉它现实。把那股劲儿找个正经出口：写东西、做作品、折腾个小生意，都比拿去喝酒赌钱耗着强。中年以后试试需要忍一忍的事，轻断食、戒酒、长距离跑步、打坐都行，关键是让自己知道「我停得下来」。每个月留一两天不社交、不喝酒、不刷手机。",
  "fuQi|破军|female": "你喜欢自己做主，不愿被人管着。感情上起伏比一般人大，容易聚散不定，你对另一半的标准也会随着心境变化。你身上有股想改造对方的劲，希望丈夫跟着你一起变，这往往是冲突的起点。感情容易一进一退，所以太早成家不见得稳，晚一点定反而牢。\n\n建议你晚一点结婚，等自己心境沉稳了再决定。挑人挑那种既包容你、又有自己主见的：太软的扛不住你，太硬的跟你对着干。婚前把生活方式摊开对一遍——谁管钱、要不要孩子、能不能接受你说走就走，这些比感觉更重要。也别急着改造他，想改的地方先说出来，问他愿不愿意。这份禄在哪个十年、哪一年被引动，要再看运限。",
  "qianYi|七杀|female": "出外是你的主场。你在外面的日子往往比在家多，也比同龄人更敢远走。到一个没人认识你的地方，你的闯劲反而成了优势，能凭自己开一片天。要留意的是，女性在外打拼容易孤单，身边没有能说话的人时，撑得越久越累；另外在外开车、跟人起冲突，也都要多留一分心。\n\n建议你出去就认真经营在外的关系。几个能约出来吃饭的朋友、一个能半夜打电话的人，比多赚一点更重要。如果远嫁，把自己的事业、自己的圈子、自己的账户都保住，不用什么都随着婆家来；真被压着就明说，硬忍着先受伤的是自己。在外喝了酒就别碰车，遇到争执先走开。",
  "fuDe|贪狼|female": "你心里很难真正闲下来。重复的、稳的、一眼望到头的日子对你就是煎熬，一有新鲜东西冒出来就静不住。热闹是你的常态，安静反而让你发慌。年轻时忙一点累一点不要紧，你这种人多半是先忙后享，越往后越懂得过舒服日子。\n\n建议你别跟自己的欲望硬碰。把它引到有产出的地方比灭掉它现实：写字、画画、做手作、教人、折腾个小生意，比拿去消费耗着强。中年以后试试需要忍一忍的事，打坐、瑜伽、长距离走路都行，关键是让自己知道「我停得下来」。心里憋着的事及时找人说，作息稳住，每年做一次常规体检。",
  "fuQi|天相|male": "你在感情上忠诚踏实。你答应的事看得很重，认定一个人就不轻易放手。你不太会主动追人，缘分多半是亲戚朋友牵线，或者从熟悉的环境里来的，很少是路上碰见就开始。你的妻子多半模样好看、性子温厚懂事，做事有规矩、够成熟，可能在行政、法律、财务或者大机构上班，不张扬但心里有主见，会把家里和你身后的事安排妥当。你们都稳重，过日子有条不紊，很少爆发大矛盾。\n\n正因为太平稳，热度容易随时间往下掉。别把没吵架当成一切都好。建议你每周固定留一段两个人的时间，哪怕只是一起吃顿饭、走一段路；她为你做的事，当面说一句谢谢，别默认她都知道。想认识人就大方请熟人介绍，这条路对你最管用。",
  "ziNv|巨门|male": "你的孩子多半口才好、爱争辩、问题特别多。从小就爱问为什么，琢磨事情的劲头很足。孩子来得偏迟一些，过程也可能有波折，一开始不容易，往后会顺起来。这样的孩子放对地方，走律师、学者、研究这类路子会有出息；放在只要听话乖巧的家庭里，反倒成了你心口的一根刺。最容易出现的冲突是青春期顶嘴，你越拿当爹的身份压他，他的口才越会练成对付你的武器。\n\n建议你主动让孩子赢一两次辩论。不是认输，是让他明白讲道理比发脾气管用。孩子问为什么别嫌烦，答不上来就一起去查。定规矩可以硬，讲道理要留余地，先听他讲完再开口。",
  "qianYi|天府|male": "你出门在外不只是守得住。你还容易碰上愿意拉你一把的人，路子比待在原地更开。最合适的是金融、银行、保险、传统行业的跨地区调动，靠一点点积累站稳，不指望一夜翻身。\n\n建议你到外地做大额投资，先请当地专业人士把关。你熟悉的律师、会计对外地的规矩并不熟，这笔顾问费省不得。签合同逐条看，尤其是付款节奏和退出条款。陌生领域的金融产品别碰，你最容易栽的就是自己不懂的东西。",
  "fuQi|天相|female": "你在感情上忠诚踏实。你答应的事看得很重，认定一个人就不轻易放手。你不太会主动追人，缘分多半来自亲友介绍或者熟悉的圈子。你的丈夫多半年纪比你稍大，人忠厚可靠，做事有规矩，可能在行政、法律、财务或者大机构上班，不张扬但心里有主见，相处越久越能发现他的好，也是你实实在在的后盾。你们都偏稳重，日子过得有条不紊，很少大吵。\n\n太平稳的关系，热度容易随时间往下掉。别把不吵架当成一切都好。建议你每周固定留一段两个人的时间，一起吃顿饭、走一段路都行；心里的不满当次说清楚，别攒着。想认识人就大方请亲友介绍，这条路对你最管用。别因为对方稳当就把自己的想法全收起来，你的意见说出来，这段关系才走得长。",
  "ziNv|巨门|female": "你的孩子多半口才好、爱质疑。琢磨事情的劲头足，学业通常不差，尤其在辩论、写作、法律这些方向。孩子来得偏迟一些，过程也可能有波折，一开始不容易，往后会顺起来，这事放宽些看，不用跟别人比早晚。最大的隐患是母女之间斗嘴：你言语锐利，青春期的孩子反驳更锐利，辩着辩着就变成谁也不理谁。\n\n建议你换一套说法跟孩子讲话。把「你应该」换成「我希望」，把「你为什么」换成「我感到」。孩子顶嘴的时候先别接招，两个人都冷静了再谈。孩子问为什么别嫌烦，答不上来就一起去查。青春期尤其要留意话的分量，一句重话孩子能记很多年。",
  "qianYi|天府|female": "你出门在外容易遇到愿意帮你的人。你并不是不适合远行。你在异地的发展以稳定积累为主，不走一夜翻身那种路线。去一个新地方，优先挑有稳定平台或专业依托的去处，别把自己的落脚点押在别人的前景上。\n\n建议你异地投资先选熟悉的城市。投资前请当地的专业人士把关，合同逐条看，尤其付款节奏和退出条款。熟人介绍的高回报项目最容易让你放松警惕，越熟越要问清楚。",
  "fuQi|巨门|male": "你在感情里会表达。你能把感受和需要讲清楚，这是优势；但话太直、太多的时候沟通就变成吵架，口舌是非是你感情最大的挑战。你其实很认真，只是嘴比心快，伤了人自己又后悔。你太太口才好、有主见，不会因为你说话直就退让，可能做律师、教育、媒体或销售，你们斗嘴是家常便饭。你们之间常有一层话讲不到一块儿的隔阂，相处也容易磕碰；古书说巨门在夫妻宫宜配年长的妻子，年纪比你大一些的反而合得来，这是参考，不是硬条件。\n\n建议你们定个规矩。吵架只说眼前这件事，不翻旧账、不评价对方这个人。有话当天说开，别憋着等对方猜。少争谁对谁错，意见不同也各自留面子。你们是慢热型，前期多花时间聊、多建立信任，越聊得深越贴近。她在谈判、人脉和消息上最能帮你，遇到看不懂的局面先听听她怎么说。",
  "caiBo|太阴|male": "你的钱是慢慢攒出来的。它来自专业服务、固定薪水或者跟审美有关的活儿，稳当、细水长流。房子和不动产才是你真正的钱袋子，来快去快的投机不是你的路。你重视生活品质，在家里、吃的、旅行上舍得花，守钱的本事中等。漏钱的口子有两处：一是为家人和伴侣的大额付出，二是心情一上头就做的投资决定。感情顺、家里和睦的时候，你的财运也跟着顺。\n\n把稳定收入当主线，把房子当底盘。中年以后这块的价值会慢慢显出来。大额支出先过一夜再决定，别在情绪里签字。投资挑实在的、波动小的，高波动的金融投机少碰。为家人掏钱之前先算一笔，这笔出去会不会动到自己那份底。太太的收入跟你的财运关系很大，把感情经营好，本身就是在经营钱。",
  "jiE|天府|male": "你的底子偏结实。整体健康不差。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天府的五行去配。你的麻烦多半来自日子过得太安逸：动得少，代谢慢下来，体重一点点往上走，腰和关节也容易因为久坐劳损。你不爱说自己的担心，心事都往肚里咽，长期憋着会连着影响胃口和抵抗力。\n\n建议把运动当成纪律，而不是心情好才做。散步、徒步、健身都行，一周排进日程，关键是别断。吃上清淡规律，少油少盐，主食多一点粗粮，甜食要控制。每年定期体检，把血糖、血脂和体重这几项查清楚，有问题遵医嘱处理，别自己扛着。心里憋着的事找个人说说，别都自己咽。",
  "xiongDi|天相|male": "你的兄弟姐妹多半忠厚、好相处。人数不多，两三个居多。你们之间不爱大吵，家里的气氛是和和气气的那种。合伙做事，对方多半是二把手型：稳、配合、办事踏实，但主导力不够。方向得你来定，让他在后面把活落地，这套分工最顺。\n\n建议你合伙之前先把话说在前头。出多少钱、谁管什么、赚了怎么分，全写进合同。最要紧的是方向由你来定，条款自己过目，别做那个别人递过来就签字的人。兄弟姐妹或者合伙人开口借钱、要你担保，先说“我回去想一想”，隔一晚再回话。",
  "fuQi|巨门|female": "你在感情里会表达。你能把感受和需要说清楚，这是优势；但话太直太多的时候就容易变成吵架。你其实很认真，只是嘴比心快，伤了人自己又后悔。你先生口才好、有主见，不会因为你说话直就退让，可能做律师、教育、媒体或销售，你们斗嘴是家常便饭。你们之间常有一层话说不到一块儿的隔阂，相处也容易磕碰；古书说巨门在夫妻宫宜配年长的对象，另一半年纪比你大一些更合得来，这是参考，不是硬条件。你自己心里舒不舒坦，最影响这段关系稳不稳。\n\n建议你们约好：吵架只说眼前这件事。也不翻旧账、不评价对方的人。有话当天说开，你一个人憋着，这段关系就跟着晃。少争谁对谁错，意见不同也各留面子。你们是慢热型，多聊、多建信任，越聊得深越贴近。他在谈判、人脉和消息上最能帮你，遇到看不懂的局面先听他的。",
  "caiBo|太阴|female": "你聚财的本事在于稳。钱来自专业服务、固定薪水或者跟审美有关的活儿，一点点攒，攒得住。房子和不动产才是你真正的钱袋子，来快去快的投机不是你的路。你会过日子，精打细算的同时还能把生活质量保住。花钱的口子主要在家人和孩子身上——为他们掏钱的时候，最容易忘了自己那一份。\n\n把你挑东西的眼光用到买房上。看地段、看小区、看户型，你的细致在这里很占便宜。跟伴侣把钱的事摊开说清楚，房子写谁的名、日常开销怎么分、多大数额的消费要商量，先讲明白。为家人花大钱之前先算一笔，这笔出去会不会动到自己养老的那份。投资走稳的，波动大的东西少碰；中年以后房子的价值会慢慢显出来。",
  "jiE|天府|female": "你的底子偏结实。整体健康不差。身上哪一处要多留意，要看你全盘哪一宫杀星最集中，按那一宫的地支对应脏腑（子胆、丑肝、寅肺、卯大肠、辰胃、巳脾、午心、未小肠、申膀胱、酉肾、戌心包、亥三焦），不照疾厄宫这颗天府的五行去配。日子过得安逸、动得少，代谢就慢下来，体重一点点往上走，腰和关节也容易因为久坐劳损。你又不爱说自己的担心，长期憋着会影响胃口和抵抗力。\n\n建议把运动当纪律。一周排进日程四次以上，四十岁前后尤其别断。吃上清淡规律，少油少盐，粗粮多一点，甜食控制住。每年定期体检，血糖、血脂和体重这几项查清楚，再加一次女性专项检查，具体查哪几项听医生安排；备孕、怀孕这些阶段该做的检查按医嘱做足，孕期饮食也听医生的。有不舒服及时看医生，别自己硬扛。",
  "xiongDi|天相|female": "你的兄弟姐妹多半温和、好相处。人数不多，两三个居多。家里的气氛讲规矩也讲和气，姐妹之间不爱大吵，遇事各自先让一步。结婚以后，你在妯娌、嫂子之间常常是那个和事佬，稳重、有分寸，不巴结也不摆架子，公婆对你挑不出毛病。姐妹要是合伙做点小生意，你们配合得相当好。麻烦的是，好脾气一旦坐实，家里的事就都往你身上推。\n\n建议你学会说一句话：“这次我不行。”拒绝不是不孝，是给自己留条路。家族里出钱、出力、照顾老人这些事，早点摆到桌面上按人头分，别默认谁有空谁上——那个有空的人永远是你。真要跟姐妹合伙做生意，感情归感情，账目归账目：出多少钱、谁管什么、怎么分，写下来签字，比事后翻脸强。",
  "mingGong|太阴|male": "你对情绪、对美、对气氛特别敏感。别人接不到的细微感受你能接到，也能把日子过出味道。挣钱你走的是慢慢攒的路：稳定的收入、固定的薪水、房子这类看得见的东西，比一次大赚更合你。麻烦在于太容易被人影响，别人一句无心的话，你能翻来覆去想半天，白白耗掉精神。你待人温柔、会照顾人，常常顾着别人就把自己忘了。母亲和妻子，是你这辈子分量最重的两个人。\n\n先把情绪的边界立起来。别人的难处你可以帮，但他的情绪不是你的责任。收入以稳为主，有余力再往房子这类实打实的东西上放；大额投资之前找个冷静的人替你把账重算一遍，别光凭感觉拍板。压力上来别硬撑，给自己一两天安静时间缓过来。母亲和太太之间的事，早点当面说开。",
  "personality|太阴|male": "你是男生里少见的温柔细腻型。你心思软，体贴得近乎周到。别人忽略的小情绪你看得见，对方随口说过的喜好你记得住，这让你在亲近的人面前特别得人疼。但也容易被人说性子太软：你不爱直来直往，不爱在大庭广众下表现，宁可在背后把事默默办完。你在安静少打扰的时候状态最好，人多喧闹的场合反而耗你。\n\n挑行业要挑对。文化、艺术、媒体、咨询、教育这些吃细腻的行业适合你，硬碰硬的销售和拼体力的活儿别勉强。把最要紧的事排在清静的时段做。还有一条更要紧——你其实也想被照顾，只是从来不开口；以后想要什么就直接说，别指望对方猜。不用逼自己变成外向的人，你的细腻在懂得辨认的人面前很值钱。",
  "mingGong|太阴|female": "你天生秀气柔美。你气质温和，身上有一股说不上来的体面劲儿，收拾不收拾都好看。你感情细腻，对美有天生的眼光，对住的用的都有点要求，愿意在生活质感上花心思。你的钱跟房子有缘，攒得住，走的是稳的路。难处在情绪：像月亮一样有阴晴圆缺，好起来什么都行，低下去做什么都没劲，别人一句话能在心里搁很久。\n\n这一生最值得下功夫的，是把情绪的底盘稳住。给自己一个只属于你的角落，书房、阳台、一张固定的椅子都行，状态不好就去那儿待着，不必非找人排解。钱往房子这类看得见、拿得住的地方放，少碰来得快去得也快的东西。挑伴侣就看一条：他能不能接住你的情绪——不嫌你麻烦、不拿道理压你，这比条件重要得多。",
  "personality|太阴|female": "你温柔、敏感，心思细。别人没说出口的情绪你都能接到，这让你在亲近的人面前是最柔软的那个存在。反过来也一样：别人无意的一句话，能在你心里回响很久。你像月亮一样有圆有缺，不同时段的状态差别明显，好的时候什么都做得动，低的时候连回个消息都费劲。你从来不缺人喜欢，缺的是真正护得住你这份柔软的人。\n\n别把自己练成钝的。那不是长大，是把月亮锯成石头，给敏感留一道屏障就够了。具体怎么做：分清哪些事是你的、哪些是别人的，别人的情绪你可以心疼，但不用扛过来。重要的事排在状态好的时段做，低谷那几天只做最要紧的几件。感情上不用急着定下来，等自己心性稳一些再谈婚嫁；挑人就看一条，他护不护得住你。",
  "tianZhai|太阴|male": "房子这一块，是你这辈子最扎实的一块底子。先有一处自己住的，慢慢再添置，这是你最顺手的攒钱方式。家对你来说比事业和交际都更要紧，家里安不安稳，直接决定你在外面有多少劲。\n\n买房按自己的节奏来。先求一处住得舒服的，把日子安顿好，再谈第二处，别为了赶行情把自己绷太紧。买卖签合同逐字看清，产权、面积、交付时间都写明白，别怕麻烦。装修往柔和温馨走：暖色调、采光好、卧室安排在安静的一侧。你睡得好，第二天整个人就不一样，这是你养生的根子。",
  "tianZhai|太阴|female": "房子对你来说不只是财产，是你的根。你对住得安不安稳要求特别高，条件允许的话，有一处完全属于自己的空间，你整个人就踏实了——这不是不信任伴侣，是你这样的性子本来就需要一块能独处的地方。\n\n买房签合同逐字看清。产权写谁的名、面积、交付时间都白纸黑字写明白，别怕麻烦。家里一定要留一个只属于你的角落：书房、阳台、一张瑜伽垫都行，状态差的时候去那儿待着，比找人诉苦恢复得快。装修往柔和走，暖色调、采光好，多放点绿植和自己喜欢的小物件，你住得舒服，人就稳。",
  "fuQi|天梁|male": "你挑另一半看的不是外表和条件。你更看人品和过日子的态度，宁可多等也不将就，所以多半不会太早成家。你在感情里习惯当照顾人、拿主意的那一个，久了关系容易不对等，对方会觉得自己被当成了学生。跟你合得来的太太，宜比你年长几岁，成熟、有阅历，遇上大事能稳住，可能做法律、医疗、教育或咨询这类工作；她不一定替你出头，但她在你身边本身就是你的底气。你们相处像老友，不用天天黏着。\n\n建议你少用教的口气。遇事先听她说完，再讲你的看法。古书说天梁在夫妻宫妻子宜比你年长，太太比你大几岁不是问题，别让年龄差成了你犹豫的理由。感情上你慢一点没关系，但别拿一张挑人的清单把自己卡住，人品和态度对了就往前走一步。两个人闹僵的时候直接把话讲开，你的冷处理比吵一架更伤人。",
  "fuQi|天梁|female": "你对感情的要求高，高在精神层面。人要谈得来、撑得住，光有条件不行，想走进你心里并不容易。你在关系里习惯当照顾人、出主意的那一个，像姐姐也像老师，结果反倒让两个人不平等，对方久了会觉得喘不过气。适合你的丈夫，是阅历比你厚、见过点世面的人，他在精神上接得住你，你才愿意把盔甲卸下来。\n\n建议你在他面前试着先示弱一次。一件小事上说我搞不定，你来。他有机会照顾你，关系才不是单向的。少给建议，多问他怎么想，哪怕你心里早有答案。他做得不如你，允许他慢一点、错一点。心里有不满别憋着，当天就讲出来，你一憋就冷着脸，那比吵一架更伤人。",
  "xiongDi|天梁|male": "你的兄弟姐妹多半也是稳重老成的性子。彼此有种互相罩着的劲儿，谁出事另一个都能当靠山。缘分的厚薄各家不同：有的就一两个手足、处得和气，有的人数不少却各过各的，平时走动不多。\n\n要合伙，优先找法律、医疗、教育、文化圈的人。他们跟你最合得来。开工前先把分工写下来：谁管钱、谁管事、谁拍板，白纸黑字比交情靠谱。你最容易犯的毛病是什么都管，管到最后什么都没做好，先划一条线，线以外的不接。跟手足别只在出事时才联系，平时一顿饭、一个电话，感情是养出来的。",
  "xiongDi|天梁|female": "你的兄弟姐妹多半也是稳重的性子。彼此有种互相罩着的劲儿，谁出事另一个都能当靠山。缘分的厚薄各家不同：有的就一两个手足、处得和气，有的人数不少却各过各的，平时走动不多。婚后跟丈夫家的嫂子、弟媳一起，你天然带点长辈感，家里的事她们爱来问你。\n\n建议你先列一张自己不管的清单。哪几类事不接、哪些忙不帮，写下来，真有人开口你才说得出口。跟手足别只在出事时联系，平时一顿饭、一个电话，感情是养出来的。要合伙就把分工白纸黑字写清楚，谁管钱、谁拍板，交情归交情，账归账。",
  "mingGong|天梁|male": "你遇事冷静、讲道理。你有一种超过年龄的成熟，越是乱局你越稳得住，是关键时刻别人想找你拿主意的那种人。你心里干净、不藏私，看着温和，真到原则的事上一点不让；再难的局面你也总能找出一条路。代价是你对对错看得太重，容易拿自己的标准衡量别人，让人跟你相处有点压力。朋友找你多半是来请教，不是来玩，圈子不宽，但都是真能帮上忙的人。你觉得自己该帮人、该把经验传下去，结果常常什么都往身上揽。\n\n建议你放过自己一点。别人不合你的标准，不代表他就错了，少一句评判，身边的人松快，你也松快。事情找上门先问一句这是不是我的责任，不是就别接。做决定你偏稳，这没问题，但每隔一两年，逼自己接一件没做过的事。也别把自己框在一个身份里，文的武的你都拿得起来，路比你自己想的宽。",
  "personality|天梁|male": "你比同龄人显老成。不是长相，是那股沉得住气的劲儿。为人厚道，看着好说话，真碰上原则的事一点不让。你身上有种天生罩着人的本能，朋友一出事第一个想到你，同事卡住了你会主动伸手。这让你人缘好，也让你累——别人的麻烦你太容易接过来，明明不关你的事，最后你陷在里头。感情上你容易吸引比你年轻、或者更需要人照顾的对象，你也享受那种被需要的感觉。\n\n建议你学会说一句实话。这事我帮不了，你得自己走一遍。不是冷血，有些人本来就得自己摔一跤才肯站起来。挑工作往帮人那条线走最顺，公职、老师、医生、文化都合你的性子；生意场也不用躲，你只是更愿意凭真本事，不靠嘴皮子。另外一周留出两小时不接电话、不管别人的事，那是你补回力气的地方。",
  "ziNv|贪狼|male": "你的孩子多半是小小社交家。才艺多、人缘好，在艺术、表演、跟人打交道这类事上有天分。孩子数量一般不多，早些年亲子缘分费点劲，或者当爸爸比同龄人晚一些，中年以后关系反倒越来越顺。最要留神的是青春期那几年，感情来得早，对刺激的东西也好奇。\n\n建议你趁早跟孩子把话摊开讲。讲讲喜欢一个人是怎么回事、身体上怎么保护自己、钱该怎么花。你自己就是这么过来的，讲这些比谁都有说服力，别拿家长架子压。零花钱设额度，手机和游戏定好时间，规矩先立后放。孩子身体上的具体问题，看医生比看星盘靠谱。",
  "jiaoYou|破军|male": "你的朋友圈起伏大、聚散无常。年轻时人来人往，朋友圈换得快。破军在这一宫的亮度，决定朋友和下属肯不肯替你出力。最大的坑是有人拉你去做来钱快的事，一起栽进去。\n\n建议你对所有“快钱”“一夜翻身”的邀约直接回绝。不用给理由。朋友要借钱、要你签字担保，一律说回去想想，隔一天再答复。留人不靠热闹，靠你真办成过的事：把能一起做事的两三个人稳住，比认识一百个强。",
  "fuMu|七杀|male": "你跟父母的关系偏冷。这不是不爱，是你天生不擅长把感情说出口：心里惦记，嘴上不讲，行动上也不主动。早早离家、聚少离多，对你来说是常态。父亲留给你的印象多半就是严厉两个字，你成长里的规矩和压力大多来自他。也有另一种情况：父母跟你话不多，却在关键时候稳稳托着你，给本钱、给人脉。\n\n建议你中年以后主动替父母安排常规体检。还要陪着去，别只是转钱。每周固定打个电话，哪怕只说三句话，频率比内容重要。跟父亲的和解是你这辈子要补的一课，可以从一起吃顿饭、听他讲讲年轻时候的事开始，不用非要谁先道歉。",
  "mingGong|天梁|female": "你独立、想得明白。你有一种超过年龄的沉稳，别人遇事慌了，你还在算下一步。你身上有股男人一样的担当，扛得住事，家里人跟着你也有底，对丈夫和孩子都是实实在在的帮衬。你一生贵人不少，卡住的时候总有年长、说得上话的人出手。感情上你习惯当照顾人、给建议的那一个，像老师对学生，时间久了对方会有压力。你对自己和身边人都端着一套高标准，最后累的也是自己。\n\n建议你在亲近的人面前学会示弱。累了就说累，不会就说不会，这不掉价，反而是让人靠近你的入口。挑伴侣找阅历比你厚一点的，你才愿意放下防备；相处时把给建议换成问一句你怎么想。工作往法律、医疗、教育、公益这类帮人的方向走，你做得比谁都投入。标准别一刀切，给身边人留点不完美的余地。",
  "personality|天梁|female": "你天生是身边人的主心骨。朋友失恋来找你哭，同事加班你给她带夜宵，亲戚出事你第一个到。你为人稳重、心里干净，看着温和好说话，真到原则上的事一点不让，扛事的劲儿不输任何人。别人都把你当那个能出主意的，遇到坎儿先想到你。代价是你常常把自己排在最后：大家默认你扛得住，你也习惯了不开口说难受，久了连你自己都忘了还可以喊累。\n\n建议你从一件小事开始练习求助。搬东西让人搭把手，心里堵了找人说一说。你不需要每次都当那个解决问题的人。往教育、医疗、咨询、公益这些帮人的行业走，你做得最有劲。每周给自己留一段谁也打扰不到的时间。先把自己活成一个值得被人照顾的人，再去照顾别人，这不是自私，是你给自己留的退路。",
  "ziNv|贪狼|female": "你的孩子多半是小小社交家。才艺多、人缘好，走到哪儿都有人喜欢。你当妈妈最大的长处是听得懂孩子，他那些五花八门的兴趣你都能接上话，秘密也愿意跟你说。最要留神的是青春期那几年，感情来得早，对刺激的东西也好奇。\n\n建议你趁早跟孩子把话讲开。讲讲喜欢一个人是怎么回事、怎么保护自己、钱该怎么花。零花钱设额度，手机和游戏定时间，规矩先立后放。有个坑要提醒你：别把自己的活法套在孩子身上，你年轻时爱玩的，他未必想玩；你觉得刺激的，他可能只觉得吵。身体上的具体问题去看医生。",
  "jiaoYou|破军|female": "你的朋友圈起伏大、聚散无常。年轻时人来人往，朋友圈换得快。破军在这一宫的亮度，决定朋友和下属肯不肯替你出力。男性朋友和一起做事的伙伴里，常有真正的战友。\n\n建议你别为了合群硬凑价值观不同的圈子。省下的力气留给能接受你折腾的那几个人。少数能陪你穿过几次大变动的朋友，值得你主动维护：定期约、有事真到场。合作型的朋友关系，把钱和分工先说清楚，感情才不容易折在里面。",
  "fuMu|七杀|female": "你跟父母的关系偏冷。这不是不爱，是你天生不擅长把感情说出口。早早离家、聚少离多，对你来说是常态。童年里常见的底色是父亲的严和母亲的沉默，你很早就学会了不吭声地自己扛。婚后跟公婆相处，你也装不出乖顺那一套，硬装反而会把自己憋坏。\n\n建议你中年以后主动替父母安排常规体检。还要陪着去，别只是转钱；每周固定打个电话，哪怕只说三句话。跟公婆做到礼数到位就行，该给的照顾给到，情感上的亲密不用勉强，双方都轻松。跟父母的和解是你中年后要补的一课，可以从一起吃顿饭、听他们讲讲从前开始。",
  "fuQi|贪狼|male": "你在感情里重感觉，喜欢有活力、有趣味的相处。你享受恋爱里那股心跳和新鲜，可关系一旦稳下来，热情就容易退，得刻意经营才走得长。不用急着早早结婚，把自己想要什么看明白了再成家，会更从容。你的妻子多半也是会聊、会玩、有才艺的人，在饭桌上能把全场带活，她的圈子还常给你带来计划外的机会。\n\n建议你别把新鲜感当成感情好不好的标准。激情退下去是正常的，接下来靠的是一起过日子的本事。定几件固定要做的事，比如每周留一个晚上只给彼此、每年一起出去一趟。两个人都爱自由，稳定这块得有一个人主动扛，谁扛提前说清楚。真要两地分开，先把见面频率谈定再走。",
  "qianYi|破军|male": "出门在外是你的天然舞台。走出去才成得了事，你比大多数人都适合远行闯荡。代价也很明确：在外奔波、心里安定不下来，这一条免不了。顺的时候你在外头能闯出名堂，越往外越能成事；但也有跑来跑去使不上劲、白忙一场的阶段。\n\n建议你远行优先挑有挑战性的活。创业、改革项目、技术开拓都行，别只是换个城市做老本行，重复的事你撑不住。人走到哪，落地先办三件事：住处定下来、认识两三个当地能说上话的人、把钱分开账户放。化权（掌权）时你在外地能当主导改革的那个人，敢接就接。",
  "fuDe|七杀|male": "你的精神状态很像一个独来独往的战士。白天在外面拼，晚上需要一个人待着。你不习惯跟人讲心事——朋友面前你是硬汉，伴侣面前你是支柱，家里人面前你是顶梁柱，真正软的那一面只在独处时才露出来。心里踏实的时候，你忙归忙，自己能调得过来；心里没着落的时候，就容易硬扛到崩：明明累了不肯歇，明明难受不肯说，明明需要人帮也不开口。\n\n你最该改的一件事是把求助和失败分开。开口找人帮忙不等于你不行。建议每周固定留半天完全不排事情，睡觉、发呆、走路都行。中年以后可以试试找专业的人聊一聊，或者慢跑、游泳、写字画画这类能让人静下来的事。手上有一门拿得出手的本事最稳，专心做一行，别这山望着那山高。",
  "fuMu|天梁|male": "父母这条线是你一辈子的主轴。他们多半厚重、有威严，跟你之间的冲突不算多，真正的张力是你总想做到他们期待的样子。\n\n建议你趁早跟父母把该问的问了。家里的老事、他们的身体、以后的打算，别等到没机会问。提醒他们定期体检，不舒服及时看医生。你跟长辈型的上司特别合得来，主动找一位老资历的人当师父。别把他们的期待当成必须完成的任务，你自己过得好，本身就是他们要的结果。",
  "fuQi|贪狼|female": "你身上的吸引力很强。你有自己的魅力和才艺，容易让人留下印象。你在感情里是主动热情的一方，享受心跳和新鲜，可关系一旦安稳下来，热情就容易往下掉，得刻意经营才走得远。人缘好不等于选对了人，热闹里保持判断最要紧。这是生年带来的底子，哪个十年、哪一年被引动，要再看运限。\n\n建议你把择偶标准写下来。分清哪几条是底线、哪几条可以让，白纸黑字比当下的感觉靠谱。别急着定，认识半年以上再谈婚嫁，晚一点结婚对你多半是好事。你未来的丈夫大概也是有才艺、会社交、挺有魅力的人，但两个人都爱热闹，日子里的稳定得有人主动去守。遇到纠缠不清的人，早点断干净。",
  "qianYi|破军|female": "出门在外是你的天然舞台。你比同龄人更敢远走、更敢推翻原有的生活。代价也很明确：在外奔波、心里安定不下来，这一条免不了。顺的时候你在外头能闯出名堂，越往外越能成事；但也有跑来跑去使不上劲、白忙一场的阶段。你性子偏孤僻，一个人在外的孤单感会比别人重。\n\n建议你远行挑有挑战性的活。别只是换个城市做老本行。落地先办三件事：住处定下来、认识两三个当地能说上话的人、给自己留一个固定的情感出口，哪怕每周固定跟老友通个电话。远嫁的话，别一边过新生活一边死守原来的自己，也别动不动就往娘家跑，那会让你卡在中间两头耗。化权（掌权）时你在外地能当主导改革的人，敢接就接。",
  "fuDe|七杀|female": "你的精神状态像一个孤身作战的人。白天在外面拼，晚上需要一个人待着。你不习惯跟人讲心事——朋友面前你是硬气的那个，伴侣面前你是独立的女人，家里人面前你是顶梁柱，真正软的那一面只在独处时才露出来。心里踏实的时候，你忙归忙，自己调得过来；心里没着落的时候，就容易硬扛到崩：明明累了不肯歇，明明难受不肯说，明明需要人帮也不开口。\n\n你最该学的一件事，是接住别人递过来的伞。你已经为自己撑了太久。建议每周固定留半天完全不排事情，睡觉、发呆、走路都行。中年以后可以找专业的人聊一聊，或者慢跑、游泳、写字画画，让自己慢下来。手上有一门拿得出手的本事最稳，专心做一行，别这山望着那山高。",
  "fuMu|天梁|female": "父母这条线是你一辈子的主轴。他们多半厚重、有威严，跟你之间的冲突不算多，真正的张力是你总想做到他们期待的样子。\n\n建议你趁早跟父母把该问的问了。家里的老事、他们的身体、以后的打算，别等到没机会问。提醒他们定期体检，不舒服及时看医生、听医生的。公婆愿意把事交给你是信任，但别为了当好儿媳就把所有问题都揽下来，接得住的接，接不住的直说。工作上主动找一位资历老的女性前辈当师父，帮助很大。",
  "guanLu|天同|male": "你事业上最大的助力是人缘。同事愿意配合，贵人多半是和气的长辈，或者圈子里有人替你引荐，工作整体挺顺，不用太拼也能维持得不错。服务、医疗健康、教育、艺术设计、餐饮酒店这类跟人打交道、要耐心的行业最合你。你在团队里是润滑剂，协调关系是强项，但催进度、拍板做决定不是。你不是只能干轻省活，问题在于有没有人把你推出去。\n\n建议你待在稳定的单位里做。别轻易一个人出去创业；真要合伙，找个有冲劲的搭档推着你跑。每做完一件事，主动跟上级讲清楚哪部分是你做的，别指望别人替你记功。每年定一个够一够才拿得到的目标；一个位置待得太舒服超过三年，就该动一动。",
  "caiBo|天机|male": "你的钱来得有起有伏。不是攒下一笔就能躺着吃的路子，靠的是你脑子跟不跟得上。稳稳地帮人做事、领薪水或接活拿报酬，才是你的底子；靠运气博来的钱留不住。把脑子变成钱是你最自然的路——讲课、咨询、做方案、写东西都算。你赚钱的本事强过守钱的本事，想法一多就把钱分到好几个方向，最后哪个都没养大。早年收入起伏大，四十岁以后经验攒够了才慢慢稳下来。\n\n建议你把最好的精力放在一个主要收入来源上。别四处出击。投资方向收到两三个就够，看不懂的新东西先放一放，手上留足现金再谈别的。想试新项目就先设上限：只投亏得起的那一部分。每月发薪当天自动转一笔钱进不轻易动的账户，不靠自觉，靠自动扣款。",
  "ziNv|紫微|male": "你的孩子是个小皇帝脾气。他自尊心强、要独立，从小不吃硬的，你越压他越反弹。偏偏你最容易犯的错就是拿家长身份压人，结果孩子长成跟你一样的硬脾气，回头跟你顶到底。你的孩子里常有一个特别出挑的，多半是老大，他往后走的路甚至会影响你晚年心里有没有着落。\n\n从孩子上初中开始就练着放手。能他自己决定的事一年比一年多交出去，少管具体怎么做，多讲清楚底线在哪。说话时把命令句换成问句，「你打算怎么弄」比「你应该怎么弄」管用得多。真吵起来你先退一步，等两个人都冷静了再谈。你能给孩子最值钱的东西是资源和见识，不是替他把路选好。",
  "qianYi|太阳|male": "你是往外走才发光的人，守在老家反而施展不开。家里的老本行、老产业通常帮不上你，多半得自己挪窝、换个地方重新扎根，在外地闯名声比在本地快得多。往东边、南边这类热闹、舞台大的地方去，一般更顺手。\n\n建议你这辈子至少去一次大城市、大平台或者国外。认真把摊子铺在更大的地方，这一步对你几乎是少不了的。人到了外地，酒局应酬要格外当心，感情和钱上的乱账在陌生地方最难收拾，能不喝就不喝，能带上同事就别单独去。化忌（阻碍）时，出门容易惹是非、伤名声，那阵子少露面、少接不熟的合作，手续和合同都办清楚。",
  "jiaoYou|武曲|male": "你的朋友圈偏务实。朋友多是因为共事、因为利益走到一起，很少有那种掏心掏肺的交情。你带人也一样，能干、执行力强、不用多说就把事办了的下属，跟你最合拍。\n\n建议你只跟讲合约、认规矩的人合伙。别跟那种「够意思就行」的人绑股权。合作前先把散场的规矩谈好：怎么分账、谁说了算、谁想退出怎么办，怎么散比怎么开始更重要。替人做担保这件事尽量不沾，吃亏的多半是你。",
  "fuMu|廉贞|male": "你跟长辈的缘分偏淡。不是感情不好，多半是聚少离多、各过各的。你的父母通常是有故事的人：职业特别，或者人生经历不太寻常；家里的气氛也比一般人家复杂，可能有些说不清的老账、长辈之间的感情旧事，或者小时候跟着爷爷奶奶长大。化禄（进财）的时候，父母能给你别处拿不到的资源和见识。\n\n建议你把联系变成固定动作。每周一个电话，每年回去几次，不靠心情靠日程。长辈的身体按常规体检来，有问题听医生的，别照着命盘自己吓自己。这一条在单位里也一样：你跟上司容易互相猜，你看得穿他却不说，他也觉得被你审着，有想法就当面讲清楚，别把神秘感当护身符。",
  "guanLu|天同|female": "你工作上最大的助力是人缘。同事愿意配合，机会常是熟人引荐来的，整体挺顺，不用太拼也能维持得不错。服务、医疗健康、教育、艺术设计、餐饮酒店这类跟人打交道、要耐心的行业最合你。你在团队里是协调关系的那个人，但催进度、拍板做决定不是强项。你对职位高低、排名前后没那么在乎，工作和家庭之间弹性很大，风险也在这儿：日子一舒服就容易停在原地，功劳也常因为不会讲而被别人领走。\n\n建议你不管重心放在哪一边，都别把这条事业线断掉。兼职、手艺、副业都算，一是手里有自己的钱，二是别让生活只剩家里这一圈。每做完一件事，主动跟上级讲清楚哪部分是你做的。打算生孩子的话，提前跟伴侣把谁来带、什么时候回去上班讲明白，写下来最好。",
  "caiBo|天机|female": "你的钱来得有起有伏。靠的是你脑子跟不跟得上，不是攒一笔就能躺着吃的路子。稳稳地帮人做事、领薪水或接活拿报酬是你的底子；靠运气博来的钱留不住。把脑子变成钱最自然——讲课、咨询、做方案、写东西都算。你赚钱的本事强过守钱的本事：研究东西、比价格你是行家，可看得越多买得越多，订阅、护肤、小物件一笔笔加起来，是看不见的漏钱口子；心里不痛快的时候，更容易靠买东西转移注意力。\n\n建议你给自己定个等待期。想买的先放进清单，等满三天再决定，多数时候就不想要了。把每月的订阅列一张表，用不上的直接退掉。投资方向收到两三个，看不懂的先不碰，手上留足现金。记账你本来就在行，再加一条：每月发薪当天先自动转走一笔存起来，剩下的才是能花的。",
  "ziNv|紫微|female": "你的孩子是个小皇帝脾气。他自尊心强、要独立，从小不吃硬的。你偏偏是那种「我都是为你好」的妈妈，替他把路铺得明明白白，可孩子从小就能感觉到这份爱里带着管，你越替他安排，他越要反着来证明自己行。\n\n把力气更多花在给孩子创造条件上。别替他做决定——你争取来的好学校、好平台、好机会，比你直接告诉他该选什么有用得多。孩子一上初中就开始练放手，少说多看，能他自己定的事一年比一年多交给他。真吵起来你先退，等两人都冷了再谈。还有，坐月子交给专业的人照顾，别硬撑。",
  "qianYi|太阳|female": "你是往外走才顺的人。老家的旧资源通常帮不上忙，换个城市重新扎根，反而更容易闯出名堂。在外地、外企或跨地区的平台上，很多在本地压着你的东西会松开，施展空间大得多。成家以后走动受家里牵制是常事，但你要是完全待在家里，人很快就蔫了——你得跟外面保持来往才有精神。\n\n建议你趁早争取外派、留学或者跨城调动的机会。这段经历是你独立起来最关键的一步。成家以后可以试试远程办公或者两地跑的安排，别把自己彻底困在家里。一个人出远门，行程告诉家人、住处选正规的，异地的酒局应酬尽量别单独去，界线讲在前面。化忌（阻碍）时，在外容易被人说闲话或者被搭讪骚扰，那阵子少接陌生邀约，安全上多留个心眼。",
  "jiaoYou|武曲|female": "你的朋友多是因为共事、因为合作走到一起的。关系能长期维持，但掏心掏肺的交情不多。你带人倒是顺手，能干、话不多、把事办成的下属跟你最合拍。\n\n建议你别勉强自己挤进不喜欢的圈子。把力气花在两三个同样独立、同样实在的朋友身上，创业型、专业型的女性通常跟你最搭。合伙这件事，合约和退出机制一定要写在前头，替人做担保尽量不沾，吃亏的多半是你。",
  "fuMu|廉贞|female": "你跟长辈的缘分偏淡，多半是聚少离多、各过各的。父母通常是有故事的人，家里的气氛也比一般人家复杂。最值得说的是你和母亲：你们之间的牵扯特别深，她可能既是你最亲的人，也是你最疼的那处伤。化禄（进财）的时候，母亲是你审美和眼界的启蒙人，父母也能给你别处拿不到的资源。\n\n建议你跟母亲的关系不用急着理清楚。先把相处的方式定下来：能聊的多聊，聊不来的话题绕开，别每次见面都翻旧账。长辈的身体按常规体检来，有问题听医生的，别照着命盘自己吓自己。婚后跟公婆保持基本的礼数就够了，不用强求亲密，你的性子本来就不容易被长辈读懂，客气而有距离，反而处得久。",
  "xiongDi|巨门|male": "你的兄弟姐妹多半也是有主见、爱讲道理的人。你们凑一块儿常常谁也不让谁。人数不多，心思也不容易想到一处去，早点各住各的反而少摩擦。合伙做事你最怕口头约定，你的疑心加上对方的疑心，在没有白纸黑字的合作里很容易发酵成猜忌。\n\n建议你合伙之前先把话讲明白。合同一条条写清楚，账目公开、定期对账。你怕的从来不是把话说开，是把话憋住。找律师、教培、传媒这类靠专业和口才的伙伴最合拍。跟兄弟姐妹相处，少争对错，多问一句对方是怎么想的；一年能一起吃上几顿饭，比争赢一次有用得多。",
  "ziNv|太阴|male": "你的孩子敏感细腻、会看脸色。你心情好不好他一眼就看出来，是难得的贴心孩子。你跟女儿的缘分尤其深，生女儿或者先生女儿的情况更多。你当爸爸最大的本事是听得懂孩子心里那点小九九，是孩子愿意主动讲秘密的那种爸爸。\n\n别什么都替他做。爱不是我全包了，是让他自己站得住：小到收拾书包，大到选专业，让他自己拿主意、自己担后果。你共情太强，容易把孩子的情绪整个扛过来，扛久了两个人都累——先分清这是他的事还是你的事。孩子跟你讲心事的时候多听少评判，他就会一直愿意讲。",
  "xiongDi|巨门|female": "你们家从小就是讲道理的家庭。姐妹兄弟之间什么话题都能辩一辩。人数不多，心思也不容易想到一处，各过各的反而少摩擦。\n\n建议你在家族里说话先换个开头。把「你这样不对」换成「我是这么想的」，杀伤力差很远。对方诉苦的时候先听完，别急着给方案。合伙做事挑讲道理的人，别拿姐妹情谊当合同，该写的条款一条条写清楚，账目定期对。真要争的事留到私下，饭桌上不辩输赢。",
  "ziNv|太阴|female": "你跟女儿的缘分极深。母女处得像姐妹一样亲，是难得的一种母女缘，生女儿或者先生女儿的情况也更多。你当妈最大的本事是听得懂孩子心里那点小九九，尤其是女儿青春期那些说不清的情绪。生孩子这件事你通常还算顺，坐月子多半有家人照顾。\n\n最要防的是共情过头。你会把孩子的情绪整个扛到自己身上，结果母女俩互相消耗。她哭的时候，你先在心里分一句——这是她的情绪，不是我的责任。你不需要为女儿的每一种情绪买单，听她说完、陪着就够了，别急着替她解决。月子里让家人照顾，别逞强，这一个月养好了，后面几年都省力。",
  "mingGong|巨门|male": "你天生会分析、也会表达。你心思细、看得准，能把复杂的事几句话说清楚，一开口就说到点子上。需要说服人、辩论、做判断的场合你最吃香。弱点是疑心重，爱反复琢磨别人的动机，防备心一起来，本来能交心的人也被挡在外面。你也容易想得多、学得杂却不精，跟人相处不算合群。说话太直，听的人会觉得有压力，一句刺人的话就能惹出本来不会有的麻烦。\n\n建议你把说话的力气只花在真正重要的事上。想顶回去的时候先停三秒，问自己说完能改变什么。做决定别等想透，信息到七八成就动手，给自己定个截止时间。信任可以分步给，先在小事上试，看结果再加码，比在旁边观察半年管用。心里堵的时候找个能听你讲完的人说说，你是讲明白了才放得下的那种人。",
  "personality|巨门|male": "你说话有条理、想得深。口才和是非哪头重，只分了庙旺、落陷两头，你这颗巨门在两头之间，原讲没有明说。但这张嘴同时也是负担：说错一句能在心里翻来覆去想三天，一点误会能纠结半年。你多疑不是没来由，是看得太细，一个表情能读出十层意思，所以不容易吃亏，也很难真正轻松。最容易掉的坑是钻牛角尖，一件事想不通就停在那儿反复推演，最后什么都没做。\n\n建议你给想事情设个闹钟。二十分钟没结论就先做别的，换个日子再想往往就通了。跟人有误会别自己猜，直接问一句省你三天。交朋友挑能跟你深谈的，浮在表面的关系你也受不了。最要紧的是：这张嘴能让你赚钱、能帮你把理争回来，也能在三秒里毁掉你最在乎的关系，话到嘴边多想一步。",
  "mingGong|巨门|female": "你心思缜密、说话清楚。口才好、分析力强，再乱的人和事你都能很快理出头绪。你天生看得深，能看穿表面底下的道理，但也容易在心里绕来绕去、钻牛角尖。你想得多、学得杂却不容易学精，跟人相处不算合群。感情上你最容易吃亏的地方是说话太直、太有主见，你觉得是在分析，另一半听着像批评。\n\n建议你保住分析力的同时，练一练怎么把话说软。同样的意思，先肯定再提问题，把「你应该」换成「我希望」，效果差很远。职业上可以放心往律师、老师、传媒、咨询、外语这些靠嘴和脑子吃饭的方向走，你在专业上很有竞争力。开口之前给话加一层温和的包装，是你最划算的一笔投资。",
  "personality|巨门|female": "你说话有锋芒。这不一定是恶意，是你天然能直击要点，让对方有点招架不住。这份口才在职场是优势，在家里常常变成杀伤力：你跟伴侣吵架很少输，但赢完两个人都不开心。你心思深、爱钻研，对秘密和真相有股执着，别人觉得没什么的事你能查出三层，所以不容易被骗，也容易陷在怀疑里出不来。人多话多的场合其实是你的主场，只是锋芒要收进专业里。\n\n建议你把最锋利的话留给工作。回到家换一套说法：先说你听懂了什么，再说你不同意什么。想赢的冲动上来时提醒自己，你真正要的不是赢，是对方愿意把你的话听完。法律、咨询、研究、心理这些靠洞察力吃饭的行当最适合你，往这几个方向走能把天赋放对地方。疑心起来直接问一句，比自己推演一星期强。"
}

STAR_BRIGHTNESS_DB: dict[str, str] = {
  "mingGong|贪狼|庙旺": "贪狼庙旺（丑未宫），桃花与才艺达到顶峰，但午宫贪狼转武官星（火贵），午宫贪狼「不要随便乱批桃花」、更宜从政从军；子（亥）宫贪狼则为正格泛水桃花命。",
  "guanLu|七杀|庙旺": "七杀庙旺在官禄宫，《全书》说「七杀庙旺武职峥嵘权贵非小，不宜文人」。",
  "mingGong|武曲|庙旺": "武曲庙旺，刚毅果决的特质全开，执行力和财务能力达到顶峰，在实业或金融领域能做出大成就，是最能赚钱的状态。",
  "mingGong|武曲|落陷": "武曲落陷，刚毅之气减弱，执行力打折，财运起伏明显，容易因过于强硬而错失合作机会，建议软化处事方式。",
  "caiBo|廉贞|庙旺": "廉贞庙旺（寅申宫）守财帛宫，文武才艺与桃花魅力同时变现，社交圈即是财富圈，越活跃越有钱，最适合个人品牌或创意类创业。",
  "caiBo|廉贞|落陷": "廉贞落陷在财帛宫或三方，桃花变烂桃花，财来自不可靠的对象，容易遭遇感情骗局或合作欺诈。需提高辨别力，重要交易务必查清对方背景。",
  "jiE|天梁|庙旺": "天梁入庙旺，病后恢复力好。《全书》卷一天梁条说天梁「居奴仆、疾厄、相貌作丰余之论」，坐疾厄本是有余之象。但仍要每年定期体检，切勿因“能扛”而忽视早期信号。",
  "mingGong|天同|落陷": "天同落陷，福气打折，享乐主义容易导致不进则退，需要刻意克服惰性，适度自我鞭策。",
  "mingGong|天同|庙旺": "天同庙旺，福星满盈，生活安乐，幸福感最高，在舒适的环境中能最大限度发挥天同的福气特质。",
  "mingGong|天机|庙旺": "天机庙旺，智慧与变通能力全开，策划分析能力达到顶峰，是顾问、分析师、策划师最好的命格。",
  "mingGong|天机|落陷": "天机落陷，聪明才智发挥打折扣，多变而缺乏执行力，容易因善变被人认为不稳定。建议专注一个方向深耕，以稳为主。",
  "fuQi|紫微|庙旺": "紫微庙旺在夫妻宫，配偶的贵气与能量达到最大值，对方在社会上相当有地位，婚姻给你带来极大的贵人资源，是令旁人艳羡的婚配。",
  "fuQi|紫微|落陷": "紫微落陷在夫妻宫，配偶的贵气有所削减，可能地位不如预期，或双方的气场不够匹配，感情中的能量对比容易失衡，需要更多耐心与包容。",
  "mingGong|七杀|庙旺": "七杀入庙旺，将星之气全开，意志力与执行力都在最佳状态，适合在竞争激烈的领域冲锋陷阵，七杀朝斗格则更可爵禄荣昌，武职或创业格局极高。",
  "caiBo|贪狼|庙旺": "贪狼庙旺（丑未墓宫）守财帛宫，才艺与社交财运全开，逢火铃同宫则成「火贪格」「铃贪格」，是14主星中偏财暴发力最强的格局之一，意外横财机会显著高于他星。",
  "mingGong|紫微|庙旺": "紫微入庙，帝星威仪全开，领导力和贵气达到顶峰。这是最能展现紫微贵格的状态，在高平台上如鱼得水，名利可以兼得。",
  "mingGong|紫微|落陷": "紫微落陷，帝星威仪受压，贵气不足，地位难以完全展现。付出与回报之间容易失衡，宜以低调务实代替高调强势，借助他人平台发挥更佳。",
  "fuQi|天府|庙旺": "天府庙旺在夫妻宫或三方，配偶稳重可靠，财务能力强，婚姻基础扎实，是令人安心的伴侣。",
  "caiBo|武曲|庙旺": "武曲入庙（辰戌丑未四墓宫尤旺）守财帛宫，财星本位发挥到极致，是真正的「财库厚实」之象，赚钱与守财能力双优，宜以实业或硬资产为核心配置。",
  "caiBo|武曲|落陷": "武曲落陷在财帛宫或三方，财星刚硬之气受压，财运起伏明显，赚钱辛苦且容易因刚硬作风错失合作。建议软化处事方式，以稳健保守为主，不宜激进扩张。",
  "mingGong|破军|庙旺": "破军入庙旺，变革创新的特质全开，行动力与开创力都在最佳状态，”走天下“的格局得以充分施展，英星入庙男命英武有威。",
  "mingGong|破军|落陷": "破军落陷，变革力减弱，开拓能力打折，行事更需谨慎规划，不宜轻易放弃稳定局面去追求变动，此时稳健积累比冒险突破更重要。",
  "mingGong|天相|落陷": "天相落陷，辅佐能力打折，位高但权轻的特质更为明显，需在专业能力上更加出色才能获得认可。",
  "mingGong|天相|庙旺": "天相庙旺，辅佐人才的特质全开，行政管理、法务秘书方向最能发挥，得到上司的信任与重用，是高平台中最可靠的人。",
  "caiBo|天府|庙旺": "天府庙旺（丑未巳亥宫尤吉）守财帛宫，南斗财库本位发挥到极致，是真正的「家财万贯，世代不衰」之象。最宜稳健长持的资产配置：核心地段不动产、蓝筹股、传家债券、艺术收藏，越守越有钱。",
  "mingGong|太阳|庙旺": "太阳入庙（寅至午宫），光明正大，事业财运俱佳，名利兼收，是太阳最佳发挥状态，公众影响力达到最高点。",
  "mingGong|太阳|落陷": "太阳落陷（酉至丑宫），劳而无获，付出多回报少，名誉难以积累。须换方向或环境，在能发光的平台上才能有所发挥，切忌固守不适合的岗位。",
  "fuQi|天机|落陷": "天机落陷在夫妻宫或三方，另一半的聪明灵活打折扣，可能显得犹豫不决、缺乏主见，或感情多变令人难以捉摸，需要更多包容与引导。",
  "fuQi|七杀|庙旺": "七杀庙旺在夫妻宫或三方，配偶同样强势果决，双方是势均力敌的伴侣，婚姻中竞争与磨合并存，但强强联合时成就感极高。",
  "guanLu|太阳|落陷": "太阳落陷在官禄宫或三方，职业上付出多回报少，在当前环境难以得到应有认可，宜主动换环境或方向，换一个能发光的平台。",
  "mingGong|廉贞|庙旺": "廉贞庙旺，文武才艺全开，桃花旺盛，社交魅力达到顶峰，感情运和社交运极好。",
  "mingGong|廉贞|落陷": "廉贞落陷，才艺与桃花打折，感情容易遇到不实的对象，官非风险增加，需提高辨别力。",
  "mingGong|天府|庙旺": "天府庙旺，守财能力达到最强，财库最为厚实，在政府机构、银行或大企业中表现最出色，稳重保守的特质在高平台上发光。",
  "jiE|太阳|落陷": "太阳落陷在疾厄宫或三方，眼睛要多留心。《全书》卷二疾厄太阳条说「陷宫亦主目疾欠光明」，也讲「左眼是太阳右眼是太阴呐」。每年查一次眼，少熬夜、少长时间盯屏幕，作息守规律，情绪别闷着。",
  "fuQi|破军|庙旺": "破军庙旺在夫妻宫或三方，配偶有独特个性，关系虽不平稳但充满激情，双方共同开创的经历反而是婚姻中最珍贵的财富。",
  "guanLu|紫微|落陷": "紫微落陷在官禄宫，事业上的贵气发挥有限，升职路上阻力较大，靠关系不如靠实力，建议在专业技能上深耕，以实绩换取地位。",
  "caiBo|太阴|落陷": "太阴落陷（卯辰巳午未宫）在财帛宫或三方，月光昏暗，富贵气质打折，财运不稳定且容易受情绪干扰。建议以稳健存储为主，少做高风险投资，待运势转佳再扩张。",
  "caiBo|太阴|庙旺": "太阴入庙（酉戌亥子丑宫，尤其亥子丑宫）守财帛宫，月光最圆最亮，富甲一方之象——田宅与不动产投资的能力达到最强，是14主星中房产财运最佳的状态，宜重资产配置。",
  "mingGong|太阴|落陷": "太阴落陷（卯辰巳午未宫），月亮减光，富贵气质减弱，情绪容易忧郁，财运尤其是田宅财运有所折扣，宜以积极的心态和行动弥补。",
  "mingGong|太阴|庙旺": "太阴入庙（酉戌亥子丑宫），月亮最圆最亮，富贵气质达到顶峰。女命此格为大富贵之象。",
  "mingGong|天梁|落陷": "天梁落陷，荫护力量减弱，逢凶化吉的特质打折，一生需多靠自身努力，减少对“好运”的依赖，主动积累专业实力。",
  "mingGong|天梁|庙旺": "天梁入庙旺，荫护力量全开，逢凶化吉的能力极强，一生有贵人守护，在危难中往往能化险为夷，宜从事权威型、服务型职业。",
  "mingGong|巨门|庙旺": "巨门庙旺，口才与辨析能力达到顶峰，在需要言辞表达的职业中最能发光，是非化为雄辩，化为生财工具。",
  "mingGong|巨门|落陷": "巨门落陷，口才打折，是非反而增多，容易被人误解，言辞需更加谨慎，多听少说。",
  "fuQi|天相|落陷": "天相落陷在夫妻宫或三方，另一半的忠厚可靠特质打折，可能稍显优柔寡断，需要你多些主动和担当。",
  "fuQi|天相|庙旺": "天相庙旺在夫妻宫或三方，配偶忠厚老实，可靠负责，是踏实的伴侣，婚姻基础扎实，生活稳定。"
}

STAR_SIHUA_DB: dict[str, str] = {
  "mingGong|贪狼|化忌": "贪狼化忌守命——「癸年生人贪狼化忌」，桃花变是非，感情欲望化为感情纠纷。多才艺变为多耗散，酒色财气赌的诱惑需格外节制。化忌年份要防意外桃花引发的困扰，感情中的是非会牵连其他生活领域。",
  "mingGong|贪狼|化禄": "贪狼化禄守命，桃花与财运双旺，多才艺，社交魅力极强——财来自广泛的人脉和多元的技能，越活跃越有财，是人脉生财的最佳格局。",
  "mingGong|贪狼|化权": "贪狼化权守命，欲望与掌控欲同步升级，事业上的主导意识极强，在商业或艺术领域能独当一面，创业欲旺盛。",
  "mingGong|武曲|化科": "武曲化科守命，财务方面有专业才能，宜从事财务规划、会计审计、技术工程领域，专业名声较好，以技艺换财是最稳定的财路。",
  "mingGong|武曲|化禄": "武曲化禄守命，财星得禄，是14主星中最强的大富格局——财来至旺，自己做生意或担任财务主管皆大吉，金融、工业、资产管理方向都能做出大成就。",
  "mingGong|武曲|化权": "武曲化权守命，掌财有道，财务管控能力极强，自己做老板的欲望和能力都达到最高点。宜自主创业或担任企业财务负责人，是创业的绝佳格局。",
  "mingGong|武曲|化忌": "武曲化忌守命，主刑伤破财（★ 校勘 2026-05-14：原作「刑囚之星」属廉贞专绑术语误用，已订正为《全书·武曲星论》正典）。手术、意外、官司风险高于常人，血光之灾需格外防范。财运受阻，容易因突发事件造成大额破财，建议购置充足的意外医疗保险。感情上孤克之气加重，婚姻需更用心维护。",
  "caiBo|廉贞|化禄": "廉贞化禄入财帛宫或三方，次桃花得禄，财来自人脉、才艺与人际关系——以创意、设计、美容、艺术、政治、餐饮等行业最易生财，靠个人魅力和社交圈带动收入。化禄时桃花化为助力，贵人多、合作机会多，是廉贞财运最甜美的状态。",
  "caiBo|廉贞|化忌": "廉贞化忌入财帛宫或三方，是14主星中最危险的财运配置之一——血光、官非、桃花纠纷三重风险叠加，财容易因感情纠葛、法律官司、意外手术大额流失。古诀云廉贞化忌主血光官非，化忌年份切忌涉及色情、赌博、灰色地带的财务往来，远离一切可能引发法律风险的合作。",
  "mingGong|天同|化禄": "天同化禄守命，福禄双美，是天同最理想的状态——生活顺遂安乐，衣食无忧，幸福感极强。财来自稳定的福禄，生活质量高，精神享受丰富。",
  "mingGong|天同|化权": "天同化权守命，本是最温和的星曜得到权力加持，在服务业或相关领域可独当一面，比普通天同命更有主见与决断力，是少见但有效的格局。",
  "mingGong|天同|化忌": "天同化忌守命，福德受损，生活顺遂感明显降低——原本应该「坐食天禄」的人，因化忌而享受不到该有的福分，感情多波折，生活中不顺心事增多，幸福感打折。宜主动调整心态，以积极进取弥补福分不足，同时特别注意肾脏与泌尿系统的健康。",
  "mingGong|天机|化禄": "天机化禄守命，以智慧生财，知识型或策划型的收入来源最为顺遂，财来自脑力和人脉——这是天机最理想的发挥状态，一生靠聪明才智赚钱，越动脑越有财。",
  "mingGong|天机|化权": "天机化权守命，原本善变多谋的特质化为强烈的掌控力，在策划或技术领域能独当一面，执行力比普通天机命强得多，但仍需防多变散乱。",
  "mingGong|天机|化科": "天机化科守命，才艺与学识转化为名声，文教或技术方向上成就显著，贵人提携多，考试运佳，专业声誉稳固。",
  "mingGong|天机|化忌": "天机化忌守命，多变焦虑的特质被放大到最强——古诀云「化忌主是非」，天机化忌的是非是思虑过多、决策失误带来的麻烦。感情多波折，神经系统承压，容易陷入反复纠结、难以决断的状态，需刻意练习”少想多做“，否则错失良机。",
  "fuQi|武曲|化禄": "武曲化禄，感情路顺遂——以行动和财富换取感情的稳定，另一半欣赏你的实力，婚姻因共同奋斗而稳固，财富基础是感情的最大支撑。",
  "fuQi|武曲|化忌": "武曲化忌，刑伤之气影响感情——婚姻中容易因金钱纠纷、意外事故或双方刚硬性格的冲突而产生裂痕。女命武曲化忌尤其需要警惕古书「寡宿」之说加化忌的双重压力，宜晚婚且婚前长期磨合。",
  "fuQi|紫微|化权": "紫微化权在夫妻宫（或三方有权），配偶主导欲极强，是那种家里说了算的类型——你们的关系中权力博弈明显，若双方都强势则争执不断，需要一方学会妥协。",
  "guanLu|破军|化禄": "破军化禄在官禄宫或三方，事业格局”破而后立“，每一次行业转换或创业都能带来更好的机会，靠开拓精神积累事业财富。",
  "caiBo|贪狼|化忌": "贪狼化忌在财帛宫或三方，桃花变烂桃花，偏财变破财——古诀云「贪狼化忌，财色两空」，最大风险是因酒色赌博、不当感情关系、虚荣消费而大额漏财。化忌年份切忌投机赌博和参与高风险娱乐场合的财务往来，远离一切「快钱」诱惑。",
  "caiBo|贪狼|化禄": "贪狼化禄在财帛宫或三方，桃花财与偏财同时启动，财来自人脉、才艺、社交场合的成交——餐饮、娱乐、酒店、夜店、美容、KTV、传媒等需要人气的行业最旺。逢火星或铃星更是「火贪格」「铃贪格」之首，偏财暴发概率倍增，典籍有专章论此格。",
  "caiBo|贪狼|化权": "贪狼化权在财帛宫或三方，欲望化为生财掌控力——能把社交圈、人脉、才艺组织成实质的商业版图，是天生的娱乐业老板、餐饮品牌创始人、销售总监格局。需自律消费，否则赚多花更多。",
  "mingGong|紫微|化科": "紫微化科守命，名声与学识双旺，在文教、专业领域或需要名誉背书的行业中格外出色。贵人运极好，往往能在关键时刻得到提携，一生名誉无瑕。",
  "mingGong|紫微|化权": "紫微化权守命，领导欲和掌控欲推至最强，天生适合独当一面、掌权做主。在仕途或企业高层中最能发挥，权威感无人能及，但需防过于独断而孤立。",
  "caiBo|武曲|化科": "武曲化科入财帛宫或三方，财星得科，专业理财之名声远播——以会计、审计、财务规划、技术工艺等专业能力换财，财来得稳且体面。化科虽不如化禄财量大，但口碑与声誉的累积是长期财运的护城河。",
  "caiBo|武曲|化禄": "武曲化禄入财帛宫或三方，财星化禄即「财星得禄」，是14主星中最强的大富格局——古赋言「武曲是财星」，化禄则财星再加禄，财源广进自然涌入，金融、实业、资产管理、房地产投资都是最旺财路。命中得此格局，宜大胆扩展事业版图，财富积累速度远超同辈。",
  "caiBo|武曲|化权": "武曲化权入财帛宫或三方，掌财之权——你天生具备做老板、当家做主管钱的能力，财务决策权牢牢握在自己手里。古诀云「武曲化权，当家立户」，宜自己创业或担任企业财务总监、CFO 类岗位，钱财调度的主导力是你最大的财富密码。",
  "caiBo|武曲|化忌": "武曲化忌入财帛宫或三方，主刑伤破财（★ 校勘：「刑囚」属廉贞专绑术语已订正），财来财去且常因突发事件破财，手术、官司、意外都是大额漏财源头。建议购置充足意外医疗保险，重大投资务必谨慎评估。化忌年份切忌冒险扩张或借贷投资。",
  "guanLu|天机|化禄": "天机化禄在官禄宫或三方，以知识和策划赚钱最顺，知识型创业或顾问服务方向是最佳出路，财来自脑力，越专业越有财。",
  "guanLu|天机|化忌": "天机化忌在官禄宫或三方，职业上的多变与失误风险增加，容易因决策过于善变而错失机会或与同事产生摩擦，宜专注一个领域，减少跳槽与方向切换。",
  "mingGong|破军|化禄": "破军化禄，”破而后立“的格局最佳，在打破旧有格局后能建立起新的财富与事业，化禄赋予破军开创力与财运的双重加持，是先苦后甜的上佳格局。",
  "mingGong|破军|化权": "破军化权，开拓力与控制力大增，在变革中有主导权，适合独立创业或带领团队打入新市场，是先锋者的权威格局。",
  "fuQi|廉贞|化禄": "廉贞化禄，感情桃花旺盛，异性缘极好，感情运顺遂，容易遇到多个追求者，婚姻机会增加。但需防桃花泛滥，在众多选择中保持清醒。",
  "fuQi|廉贞|化忌": "廉贞化忌，感情纠纷与血光风险并存——感情中容易遭遇不诚实的伴侣，或因感情纠葛引发争执甚至危及人身安全，感情路曲折。女命廉贞化忌更需注意，不要轻易陷入复杂的感情关系。",
  "guanLu|贪狼|化禄": "贪狼化禄在官禄宫或三方，多才艺转化为实际财路，靠技能和人脉生财，艺术、娱乐、商业方向皆宜，越活跃机会越多。",
  "mingGong|太阳|化忌": "太阳化忌守命，眼疾与名誉受损是双重风险——太阳化忌主眼目之灾，以及「劳而无获」的付出困境。这个格局意味着你的努力与认可之间容易出现落差，旁人看不到你的付出，或名誉受到无端损害。需格外注意用眼健康，同时调整心态接受「默默耕耘」的模式，落陷加忌则更须换方向。",
  "mingGong|太阳|化禄": "太阳化禄守命，名利双收，财从公众事务或社会声誉中来——这是太阳最理想的格局，阳光与财禄并进，名声越响亮收入越高，一生在公众场合大放异彩。",
  "mingGong|太阳|化权": "太阳化权守命，在公众事务或政务领域掌权，社会地位与话语权显著提升，是非常有力的事业格局，最适合政界或大型公众机构。",
  "fuQi|天同|化禄": "天同化禄，感情幸福感倍增，婚姻顺遂，另一半温柔体贴，双方生活和谐，是夫妻宫中最幸福的格局之一。",
  "fuQi|天同|化忌": "天同化忌影响感情，婚姻福分受损，感情多波折，生活中容易出现不和谐，双方幸福感下降。需主动为关系注入新鲜感，定期创造共同的美好体验。",
  "jiE|廉贞|化忌": "廉贞化忌在疾厄宫或三方，血光、手术和意外是头一号的健康警示。《全书》卷一廉贞条原文「遇刑忌则脓血不免」：化忌之外再见擎羊或天刑，开刀见血这一关躲不过，外伤和手术都要提早防。",
  "fuQi|天机|化禄": "天机化禄影响感情线，感情因智慧与沟通而顺遂，另一半聪慧能干，两人有共同话题与智识上的吸引，感情路因脑力相通而顺畅。",
  "fuQi|天机|化忌": "天机化忌影响感情线，感情中的是非来自多变与不稳定——你或另一半可能反复无常，感情分分合合，思虑过多而无法安心投入。需要刻意建立信任感和稳定性，否则感情难以长久。",
  "guanLu|太阳|化忌": "太阳化忌在官禄宫或三方，职业中名誉受损是最大风险，可能遭遇无端是非或升职受阻，宜低调务实，以实绩说话，避免正面与权威冲突。",
  "guanLu|太阳|化禄": "太阳化禄在官禄宫或三方，名利双收，职业上的公众曝光度直接转化为收入，知名度越高机会越多，最适合有名气加持的职业方向。",
  "mingGong|廉贞|化禄": "廉贞化禄守命，次桃花得禄，感情桃花旺盛，多才艺，社交能力极强，财来自人际与感情资源的转化，是非常活跃的命格。",
  "mingGong|廉贞|化忌": "廉贞化忌守命，血光、官司、感情纠纷是三大风险——命理推断廉贞化忌为「桃花星化忌」（桃花劫、因情色惹祸），血光官非则属传统之说。一生中要防无端招惹的是非，感情上需格外谨慎，避免感情纠葛引发的官司或人身安全问题。化忌年份尤须低调，远离是非圈。",
  "jiE|天机|化忌": "天机化忌在疾厄宫或三方，思虑更重、更容易想不开，睡眠最先受影响。压力要主动疏解，作息守住；哪个脏腑要留意，仍看全盘杀星最集中那一宫的地支。",
  "guanLu|巨门|化忌": "巨门化忌在官禄宫或三方，职场口舌是非多，需特别注意言辞不当引发的职业危机，建议从事相对独立的工作，减少不必要的争论。",
  "guanLu|巨门|化禄": "巨门化禄在官禄宫或三方，以口才生财，律师、教师、传媒、销售、培训方向最顺遂，越能言善道越有财。",
  "jiE|太阳|化忌": "太阳化忌在疾厄宫或三方，眼睛是要盯住的地方。每年做一次眼科检查，少对着强光、少长时间盯屏幕。《全书》卷二疾厄太阳条原文：「太阳头风，太阴同加化忌，羊陀主眼目有伤，陷宫亦主目疾欠光明。」疾厄宫里太阳、太阴同宫，化忌再加羊陀，就是这句说的眼目有伤。",
  "fuQi|破军|化禄": "破军化禄在感情宫位或三方，感情经历波折后终能破而后立，有第二春或在感情中得到物质方面的滋润，婚后生活逐渐改善。",
  "caiBo|太阴|化科": "太阴化科在财帛宫或三方，财以文教、艺术、设计、心理咨询等温柔细腻的专业领域为来源，靠美感与情感价值赚钱——女命此格的财路常带有审美属性，如美容、室内设计、女性消费品；财来得有品味，名声与积累并重。",
  "caiBo|太阴|化忌": "太阴化忌在财帛宫或三方，田宅财运受损，房产投资需谨慎，情绪化的财务决策是最大漏财点。古诀云「太阴化忌，月主忧愁」——常因感情忧愁、家庭矛盾连带影响财运，男命化忌还要警惕婆媳/妻母财务纠纷。宜保守稳健，避免在情绪低落时做重大财务决定。",
  "caiBo|太阴|化禄": "太阴化禄在财帛宫或三方，田宅房产财运最旺，投资房产是最理想的财路。古诀云「太阴主富」，化禄则月光皎洁聚财，女命此格大富之象，钱来钱顺，财库越积越厚。",
  "caiBo|太阴|化权": "太阴化权在财帛宫或三方，田宅与不动产掌控力极强，自己做地产投资、收租、做包租公（婆）的格局——女命此格则是家中财政的最高决策者，男命此格则借妻力掌财，以稳健的资产配置为主轴，不善炒作但善长持。",
  "mingGong|太阴|化科": "太阴化科守命，文艺才华与感性智慧并重，在艺术、教育、文化领域有专业名声，温柔中带着学识的气质令人印象深刻。",
  "mingGong|太阴|化忌": "太阴化忌守命——对男命来说，这是专门警告的配置：「男人的命啊，太阴化忌的人呐，最怕太阴化忌就是这样婆媳不和，太太跟妈妈一定不和的」。妻母关系是最大的家庭困境，需格外用心处理。对女命，太阴化忌主情绪抑郁、感情忧愁，容易陷入内心世界无法自拔，田宅财运也受影响，宜主动出门社交、多接触阳光。此外，太阴主母，特别强调太阴化忌须分庙陷断母缘：**落陷化忌**者母缘偏薄，命理推断「妈妈会比较早走」，宜多珍惜相处；**入庙化忌**则不作此论，反主母女感情特别好，仅多为你操心。",
  "mingGong|太阴|化禄": "太阴化禄守命，月亮得禄，财运最旺——尤其女命此格局为大富之象，田宅财帛皆旺，房产投资是最佳财路。",
  "mingGong|太阴|化权": "太阴化权守命，情感敏锐转化为极强的掌控力，在需要细腻判断的领域（理财、艺术、教育）有超群能力。女命化权则在家或职场都是说了算的人。",
  "fuQi|天梁|化科": "天梁化科在感情宫位，感情中因名声或学识而吸引对象，伴侣注重文化品味，共同话题多在学识、精神层面。",
  "fuQi|天梁|化禄": "天梁化禄在感情宫位或三方，感情较顺，配偶可能有一定的学识或权威背景，婚姻生活有稳定的物质基础。",
  "mingGong|天梁|化权": "天梁化权，在专业领域权威大增，学识与执行力合一，是一方权威，受人尊重与信赖，领导力格局显现。",
  "mingGong|天梁|化科": "天梁化科，学识名声兼备，专业声誉远播，是学术研究、专业咨询领域的理想格局，靠名声吸引机会。",
  "mingGong|天梁|化禄": "天梁化禄，因学识或服务他人而获得财禄，人生逢凶化吉的格局进一步加强，宜助人而自助，事业与口碑双丰收。",
  "fuQi|贪狼|化忌": "贪狼化忌，桃花变是非——感情中容易遭遇不靠谱的对象，或因感情关系引发各种麻烦和纠纷，需格外谨慎择偶，防止感情误入歧途。",
  "fuQi|贪狼|化禄": "贪狼化禄，桃花大旺，感情机会多，异性缘极佳，容易遇到多个意向对象——关键是在众多选择中找到真正匹配的，而不是在桃花中迷失。",
  "guanLu|武曲|化禄": "武曲化禄在官禄宫或三方，财路大开；禄在官禄，可指职位上管理公家或机构的钱财，掌财不等于钱归自己。",
  "guanLu|武曲|化忌": "武曲化忌在官禄宫或三方，职场风波多——可能遭遇官司、被裁或与上级发生激烈冲突，血光和意外事件影响工作，化忌年份尤须低调，防突发变故。",
  "mingGong|巨门|化权": "巨门化权守命，口才与是非转化为话语权，在辩论、司法、传媒、政治领域能发挥最大影响力，说话的力量极强。",
  "mingGong|巨门|化忌": "巨门化忌守命，口舌是非最重——巨门在朋友宫「跟朋友合伙会朋友变仇人」，化忌则是非加倍。言语纠纷、官司口舌是最大的人生困扰，需时刻谨言慎行，切忌多嘴惹祸。社交圈的是非会持续消耗精力，宜减少不必要的争论。",
  "mingGong|巨门|化禄": "巨门化禄守命，口才生财——以言辞、沟通和表达换取收入，是律师、教师、传媒、演讲、销售的绝佳格局。原本是非之星化禄后，口才成为最大的财路。",
  "fuQi|巨门|化忌": "巨门化忌，感情中的是非口角是最大隐患——容易因说错话、误解或口舌争执而伤感情。需在亲密关系中刻意克制批评和争辩的冲动，多倾听少反驳。",
  "fuQi|巨门|化禄": "巨门化禄，口才在感情中转化为魅力，沟通能力强是感情最大优势，另一半欣赏你的表达，感情中话语的温度决定关系的质量。",
  "jiE|天同|化忌": "天同化忌在疾厄宫或三方，图安逸、不爱动的毛病被放大，体重和血糖最先出状况。养成规律运动习惯，每年体检把这两项盯住；哪个脏腑要留意，看全盘杀星最集中那一宫的地支。",
  "jiE|武曲|化忌": "武曲化忌在疾厄宫或三方，手术、刀伤和磕碰外伤要当心。化忌那一年前后，开车、登高、动刀动机器都放慢，安全放第一。哪个脏腑要留意，看全盘杀星最集中那一宫的地支。"
}

SECOND_STAR_DESC_DB: dict[str, str] = {
  "天府": "南斗令星、财库星，稳重保守，善理财，逢禄存武曲聚财大；单独一颗不论解厄；宜政府银行大企业。",
  "巨门": "是非口才星，善辩论，宜律师教师传媒；庙旺灾减、转能言善道。化忌口舌官非。",
  "天梁": "荫星寿星，主庇护与长辈缘，宜法律医学教育；《全书》说「要入庙方富贵，陷地遇火羊破局，则下贱孤寡夭折」。",
  "天相": "印星辅佐，忠厚老实，位高权轻，宜行政秘书法务，守成为上。",
  "破军": "耗星，主破旧立新，性孤僻、不重利；陷地加煞主弃祖离宗。化禄破而后立。",
  "贪狼": "主桃花星（：落亥、子才是正科桃花，在午按武官星看，不要随便批桃花），多才艺社交，早年虚华晚年成就，逢火铃偏财暴发。",
  "七杀": "将星，孤独果决冒险，宜军警创业，七杀朝斗格则武职大贵。",
  "太阴": "月亮富贵星，感情细腻，入庙富贵、女命入庙尤佳，主田宅房产。"
}

